// Generated by scripts/gen-l10n.mjs (gdetail n5, ko) — 不要手改;改翻譯請改 scripts/out/l10n/ko/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["ko"]=Object.assign(window.GRAMMAR_DETAIL_L10N["ko"]||{},{"n5-51":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어는 「주다」 하나로 말하지만(드리다·받다 같은 말도 있지만요), 일본어는 <b>물건이 어느 방향으로 가는지</b>를 봐요. 내 쪽에서 <b>나가는</b> 경우는 <span class='gd-jp'>あげます</span>, 다른 사람 쪽에서 <b>나에게 들어오는</b> 경우는 <span class='gd-jp'>くれます</span>, 내 입장에서 「내가 <b>받았다</b>」라고 말할 때는 <span class='gd-jp'>もらいます</span>를 써요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>あげます</span>나(또는 우리 쪽 사람)가 다른 사람에게 줘요. 물건이 밖으로 나가요. 남이 남에게 줄 때도 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に誕生日プレゼントをあげました。</span>(친구에게 생일 선물을 줬어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは山田さんに花をあげました。</span>(다나카 씨는 야마다 씨에게 꽃을 줬어요)</div><div class='gd-sec'><span class='gd-tag'>くれます</span>다른 사람이 <b>나</b>에게, 또는 <b>우리 가족</b>에게 줘요. 물건이 내 쪽으로 들어와요. 「나에게」는 보통 말하지 않아도 일본 사람은 바로 알아들어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>母が時計をくれました。</span>(어머니가 시계를 주셨어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が妹にお菓子をくれました。</span>(친구가 제 여동생에게 과자를 줬어요)</div><div class='gd-sec'><span class='gd-tag'>もらいます</span>받는 사람 입장에서 「받았다, 얻었다」라고 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生から手紙をもらいました。</span>(선생님께 편지를 받았어요)</div><div class='gd-h'>어떻게 이어요</div><div class='gd-sec'>세 문장 모두 「누가, 누구에게, 무엇을」 구조인데, <b>누가 주인공인지</b>가 달라요.<br><b>あげます</b>: 주는 사람<span class='gd-jp'>は</span>　받는 사람<span class='gd-jp'>に</span>　물건<span class='gd-jp'>を</span>　<span class='gd-jp'>あげます</span><br><b>くれます</b>: 주는 사람<span class='gd-jp'>が</span>　(나<span class='gd-jp'>に</span>)　물건<span class='gd-jp'>を</span>　<span class='gd-jp'>くれます</span><br><b>もらいます</b>: 나<span class='gd-jp'>は</span>　주는 사람<span class='gd-jp'>に</span>／<span class='gd-jp'>から</span>　물건<span class='gd-jp'>を</span>　<span class='gd-jp'>もらいます</span><br>과거형은 똑같이 ます를 ました로 바꿔요: <span class='gd-pair'><span class='gd-jp'>くれます</span> → <span class='gd-jp'>くれました</span></span></div><div class='gd-h'>헷갈리기 쉬운 표현과 구분하기</div><div class='gd-sec'>같은 상황이에요: <b>친구가 나에게 책을 한 권 줬다</b>.<br>・<span class='gd-jp'>友達が本をくれました。</span>(친구가 책을 줬어요) 주인공은 친구이고, 책이 내 쪽으로 와요.<br>・<span class='gd-jp'>友達に本をもらいました。</span>(친구에게 책을 받았어요) 주인공은 나이고, 내가 받아요.<br>이 두 문장은 뜻이 같아서 둘 다 쓸 수 있어요.<br>・<span class='gd-jp'>友達が私に本をあげました。</span>　이 문장은 <b>틀려요</b>. あげます는 「나에게 주다」에는 쓸 수 없어요.<br><br>반대로 <b>내가 친구에게 책을 준</b> 경우에는 이렇게만 말해요.<br>・<span class='gd-jp'>友達に本をあげました。</span>(친구에게 책을 줬어요)</div><div class='gd-warn'>판단 요령: 먼저 「물건이 내 쪽으로 오나?」를 자신에게 물어보세요. 그렇다면 くれます나 もらいます를 쓰고, 밖으로 나가면 あげます를 써요.</div><div class='gd-h'>자주 하는 실수</div><div class='gd-warn'>・한국어 「어머니가 (나에게) 줬다」를 그대로 옮겨서 <span class='gd-jp'>母があげました</span>라고 쓰는 경우가 많은데, 틀려요. 나나 우리 가족에게 주는 경우는 무조건 <b>くれます</b>예요.<br>・くれます의 주인공은 「나」가 될 수 없어요. <span class='gd-jp'>私が友達にくれました</span>는 틀린 문장이고, <span class='gd-jp'>友達にあげました</span>라고 해야 해요.<br>・もらいます 앞의 <span class='gd-jp'>に</span>는 「<b>~에게서</b>」라는 뜻이지 「~에게(주다)」가 아니에요. <span class='gd-jp'>友達にもらいました</span>는 「친구에게서 받았다」이고, 「친구에게 줬다」가 아니에요. 헷갈리면 <span class='gd-jp'>から</span>로 바꿔 쓰세요. 뜻은 같아요.<br>・가족은 「내 쪽 사람」으로 치기 때문에, 친구가 여동생에게 물건을 줄 때도 くれます를 써요.<br>・선생님이나 상사에게 줄 때 그냥 あげます라고 하면 조금 거만하게 들려요. 나중에 더 공손한 표현을 배울 거예요.<br>・가끔 <span class='gd-jp'>花に水をやります</span>(꽃에 물을 줘요)라는 말을 듣게 되는데, やります는 동물이나 식물에게 줄 때 써요. 사람에게 やります라고 하면 좀 거칠게 들리니까 처음에는 あげます만 쓰면 돼요.</div><div class='gd-h'>다 익히고 나면 이어서 배워요</div><div class='gd-sec'>N4에 가면 이 세 동사가 て형 뒤에 붙어서 「다른 사람을 위해 해 주는 행동」을 나타내요. <span class='gd-jp'>友達が駅まで送ってくれました。</span>(친구가 역까지 데려다줬어요) 방향을 판단하는 법은 여기서 배운 것과 완전히 같아요. 지금 확실히 구분해 두면 나중에 아주 편해요.</div>","n5-58":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>「〜ながら」는 한국어의 <b>「~(으)면서」</b>예요. 그런데 일본어에는 습관이 하나 있어요. <b>더 중요한 일을 뒤에 둔다</b>는 거예요. 예를 들어 '음악을 들으면서 공부해요'에서는 주로 공부를 하는 거고 음악은 곁들이일 뿐이니까, 일본어로는 <span class='gd-jp'>音楽を聞きながら勉強します。</span>라고 해요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>동사를 먼저 ます형으로 바꾸고, <b>「ます」를 떼고</b> 바로 「ながら」를 붙여요. 세 종류의 동사 모두 똑같아요.<br><span class='gd-pair'><span class='gd-jp'>聞きます</span> → ます를 뗌 → <span class='gd-jp'>聞きながら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べながら</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見ながら</span></span><span class='gd-pair'><span class='gd-jp'>運転します</span> → <span class='gd-jp'>運転しながら</span></span><br>뒤에는 주된 동작을 이어요. 「ながら」 자체는 <b>절대 변하지 않아요</b>. 과거, 부정, 공손한 표현은 모두 맨 마지막 동사가 맡아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>歌を歌いながら、料理しました。</span>(노래를 부르면서 요리했어요)</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>같은 시간에 두 가지 하기</span>손은 이걸 하면서, 동시에 저것도 하고 있을 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビを見ながら、ご飯を食べます。</span>(TV를 보면서 밥을 먹어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>歩きながらスマホを見るのは危ないです。</span>(걸으면서 스마트폰을 보는 건 위험해요)</div><div class='gd-sec'><span class='gd-tag'>이 기간에 두 가지를 다 하기</span>꼭 같은 순간이 아니어도 돼요. 요즘 두 가지를 병행하는 경우에도 써요. '일과 공부를 병행한다'는 느낌이죠.</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトをしながら、日本語を勉強しています。</span>(아르바이트를 하면서 일본어를 공부하고 있어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・붙이는 건 <b>ます형에서 ます를 뗀 형태</b>예요. 원형이 아니에요. <span class='gd-jp'>聞きながら</span>가 맞고 「聞くながら」는 틀려요. <span class='gd-jp'>食べながら</span>가 맞고 「食べるながら」는 틀려요.<br>・앞뒤 두 가지 일은 반드시 <b>같은 사람</b>이 해야 해요. '엄마가 밥을 하는 동안 나는 TV를 보고 있었다'는 두 사람이 하는 일이니까 ながら를 쓸 수 없고, 「とき」를 써야 해요. <span class='gd-jp'>母が料理をしているとき、私はテレビを見ていました。</span><br>・한국어 느낌대로 앞뒤를 마음대로 바꾸면 안 돼요. 한국어에서는 'A하면서 B해요'의 앞뒤를 바꿔도 크게 다르지 않게 들리지만, 일본어는 <b>뒤에 오는 쪽이 주인공</b>이에요. <span class='gd-jp'>勉強しながら音楽を聞きます</span>라고 하면 '주로 음악을 듣고, 겸사겸사 공부한다'는 뜻으로 들려요.<br>・과거나 공손한 표현은 마지막 동사만 바꿔요. ながら 앞에 ました를 붙이면 안 돼요. 「聞きましたながら」는 틀리고, <span class='gd-jp'>聞きながら勉強しました</span>라고 해야 해요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'><b>て형 연결</b>＝한 가지를 끝낸 <b>다음에</b> 다음 일을 해요. 순서가 있어요.<br><b>ながら</b>＝두 가지를 <b>동시에</b> 해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べて、テレビを見ます。</span>(밥을 먹고 나서 TV를 봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べながら、テレビを見ます。</span>(밥을 먹으면서 TV를 봐요)</div><div class='gd-sec'><b>〜たり〜たりします</b>＝한 일들을 예로 들어 말하는 거예요. 동시에 하는 게 아니에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は本を読んだり、映画を見たりします。</span>(주말에는 책을 읽기도 하고 영화를 보기도 해요)</div><div class='gd-warn'>구분 요령: 동시에 하면 ながら, 끝내고 나서 하면 て형, 한 일들을 아무거나 예로 들면 たり〜たり예요.</div>","n5-56":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>「〜たり〜たりします」는 한국어의 <b>'책을 읽기도 하고 영화를 보기도 해요'</b> 같은 표현이에요. 여러 일 중에서 두세 가지를 예로 골라 말하는 거라서, '예를 든 것뿐이고 다른 것도 해요'라는 뜻이 돼요. 두 번째 용법도 있어요. <b>'이랬다저랬다'</b>예요. 한국어의 '더웠다 추웠다 해요', '내렸다 그쳤다 해요'와 같아요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>예 들기</span>누가 평소에 뭘 하는지 물어보면, 전부 말할 필요 없이 대표적인 것 몇 가지만 말하면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日は、本を読んだり映画を見たりします。</span>(쉬는 날에는 책을 읽기도 하고 영화를 보기도 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除したり、買い物に行ったりします。</span>(주말에는 청소를 하기도 하고 장을 보러 가기도 해요)</div><div class='gd-sec'><span class='gd-tag'>이랬다저랬다</span>서로 반대되는 동작이나 상태가 번갈아 나타나요.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、暑かったり寒かったりします。</span>(요즘 더웠다 추웠다 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は雨が降ったりやんだりしています。</span>(오늘은 비가 내렸다 그쳤다 해요)</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>세 단계예요. <b>동사를 먼저 た형으로 바꾸고 → 뒤에 り를 붙이고 → 마지막에 します를 붙여요</b>.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだり</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったり</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たり</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たり</span></span><br>た형이 아직 익숙하지 않다면 <b>て형의 「て」를 「た」로, 「で」를 「だ」로 바꾼다</b>고 생각하면 돼요.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>い형용사</b>: 「い」를 떼고 「かったり」로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かったり</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったり</span></span>(<span class='gd-jp'>いい</span>는 <span class='gd-jp'>よかったり</span>로 바뀌어요)<br><b>명사, な형용사</b>: 뒤에 「だったり」를 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ごはんはパンだったりご飯だったりします。</span>(아침은 빵을 먹을 때도 있고 밥을 먹을 때도 있어요)</div><div class='gd-sec'>과거나 공손함의 정도는 모두 <b>맨 마지막의 する</b>가 맡아서 바꿔요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は友達と話したり、ゲームをしたりしました。</span>(어제는 친구와 이야기도 하고 게임도 했어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家で寝たり、テレビを見たりする。</span>(주말에는 집에서 자기도 하고 TV를 보기도 해: 친구에게 하는 말투)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・붙이는 건 <b>た형</b>이에요. ます형이 아니에요. <span class='gd-jp'>行ったり</span>가 맞고 行きたり는 틀려요. <span class='gd-jp'>読んだり</span>가 맞고 読みたり는 틀려요.<br>・문장 끝의 <span class='gd-jp'>します</span>(또는 <span class='gd-jp'>する</span>)를 빠뜨리면 안 돼요. 없으면 말이 끝나지 않은 것처럼 들려요.<br>・과거형은 맨 끝만 바꿔요. <span class='gd-jp'>行ったりしました</span>가 맞고 行きましたり라고는 하지 않아요.<br>・동작이 둘 이상이면 하나하나 뒤에 たり를 붙여야 해요. 회화에서는 두 번째 たり를 생략하는 경우도 가끔 들리지만, 시험이나 글쓰기에서는 빠짐없이 써야 해요. 한 가지만 예로 들어도 괜찮아요. 예를 들면 <span class='gd-jp'>映画を見たりします</span>(영화를 보기도 해요)처럼요.<br>・たり는 <b>순서를 나타내지 않아요</b>. 'A를 하고 나서 B를 한다'고 말하고 싶다면 て형을 써야 해요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 '어제 한 일'을 말하는 경우를 비교해 볼게요.<br><b>て</b>＝순서대로 말하고, 딱 그 일들만 했어요. <span class='gd-jp'>昨日は本を読んで、映画を見ました。</span>(어제는 책을 읽고, 그다음에 영화를 봤어요)<br><b>たり</b>＝몇 가지를 예로 들고, 다른 일도 있어요. 순서는 상관없어요. <span class='gd-jp'>昨日は本を読んだり、映画を見たりしました。</span>(어제는 책을 읽기도 하고 영화를 보기도 했어요)<br><b>や</b>＝역시 예를 드는 건데, 이어 주는 건 <b>물건(명사)</b>이에요. <span class='gd-jp'>昨日は本や漫画を読みました。</span>(어제는 책이나 만화 같은 걸 읽었어요)</div><div class='gd-warn'>구분 요령: 순서대로 다 말할 때는 「て」, 몇 가지 <b>동작</b>을 예로 들 때는 「たり」, 몇 가지 <b>물건</b>을 예로 들 때는 「や」를 써요.</div>","n5-15":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「は」는 한국어의 '은/는'과 아주 비슷해요. <b>「～로 말하자면, …」</b>이라는 느낌이에요. 이야기할 대상을 문장 맨 앞에 놓고 상대에게 \"지금 이 얘기를 할게요\" 하고 알린 다음, 뒤에서 그것이 어떤지 말해요. <span class='gd-jp'>私は学生です。</span>는 \"저로 말하자면 학생이에요\", 즉 \"저는 학생이에요\"라는 뜻이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>명사 뒤에 は만 붙이면 돼요.<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私は</span></span><span class='gd-pair'><span class='gd-jp'>伊藤さん</span> → <span class='gd-jp'>伊藤さんは</span></span><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日は</span></span><br><b>읽는 법이 중요해요</b>: 조사로 쓸 때는 <span class='gd-jp'>は</span>라고 쓰지만 <b>wa</b>로 읽어요. <span class='gd-jp'>わ</span>와 발음이 같아요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>소개, 설명</span>가장 기본적인 쓰임이에요. 먼저 \"누구/무엇\"을 말하고, 그다음에 \"어떠한지\"를 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>伊藤さんは建築家です。</span>(이토 씨는 건축가예요.)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑いですね。</span>(오늘은 덥네요.)</div><div class='gd-sec'><span class='gd-tag'>먼저 주제, 그다음 세부 내용</span>は 앞에는 \"이 문장이 무엇에 대한 이야기인지\"를 놓고, 뒤에는 또 다른 주인공이 나올 수 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>象は鼻が長いです。</span>(코끼리는 코가 길어요.)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのケーキは姉が焼きました。</span>(그 케이크는 누나(언니)가 구웠어요.)</div><div class='gd-sec'>두 번째 문장에서 많이 막혀요. 케이크를 구운 사람은 누나(언니)이지 케이크가 아니니까요. 그래서 <b>は 앞에 오는 말이 꼭 \"동작을 한 사람\"은 아니에요</b>. 단지 \"이 문장이 무엇에 대한 이야기인지\"를 말할 뿐이에요. 이 문장은 케이크 이야기를 꺼내고, \"누나(언니)가 구웠다\"를 덧붙인 거예요.</div><div class='gd-sec'><span class='gd-tag'>두 가지 비교하기</span>양쪽에 모두 は를 쓰면 \"이건 이런데, 저건 달라요\" 하는 대비의 느낌이 생겨요.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーは好きですが、お茶はあまり飲みません。</span>(커피는 좋아하지만, 차는 별로 안 마셔요.)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・조사 は는 wa로 읽어요. 인사말 <span class='gd-jp'>こんにちは</span>, <span class='gd-jp'>こんばんは</span>의 마지막 は도 wa로 읽어요. 그 밖의 단어 속 は는 그대로 ha로 읽어요. <span class='gd-jp'>はい</span>, <span class='gd-jp'>花</span>처럼요.<br>・「誰」「どれ」 같은 의문사가 문장의 주인공이 되어 질문할 때는 뒤에 は가 아니라 が를 써야 해요. <span class='gd-jp'>誰は来ましたか</span>는 틀린 문장이고, <span class='gd-jp'>誰が来ましたか</span>(누가 왔어요?)라고 말해야 해요.<br>・주제는 한 번 말하면 뒤에서는 생략할 수 있어요. 한국어에서도 \"저는\"을 매번 말하지 않죠? 일본어도 마찬가지로 <span class='gd-jp'>私は</span>를 한 번 말한 뒤에는 보통 반복하지 않아요. 계속 말하면 오히려 장황해요. <span class='gd-jp'>私は陳です。台湾から来ました。</span>(저는 천이에요. 대만에서 왔어요.)</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>は와 が가 가장 헷갈려요. 같은 장면으로 볼게요. 회사에 신입 직원이 왔어요.<br>아직 아무도 당신을 모르니 자기소개를 해요. <span class='gd-jp'>私は陳です。</span>(저는 천이에요.) → 사람들이 알고 싶은 건 <b>뒤</b>의 \"천\"이에요.<br>누군가 당신을 찾아요. <span class='gd-jp'>陳さんはどちらですか。</span>(천 씨는 어느 분이세요?) 당신이 손을 들고 말해요. <span class='gd-jp'>私が陳です。</span>(제가 천이에요.) → 이때 중요한 건 <b>앞</b>의 \"저\"예요.<br>또 방금 눈앞에서 보거나 일어난 일에도 が를 써요. <span class='gd-jp'>あ、バスが来ました。</span>(아, 버스가 왔어요.)</div><div class='gd-warn'>판단 요령: は를 쓰면 중점은 <b>は의 뒤</b>에 있고, が를 쓰면 중점은 <b>が의 앞</b>에 있어요. \"누구? 어느 것?\"에 대한 대답이나 방금 본 일에는 が를 써요.</div><div class='gd-h'>배운 뒤에 이어서 배우기</div><div class='gd-sec'>は를 <b>も</b>로 바꾸면 \"~도\"가 돼요. <span class='gd-jp'>私も学生です。</span>(저도 학생이에요.) 겹쳐 쓰는 게 아니라 그대로 바꾸는 거예요. \"私はも\"라는 말은 없어요.</div>","n5-34":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「が」는 손가락으로 가리키며 <b>\"바로 그거예요!\"</b> 하고 말하는 것과 같아요. 어떤 일을 <b>누가</b> 했는지, <b>무엇이</b> 일어났는지처럼 그 주인공을 콕 집어낼 때 뒤에 が를 써요.<br>예를 들어 누가 \"누가 왔어요?\" 하고 물으면 \"다나카 씨가 왔어요\"라고 대답하죠. 이 \"다나카 씨\"가 집어낸 답이라서 <span class='gd-jp'>田中さんが来ました</span>라고 해요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>명사 뒤에 が를 그대로 붙이면 돼요. 형태가 변하지 않아요.<br><span class='gd-jp'>私が</span>, <span class='gd-jp'>雨が</span>, <span class='gd-jp'>田中さんが</span>, <span class='gd-jp'>誰が</span>, <span class='gd-jp'>何が</span></div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>누구, 무엇을 물을 때</span>\"누구\", \"무엇\"이 문장의 주인공일 때는 질문에도 が를 쓰고, 대답에도 が를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ましたか。</span>(누가 왔어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来ました。</span>(다나카 씨가 왔어요.)</div><div class='gd-ex-line'>・<span class='gd-jp'>何が一番おいしいですか。</span>(무엇이 제일 맛있어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンが一番おいしいです。</span>(이 라멘이 제일 맛있어요.)</div><div class='gd-sec'><span class='gd-tag'>눈앞에서 보이는 일</span>방금 보거나 방금 일어난 상황을 그대로 장면처럼 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、バスが来ました。</span>(아, 버스가 왔어요.)</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降っています。</span>(눈이 내리고 있어요.)</div><div class='gd-sec'><span class='gd-tag'>처음 언급할 때</span>상대가 아직 모르는 사람이나 일을 처음 꺼낼 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、友達が家に来ました。</span>(어제 친구가 우리 집에 왔어요.)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>\"누구, 무엇, 어디\" 뒤에는 は를 쓸 수 없어요</b>. <span class='gd-jp'>誰は来ましたか</span>는 틀린 문장이고, <span class='gd-jp'>誰が来ましたか</span>라고 해야 해요. 다른 의문사도 마찬가지예요. 예를 들어 <span class='gd-jp'>どこが痛いですか</span>(어디가 아파요?)처럼요.<br>・<b>が로 물으면 が로 대답해요</b>. 누가 <span class='gd-jp'>誰が作りましたか</span>(누가 만들었어요?)라고 물으면 <span class='gd-jp'>私が作りました</span>(제가 만들었어요)라고 답해야 해요. \"私は作りました\"라고 답하면 \"저는 만들긴 했는데요\" 같은 느낌이 되어 어색하게 들려요.<br>・한국어 화자는 '은/는'에 익숙해서 모든 문장의 주어에 は를 붙이기 쉬워요. 하지만 창밖에서 갑자기 비가 오는 걸 봤다면 <span class='gd-jp'>あ、雨が降っています</span>라고 해야 해요. 눈앞의 장면을 그대로 말하는 문장에는 が가 자연스러워요.<br>・<span class='gd-jp'>日本語が好きです</span>, <span class='gd-jp'>ピアノができます</span>에도 が를 쓰지만, 그건 \"무엇을 좋아하는지, 무엇을 할 수 있는지\"를 나타내는 쓰임이에요. 다른 카드 「助詞が（能力・好惡）」에서 설명하니 지금은 섞어서 생각하지 마세요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'><b>は</b>는 \"～로 말하자면\"이에요. 먼저 화제를 꺼내고, <b>중점은 뒤</b>에 있어요.<br><b>が</b>는 \"바로 ～가\"예요. <b>중점은 앞에 있는 이 명사</b>에 있어요.<br><br>같은 \"제가 다나카예요\"라도:<br>자기소개에서는 <span class='gd-jp'>私は田中です。</span>(저는 다나카예요.)라고 해요. 이때 사람들은 \"내가 누구인지\"를 듣고 있어요.<br>누군가 <span class='gd-jp'>田中さんはどの人ですか。</span>(다나카 씨는 어느 분이세요?)라고 물으면 <span class='gd-jp'>私が田中です。</span>(제가 다나카예요.)라고 말해요. 이때는 여러 사람 중에서 다나카를 집어내는 거예요.<br><br>같은 \"다나카 씨가 왔다\"라도:<br><span class='gd-jp'>田中さんが来ました。</span>(다나카 씨가 왔어요.) 누가 왔는지 단순히 알리는 말이에요.<br><span class='gd-jp'>田中さんは来ました。</span>(다나카 씨는 왔어요.) 다나카를 먼저 화제로 삼아서, \"다른 사람은 모르겠지만\"이라는 뉘앙스가 있어요.</div><div class='gd-warn'>판단 요령: \"누구인지, 무엇인지\"에 답하려면 が를, \"이 사람, 이 물건이 어떤지\"를 말하려면 は를 써요. 의문사가 주인공일 때는 뒤에 항상 が를 써요.</div><div class='gd-h'>배운 뒤에 이어서 배우기</div><div class='gd-sec'>\"어디에 무엇이 있다\"에도 が를 써요. <span class='gd-jp'>あそこに猫がいます。</span>(저기에 고양이가 있어요.) 이어서 존재 표현, 그리고 \"좋아하다, 할 수 있다\"에 が를 쓰는 표현도 배워 보세요.</div>","n5-38":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「だけ」와 「しか」는 둘 다 ‘만, 뿐’이라는 뜻이에요. <b>だけ</b>는 한국어의 ‘~만’처럼 범위만 담담하게 말해요. <b>しか〜ません</b>은 ‘~밖에 없다’에 가까워서 <b>‘너무 적다, 부족하다’</b>는 느낌이 담겨요. 가장 큰 특징은 <b>しか 뒤에는 반드시 부정형이 온다</b>는 거예요. 한국어의 ‘~밖에’ 뒤에 부정이 오는 것과 똑같아요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><b>だけ</b>: 명사나 수량 바로 뒤에 붙여요.<br><span class='gd-pair'><span class='gd-jp'>水</span> → <span class='gd-jp'>水だけ</span></span><span class='gd-pair'><span class='gd-jp'>一つ</span> → <span class='gd-jp'>一つだけ</span></span><br>동사에도 붙일 수 있고, 이때는 사전형(사전에 실려 있는 형태)을 써요: <span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るだけ</span></span>(보기만 해요)</div><div class='gd-sec'><b>しか</b>: 명사나 수량 뒤에 붙이고, 문장 끝의 동사는 반드시 부정형으로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>水を飲みます</span> → <span class='gd-jp'>水しか飲みません</span></span>(물만 마셔요)</div><div class='gd-sec'><b>원래 있던 「を」「が」는 빼요</b>: <span class='gd-jp'>水を</span>는 <span class='gd-jp'>水だけ</span>, <span class='gd-jp'>水しか</span>가 돼요. (だけ 뒤에 を를 남겨도 되지만, 보통은 그냥 빼요.)<br>「に」「で」「へ」 같은 조사는 <b>그대로 남기고</b> しか 앞에 둬요.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達にしか言いませんでした。</span>(친구한테만 말했어요)</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>だけ：범위만 담담하게</span>많다 적다 하는 느낌 없이 ‘이것뿐’이라고 알려 주는 말이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>サラダだけ注文します。</span>(샐러드만 주문할게요)</div><div class='gd-ex-line'>・<span class='gd-jp'>見ているだけです。</span>(그냥 구경하는 중이에요)</div><div class='gd-sec'>두 번째 문장은 일본에서 쇼핑할 때 아주 유용해요. 점원이 다가와서 말을 걸면 이렇게 대답하면 돼요.</div><div class='gd-sec'><span class='gd-tag'>しか：적다, 부족하다고 느낄 때</span>마음속으로 ‘너무 적다’, ‘생각보다 적다’고 느끼는 거예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>10分しか残っていません。</span>(10분밖에 안 남았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は3時間しか寝ませんでした。</span>(어제는 3시간밖에 못 잤어요)</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・<b>しか 뒤에는 반드시 부정형</b>: <span class='gd-jp'>千円しかありません</span>은 되지만, 「千円しかあります」라고는 할 수 없어요.<br>・<b>「ません」을 ‘없다’로만 읽지 마세요</b>: <span class='gd-jp'>千円しかありません</span>은 ‘천 엔밖에 없어요’이지, ‘천 엔이 없어요’가 아니에요. <span class='gd-jp'>肉しか食べません</span>도 ‘고기만 먹어요’이지, ‘고기를 안 먹어요’가 아니에요. ‘그것 말고는 전부 없다’고 생각하면 쉬워요.<br>・<b>しか 앞에는 を, が를 남기지 않아요</b>: 「水をしか」라고는 못 하고, <span class='gd-jp'>水しか</span>라고 해야 해요.<br>・<b>だけ가 ‘충분하다’는 뜻은 아니에요</b>: だけ는 중립적인 ‘만’일 뿐, ‘충분하다’는 뜻은 없어요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>같은 상황이라도 だけ는 사실을 알리는 말이고, しか는 ‘너무 적다’는 감탄이 담긴 말이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人だけ来ました。</span>(파티에 한 명만 왔어요: 단순한 보고)</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人しか来ませんでした。</span>(파티에 한 명밖에 안 왔어요: 사람이 너무 적어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しだけ分かります。</span>(일본어를 조금 알아요: 겸손하게 조금 할 줄 안다고 말할 때)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少ししか分かりません。</span>(일본어를 조금밖에 몰라요: 많이 모른다는 점을 강조해서, 어려운 말은 쓰지 말아 달라고 할 때)</div><div class='gd-warn'>판단 요령: 한국어로 ‘~밖에 없다/안 ~한다’라고 말하고 싶고 마음속으로 적다고 느껴지면 「しか＋ません」을 쓰세요. 그냥 범위만 알려 주는 거라면 「だけ」를 쓰고요. しか는 반드시 ません과 짝이라는 점을 꼭 기억하세요.</div>","n5-62":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어에서는 ‘문이 열리다’와 ‘문을 열다’처럼 짝이 되는 동사가 있죠. 일본어도 마찬가지로 <b>동사가 서로 달라요</b>. ‘문이 열려요’는 <span class='gd-jp'>開く</span>, ‘누군가 문을 열어요’는 <span class='gd-jp'>開ける</span>를 써요. 앞쪽을 <b>자동사</b>, 뒤쪽을 <b>타동사</b>라고 하고, 앞에 오는 조사도 함께 바뀌어요.</div><div class='gd-h'>두 가지 이름부터 알아 두기</div><div class='gd-sec'><span class='gd-tag'>자동사＋が</span>누가 했는지와 상관없이 ‘무언가가 어떻게 된다’는 상태만 말해요. 앞에는 <b>が</b>를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開きます。</span>(문이 열려요: 전철 안내 방송에서 자주 들려요)</div><div class='gd-sec'><span class='gd-tag'>타동사＋を</span>‘누군가가 어떤 것에 작용한다’는 말이에요. 작용을 받는 대상 뒤에 <b>を</b>를 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアを開けます。</span>(문을 열어요)</div><div class='gd-sec'>간단한 판단법이 있어요. 한국어로 ‘~을/를’을 붙여 말할 수 있는지 보세요. ‘문을 열다’처럼 자연스러우면 타동사＋を, ‘문이 열리다’처럼 ‘~이/가’로 말하면 자동사＋が예요.</div><div class='gd-h'>가장 자주 나오는 짝</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がつきました。</span>(불이 켜졌어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>電気をつけてください。</span>(불을 켜 주세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業が始まります。</span>(수업이 시작돼요)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業を始めます。</span>(수업을 시작할게요)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布が落ちました。</span>(지갑이 떨어졌어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を落としました。</span>(지갑을 떨어뜨렸어요)</div><div class='gd-sec'>이런 짝도 있어요. 왼쪽이 자동사, 오른쪽이 타동사예요.<br><span class='gd-jp'>閉まる</span>／<span class='gd-jp'>閉める</span>(닫히다／닫다)<br><span class='gd-jp'>消える</span>／<span class='gd-jp'>消す</span>(꺼지다／끄다)<br><span class='gd-jp'>入る</span>／<span class='gd-jp'>入れる</span>(들어가다／넣다)<br><span class='gd-jp'>出る</span>／<span class='gd-jp'>出す</span>(나가다, 나오다／꺼내다, 내다)<br>어느 쪽이 자동사이고 어느 쪽이 타동사인지는 모든 경우에 맞는 규칙이 없어요. 그래서 <b>한 쌍씩 예문과 함께 외우는 게</b> 가장 좋아요.</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・조사와 동사의 짝을 맞춰야 해요: <span class='gd-jp'>電気を消します</span>, <span class='gd-jp'>電気が消えます</span>는 둘 다 맞지만, 「電気を消えます」는 틀려요.<br>・다른 사람에게 부탁할 때는 타동사를 써요: <span class='gd-jp'>窓を閉めてください</span>라고 해야 하고, 「窓が閉まってください」라고는 못 해요.<br>・여기서 <span class='gd-jp'>開く</span>는 <b>あく</b>라고 읽어요. 같은 한자에 「ひらく」라는 읽기도 있는데 쓰임이 달라서, 지금은 섞지 않는 게 좋아요.<br>・<span class='gd-jp'>入る</span>, <span class='gd-jp'>出る</span>는 장소와 함께 자주 써요: <span class='gd-jp'>部屋に入ります</span>(방에 들어가요)는 に를 쓰고, <span class='gd-jp'>家を出ます</span>(집을 나가요)의 を는 ‘떠나는 장소’를 나타내요. 작용을 받는 대상이 아니라서 出る는 여전히 자동사예요.<br>・자동사는 ‘저절로 일어나는 일’만 말하는 게 아니에요: <span class='gd-jp'>行く</span>, <span class='gd-jp'>寝る</span>도 자동사인데, 사람이 스스로 하는 동작이에요. 핵심은 <b>작용을 받는 대상이 있는지</b>예요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>두 종류의 동사에 「〜ています」를 붙이면 뜻이 많이 달라져요.<br><span class='gd-jp'>窓が開いています。</span>(창문이 열려 있어요) → 눈앞에 보이는 상태를 말해요<br><span class='gd-jp'>夏はいつも窓を開けています。</span>(여름에는 늘 창문을 열어 둬요) → 사람이 하는 동작이나 습관을 말해요</div><div class='gd-warn'>판단 요령: ‘열려 있다, 켜져 있다, 닫혀 있다’처럼 눈에 보이는 상태만 말할 때는 「が＋자동사ています」를 쓰세요.</div><div class='gd-h'>다음에 배워 보세요</div><div class='gd-sec'>타동사에 「〜てあります」를 붙이면 ‘누군가 일부러 해 두었다’는 뜻이 돼요: <span class='gd-jp'>窓が開けてあります。</span>(창문이 열려 있어요: 누군가 일부러 열어 두었어요)</div>","n5-1":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>「名詞＋です」는 한국어의 <b>“~이에요/예요”</b>, 「名詞＋じゃありません」은 <b>“~이/가 아니에요”</b>에 해당해요. <span class='gd-jp'>私は学生です。</span>는 “저는 학생이에요”라는 뜻이에요. 일본어에서 가장 기본적인 문장이라서 자기소개 첫 마디부터 바로 써요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>아주 간단해요. 명사 뒤에 <b>그대로 붙이기만</b> 하면 되고, 명사 자체는 전혀 바뀌지 않아요.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生です</span></span>(학생이에요)<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃありません</span></span>(학생이 아니에요)<br>문형은 「A<span class='gd-jp'>は</span>B<span class='gd-jp'>です</span>」＝A는 B예요/이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>林です。よろしくお願いします。</span>(저는 하야시예요. 잘 부탁드려요)</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>(이건 제 우산이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは先生じゃありません。</span>(다나카 씨는 선생님이 아니에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みじゃありません。</span>(내일은 휴일이 아니에요)</div><div class='gd-sec'>뒤에 <span class='gd-jp'>か</span>를 붙이면 의문문이 돼요. <span class='gd-jp'>学生ですか。</span>(학생이에요?)</div><div class='gd-h'>“아니에요”를 말하는 여러 가지 방법</div><div class='gd-sec'>뜻은 모두 같고, 쓰는 상황만 달라요.<br><span class='gd-tag'>가장 많이 써요</span><span class='gd-jp'>学生じゃありません</span>: 일상에서 쓰는 정중한 표현이에요.<br><span class='gd-tag'>조금 격식 있어요</span><span class='gd-jp'>学生ではありません</span>: 글이나 격식을 차리는 자리에서 써요. 「じゃ」는 「では」를 빠르게 말한 형태예요.<br><span class='gd-tag'>조금 편해요</span><span class='gd-jp'>学生じゃないです</span>: 마찬가지로 정중하지만 어감이 더 부드러워서, 요즘 일본 사람들이 말할 때 아주 많이 써요.</div><div class='gd-h'>친구에게 말할 때</div><div class='gd-sec'>가족이나 친한 친구에게는 です를 쓰지 않고 <b>だ／じゃない</b>로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><br>다만 실제 대화에서는 「だ」를 생략하거나 뒤에 「よ」를 붙이는 쪽이 자연스러워요. 그렇지 않으면 말투가 조금 딱딱하게 들려요.</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、学生だよ。</span>(응, 나 학생이야)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・「AはB」의 <span class='gd-jp'>は</span>는 ha가 아니라 <b>wa</b>로 읽어요.<br>・<span class='gd-jp'>です</span> 끝의 「す」는 보통 아주 약하게 발음해서 “des”처럼 들려요.<br>・です가 늘 “~이에요”로 옮겨지는 건 아니에요. <span class='gd-jp'>今日は雨です。</span>는 “오늘은 비가 와요”라는 뜻이에요. 한국어로는 “오늘은 비예요”보다 “비가 와요”가 자연스럽죠.<br>・동사 뒤에는 です를 붙일 수 없어요. <span class='gd-jp'>食べます</span>라고 하면 되고, 「食べるです」라고 하면 안 돼요.<br>・문장마다 <span class='gd-jp'>私は</span>를 말할 필요는 없어요. 상대가 자기 이야기라는 걸 알 때는 일본 사람들도 보통 생략해요.</div><div class='gd-h'>비슷하게 생긴 표현과 구분하기</div><div class='gd-sec'>명사와 な형용사의 부정은 둘 다 じゃありません을 쓰지만, <b>い형용사는 달라서</b> 가장 헷갈려요.<br><b>명사</b>: <span class='gd-jp'>ここは駅じゃありません。</span>(여기는 역이 아니에요)<br><b>な형용사</b>: <span class='gd-jp'>ここは静かじゃありません。</span>(여기는 조용하지 않아요)<br><b>い형용사</b>: <span class='gd-jp'>ここは高くないです。</span>(여기는 비싸지 않아요)<br>「高いじゃありません」이라고는 할 수 없고, い를 <b>くない</b>로 바꿔야 해요.</div><div class='gd-warn'>구분 요령: 명사와 な형용사는 그대로 「じゃありません」을 붙이고, い형용사는 い를 「くないです」로 바꿔요. <span class='gd-jp'>きれい</span>는 い로 끝나지만 사실 な형용사예요. 그래서 <span class='gd-jp'>きれいじゃありません</span>이라고 해요.</div><div class='gd-h'>다 익힌 다음에 배우면 좋은 것</div><div class='gd-sec'>과거 표현이에요. <span class='gd-jp'>学生でした</span>(예전에 학생이었어요), <span class='gd-jp'>学生じゃありませんでした</span>(예전에 학생이 아니었어요).</div>","n5-2":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>「〜ます」는 일본어의 <b>정중한 말투</b>예요. 선생님, 점원, 처음 만난 사람에게 쓰고, 가족이나 친한 친구에게는 ます가 없는 말투를 써요. “~하지 않아요”라고 말하려면 ます를 <b>ません</b>으로 바꾸면 돼요. 처음 배울 때는 <b>전부 ます로 말하는 게 가장 안전</b>해요. 실례가 되지 않거든요.</div><div class='gd-h'>하나의 형태로 현재도 미래도</div><div class='gd-sec'>일본어에는 따로 “미래형”이 없어요. 평소의 습관도, 앞으로 할 일도 모두 「〜ます」를 쓰고, 시간은 「毎日」「明日」「来週」 같은 말로 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日コーヒーを飲みます。</span>(저는 매일 커피를 마셔요: 습관)</div><div class='gd-ex-line'>・<span class='gd-jp'>来週、京都へ行きます。</span>(다음 주에 교토에 가요: 미래)</div><div class='gd-ex-line'>・<span class='gd-jp'>田村先生はお酒を飲みません。</span>(다무라 선생님은 술을 안 드세요)</div><div class='gd-h'>활용 방법: 먼저 동사가 어느 그룹인지 보기</div><div class='gd-sec'><b>1그룹(5단 동사)</b>: 마지막 음을 같은 행의 「い」단 음으로 바꾸고 ます를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む를 み로 바꿈 → <span class='gd-jp'>飲みます</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きます</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買います</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>2그룹(1단 동사)</b>: 마지막의 「る」를 떼고 ます를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span></div><div class='gd-sec'><b>3그룹(두 개뿐이니 그냥 외우세요)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>(きます)</span><br>「勉強する」「出張する」처럼 「名詞＋する」 형태인 단어도 똑같아요. <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'>부정은 ます를 ません으로 바꾸기만 하면 되고, 세 그룹 모두 같아요. <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べません</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span>는 2그룹처럼 생겼지만 사실 1그룹이에요. <span class='gd-jp'>帰ります</span>가 맞고, 帰ます가 아니에요.<br>・「ません」은 “~하지 않아요”이지 “~할 수 없어요”가 아니에요. <span class='gd-jp'>お酒を飲みません</span>은 “저는 술을 안 마셔요”이고, “못 마셔요”가 아니에요.<br>・ます는 <b>동사</b> 뒤에만 붙일 수 있어요. “저는 학생이에요”는 <span class='gd-jp'>学生です</span>라고 하고, 学生ます라고 하면 안 돼요.<br>・ます의 「す」는 보통 아주 약하게 발음해서 “mas”처럼 들려요. 그렇게 들려도 잘못 들은 게 아니니 걱정하지 마세요.</div><div class='gd-h'>비슷하게 생긴 표현과 구분하기</div><div class='gd-sec'>한국어는 “지금 밥을 먹어요”처럼 습관과 진행을 같은 형태로 말할 수 있어서, “~하고 있어요”까지 그냥 ます로 말하기 쉬워요. 하지만 ます는 <b>습관</b>이나 <b>앞으로 할 일</b>을 말하고, “~하는 중이에요”는 <b>ています</b>를 써야 해요.<br><span class='gd-jp'>今、ご飯を食べます。</span>(지금 밥을 먹을 거예요: 아직 먹기 전)<br><span class='gd-jp'>今、ご飯を食べています。</span>(지금 밥을 먹고 있어요: 이미 먹는 중)</div><div class='gd-warn'>구분 요령: 아직 시작하기 전이거나 매일 하는 일은 ます, 지금 하는 중이면 ています를 써요.</div><div class='gd-h'>다 익힌 다음에 배우면 좋은 것</div><div class='gd-sec'>지난 일을 말할 때예요. <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>(마셨어요), <span class='gd-pair'><span class='gd-jp'>飲みません</span> → <span class='gd-jp'>飲みませんでした</span></span>(안 마셨어요).<br>다른 사람에게 권유하고 싶다면 <span class='gd-jp'>〜ませんか</span>와 <span class='gd-jp'>〜ましょう</span>를 이어서 배워 보세요.</div>","n5-31":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>「から」는 한국어의 <b>「~니까」「~기 때문에」</b>에 해당해요. 한국어에서 이유를 먼저 말하고 어미를 붙이는 것처럼, 일본어도 <b>이유 문장의 맨 끝</b>에 「から」를 붙이고 그다음에 결과를 말해요. 어순이 같아서 금방 익숙해질 거예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないから、急ぎましょう。</span>(시간이 없으니까 서두르죠)</div><div class='gd-sec'>순서는 <b>이유 ＋ から、결과</b>예요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>「から」 앞에는 완결된 문장이 와요. 반말체(보통형)도 되고, です・ます가 붙은 정중한 형태도 돼요.<br><b>동사</b>: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くから</span></span><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますから</span></span><br><b>い형용사</b>: <span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いから</span></span><span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒いですから</span></span><br><b>な형용사</b>: 먼저 「だ」나 「です」를 붙여야 해요. <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かですから</span></span><br><b>명사</b>: 마찬가지로 「だ」나 「です」를 붙여요. <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だから</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨ですから</span></span><br>과거의 일도 말할 수 있어요: <span class='gd-pair'><span class='gd-jp'>寝なかった</span> → <span class='gd-jp'>寝なかったから</span></span></div><div class='gd-sec'>앞부분은 반말체로 쓰고 문장 끝에 ます를 쓰는 형태는 일상에서 아주 흔해요. 더 공손하게 말하고 싶다면 앞뒤 모두 です・ます를 쓰세요.</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>이유 설명</span>원인을 먼저 말하고 결과를 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いから、よく来ます。</span>(이 가게는 싸서 자주 와요)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は日曜日だから、学校は休みです。</span>(오늘은 일요일이라서 학교는 쉬어요)</div><div class='gd-sec'><span class='gd-tag'>부탁, 주의, 권유</span>뒤에 요청이나 권유가 와도 자연스러워요.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないですから、触らないでください。</span>(위험하니까 만지지 마세요)</div><div class='gd-sec'><span class='gd-tag'>이유만 대답하기</span>상대가 「왜?」라고 물었을 때는 결과를 다 아니까 이유에 から만 붙여서 대답해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>「どうして食べないの？」「辛いから。」</span>(「왜 안 먹어?」「매우니까.」)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・명사와 な형용사 뒤에는 <b>から를 바로 붙일 수 없어요</b>. <span class='gd-jp'>雨だから</span>라고 해야 하고 「雨から」는 틀려요. <span class='gd-jp'>静かだから</span>라고 해야 하고 「静かから」는 틀려요.<br>・い형용사는 반대로 <b>だ를 붙이면 안 돼요</b>. <span class='gd-jp'>高いから</span>라고 해야 하고 「高いだから」는 틀려요.<br>・「왜냐하면」처럼 から를 문장 맨 앞에 두면 안 돼요. 「비가 오니까」는 <span class='gd-jp'>雨だから</span>이고, から는 뒤에 와요.<br>・문장 맨 앞에 단독으로 오는 <span class='gd-jp'>だから</span>는 「그래서」「그러니까」라는 뜻이에요. <span class='gd-jp'>雨です。だから、行きません。</span>(비가 와요. 그래서 안 가요)<br>・선생님이나 상사에게 자기 상황(예: 지각한 이유)을 설명할 때 から는 좀 직설적으로 들려서, 때로는 변명처럼 느껴질 수 있어요. 일상 대화에서는 から를 써도 전혀 문제없어요.</div><div class='gd-h'>비슷하게 생긴 표현과 구별하기</div><div class='gd-sec'>이미 배운 시작점을 나타내는 「から」(<b>~부터, ~에서</b>)와 생김새가 똑같아요.<br><b>시작점</b>: <span class='gd-jp'>9時から働きます。</span>(9시부터 일해요)<br><b>이유</b>: <span class='gd-jp'>雨だから、働きません。</span>(비가 오니까 일하지 않아요)<br>차이는 앞에 무엇이 오느냐예요. 시작점의 から는 시간이나 장소 명사가 바로 앞에 오고, 이유의 から는 동사, 형용사, 「だ」「です」처럼 문장의 끝 형태가 앞에 와요.</div><div class='gd-warn'>구별 요령: から 앞에 <span class='gd-jp'>9時</span>, <span class='gd-jp'>駅</span> 같은 명사만 있으면 「~부터/~에서」예요. 앞에 <span class='gd-jp'>雨だ</span>, <span class='gd-jp'>寒い</span>, <span class='gd-jp'>あります</span>처럼 완결된 문장이 있으면 「~니까」예요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>이유를 문장 끝으로 보내 「〜からです」로 만들면 「왜?」라는 질문에 대답할 수 있어요. <span class='gd-jp'>熱があるからです。</span>(열이 있어서예요) 나중에 「〜ので」도 배울 텐데요, 이것도 「~때문에」라는 뜻이고 から보다 어감이 부드러워서 상사에게 휴가를 내거나 사과할 때 더 자주 써요.</div>","n5-54":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>이 세 가지 문형은 <b>일을 하는 순서</b>를 나타내요. 한국어와 거의 같아서 이해하기 쉬워요.<br><span class='gd-jp'>〜てから</span>＝「~하고 나서」(먼저 ~하고, 그다음에 ~)<br><span class='gd-jp'>〜たあとで</span>＝「~한 후에」<br><span class='gd-jp'>〜まえに</span>＝「~하기 전에」<br>친구에게 하루를 이야기하듯 떠올려 보세요. 양치하고 나서 자고, 밥을 먹은 후에 TV를 보고, 나가기 전에 날씨를 확인하는 식이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><span class='gd-tag'>먼저 ~하고 나서 ~</span>동사 <b>て형</b>＋から.<br><span class='gd-pair'><span class='gd-jp'>磨く</span> → <span class='gd-jp'>磨いて</span> → <span class='gd-jp'>磨いてから</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてから</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してから</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>歯を磨いてから、寝ます。</span>(양치하고 나서 자요)</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってから、食べてください。</span>(먼저 손을 씻고 나서 드세요)</div><div class='gd-sec'><span class='gd-tag'>~한 후에</span>동사 <b>た형</b>＋あとで. た형은 て형의 「て」를 「た」로, 「で」를 「だ」로 바꾼 형태예요.<br><span class='gd-pair'><span class='gd-jp'>見て</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たあとで</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだあとで</span></span><br>앞에 명사가 오면 중간에 「の」를 넣어요: <span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のあとで</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見たあとで、ご飯を食べました。</span>(영화를 본 후에 밥을 먹었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のあとで、ビールを飲みます。</span>(퇴근 후에 맥주를 마셔요)</div><div class='gd-sec'><span class='gd-tag'>~하기 전에</span>동사 <b>사전형</b>(사전에 실려 있는 기본형)＋まえに.<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝るまえに</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまえに</span></span><br>앞에 명사가 올 때도 「の」를 넣어요: <span class='gd-pair'><span class='gd-jp'>食事</span> → <span class='gd-jp'>食事のまえに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寝るまえに、シャワーを浴びます。</span>(자기 전에 샤워해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>食事のまえに、手を洗います。</span>(식사 전에 손을 씻어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・まえに 앞에는 <b>항상 사전형</b>이 와요. 과거의 일을 말할 때도 마찬가지예요. <span class='gd-jp'>日本へ来るまえに、英語を勉強しました。</span>(일본에 오기 전에 영어를 공부했어요) 「来たまえに」라고는 할 수 없어요. 한국어의 「~기 전에」와 같은 원리예요.<br>・あとで 앞에는 <b>항상 た형</b>이 와요. 아직 일어나지 않은 일을 말할 때도 마찬가지예요. <span class='gd-jp'>食べたあとで、歯を磨きます。</span>(먹은 후에 양치할 거예요) 「食べるあとで」라고는 할 수 없어요.<br>・문장 전체가 과거인지 현재인지는 <b>문장 끝</b>(磨きます／磨きました)이 정해요. 앞부분은 따라서 바꾸지 않아요.<br>・명사에 바로 붙이면 「の」를 빠뜨리기 쉬워요. 한국어는 「수업 후에」처럼 조사가 없지만, 일본어는 <span class='gd-jp'>授業のあとで</span>라고 해야 하고 「授業あとで」는 틀려요.<br>・<span class='gd-jp'>あとで</span> 앞에 아무것도 없이 단독으로 쓰면 「나중에, 이따가」라는 뜻이에요. <span class='gd-jp'>あとで電話します。</span>(이따가 전화할게요)</div><div class='gd-h'>비슷하게 생긴 표현과 구별하기</div><div class='gd-sec'>てから와 あとで는 둘 다 「A를 하고 나서 B」라는 뜻이고, 많은 경우 둘 다 쓸 수 있어요. 차이는 어감이에요.<br><span class='gd-jp'>お風呂に入ってから、ご飯を食べます。</span>(<b>먼저</b> 목욕하고 <b>나서</b> 밥을 먹어요: 순서를 강조해서 「목욕을 마쳐야 먹는다」는 느낌이에요)<br><span class='gd-jp'>お風呂に入ったあとで、ご飯を食べます。</span>(목욕한 후에 밥을 먹어요: 밥 먹는 시점이 뒤라는 것만 알려 줘요)<br>상대에게 「A를 반드시 먼저 해 달라」고 할 때는 てから가 가장 자연스러워요.<br><span class='gd-jp'>電話してから来てください。</span>(먼저 전화하고 나서 오세요)</div><div class='gd-warn'>구별 요령: 「먼저 ~하고 나서 ~」는 <b>てから</b>, 단순히 「~한 후에」는 <b>たあとで</b>, 「~하기 전에」는 <b>まえに</b>를 쓰고, 이때 앞에는 반드시 사전형이 와요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>てから 뒤에 일정 기간이 오면 「~하고 나서 벌써 …」라는 뜻이 돼요. <span class='gd-jp'>日本に来てから、もう三年です。</span>(일본에 온 지 벌써 3년이에요)</div>","n5-11":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「〜くします／〜にします」는 한국어의 <b>「~을/를 ~하게 만들다」「~하게 하다」</b>에 해당해요. 예를 들어 「소리를 작게 하다」「방을 깨끗하게 정리하다」처럼, 물건이 저절로 변하는 게 아니라 <b>누군가 직접 손을 써서</b> 바꾼다는 점이 핵심이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><b>い형용사</b>: 마지막 「い」를 빼고 「く」로 바꾼 다음 します를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>短い</span> → い를 く로 바꾸기 → <span class='gd-jp'>短くします</span></span><br><span class='gd-pair'><span class='gd-jp'>小さい</span> → <span class='gd-jp'>小さくします</span></span><span class='gd-pair'><span class='gd-jp'>暖かい</span> → <span class='gd-jp'>暖かくします</span></span></div><div class='gd-sec'><b>な형용사</b>: 그대로 「にします」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいにします</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かにします</span></span></div><div class='gd-sec'><b>명사</b>: 이것도 그대로 「にします」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>子どもの部屋</span> → <span class='gd-jp'>子どもの部屋にします</span></span></div><div class='gd-sec'>바뀌는 대상 뒤에는 <b>を</b>를 써요. 한국어의 「~을/를」과 딱 맞아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>音を小さくしてください。</span>(소리를 작게 해 주세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上をきれいにします。</span>(책상 위를 깨끗하게 정리해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋を子どもの部屋にします。</span>(이 방을 아이 방으로 만들 거예요)</div><div class='gd-h'>가장 자주 듣는 표현</div><div class='gd-sec'><span class='gd-tag'>상대에게 부탁할 때</span>뒤에 「てください」를 붙여서, 상대에게 무언가를 어떤 상태로 만들어 달라고 부탁해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かにしてください。</span>(조용히 해 주세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し安くしてください。</span>(조금만 더 싸게 해 주세요)</div><div class='gd-sec'><span class='gd-tag'>주문・선택할 때</span>명사＋にします는 「~로 할게요」「~로 정했어요」처럼 선택할 때도 자주 써요. 식당에서 주문할 때 특히 많이 들어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>私はコーヒーにします。</span>(저는 커피로 할게요)</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行は京都にしました。</span>(여행은 교토로 정했어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・い형용사의 「い」는 반드시 먼저 빼야 해요. <span class='gd-jp'>短くします</span>가 맞고, 「短いくします」나 「短いにします」는 틀려요.<br>・<span class='gd-jp'>きれい</span>는 끝이 い지만 な형용사예요. <span class='gd-jp'>きれいにします</span>가 맞고, 「きれくします」는 틀려요.<br>・<span class='gd-jp'>いい</span>는 <span class='gd-jp'>よく</span>로 바뀌어요. <span class='gd-jp'>この町をよくしたいです。</span>(이 도시를 더 좋게 만들고 싶어요) 「いくします」는 틀려요.<br>・바꾸려는 대상에는 <b>を</b>를 써요. が로 쓰지 않도록 주의하세요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'><b>くなります／になります</b>＝대상이 <b>저절로 그렇게 되는 것</b>이고, <b>が</b>를 써요.<br><span class='gd-jp'>部屋が暖かくなりました。</span>(방이 따뜻해졌어요: 해가 들었을 수도 있어요)<br><b>くします／にします</b>＝<b>누군가 손을 써서</b> 그렇게 만드는 것이고, <b>を</b>를 써요.<br><span class='gd-jp'>部屋を暖かくしました。</span>(방을 따뜻하게 했어요: 예를 들어 난방을 켰어요)</div><div class='gd-warn'>판단 요령: 「~을/를 ~하게 만들다」라고 말할 수 있으면 <b>を＋します</b>, 「~해지다」라고만 말할 수 있으면 <b>が＋なります</b>를 써요.</div><div class='gd-h'>다 배운 뒤에 이어서 배울 내용</div><div class='gd-sec'>명사＋にします는 「~로 정하다」라는 뜻으로 쓸 수 있어요. 어떤 행동을 하기로 결정할 때는 나중에 동사＋ことにします를 배우게 돼요. <span class='gd-jp'>日本へ行くことにしました。</span>(일본에 가기로 했어요)</div>","n5-12":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「〜ましょう」는 한국어의 <b>「우리 ~해요」「~합시다」</b>에 해당해요. 친구에게 「우리 가요」「잠깐 쉬어요」라고 말할 때, 일본어로는 <span class='gd-jp'>行きましょう</span>, <span class='gd-jp'>休みましょう</span>라고 해요. 정중한 표현이라서 선생님, 직장 동료, 처음 만난 사람에게도 쓸 수 있어요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>동사를 먼저 「〜ます」형으로 만들고, <b>ます를 ましょう로 바꾸기</b>만 하면 돼요. 동사가 어느 그룹인지는 신경 쓰지 않아도 돼요.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きましょう</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べましょう</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しましょう</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ましょう</span></span></div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>상대에게 함께하자고 권할 때</span>모두 함께 무언가를 할 때 쓰고, <span class='gd-jp'>一緒に</span>(함께)와 자주 같이 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に帰りましょう。</span>(같이 집에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休みましょう。</span>(잠깐 쉬어요)</div><div class='gd-sec'><span class='gd-tag'>앞장서서 시작을 알릴 때</span>수업하는 선생님이나 회의를 진행하는 사람이 자주 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>じゃあ、始めましょう。</span>(그럼 시작해요)</div><div class='gd-h'>뒤에 か를 붙이면: ましょうか</div><div class='gd-sec'><span class='gd-tag'>제가 도와드릴까요?</span>상대를 위해 먼저 나서서 무언가를 해 주겠다고 할 때 쓰는, 배려심 있는 표현이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物を持ちましょうか。</span>(짐을 들어 드릴까요?)</div><div class='gd-sec'><span class='gd-tag'>함께 의논할 때</span>이미 같이 하기로 정한 뒤 세부 사항을 물을 때 쓰고, 앞에 「何」「どこ」「何時」가 자주 와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>何時に会いましょうか。</span>(우리 몇 시에 만날까요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・ます는 <b>바꾸는 것</b>이지 뒤에 덧붙이는 게 아니에요. <span class='gd-jp'>行きましょう</span>가 맞고, 「行きますましょう」는 틀려요.<br>・「ましょう」는 <b>ましょー</b>처럼 길게 발음해요. 짧게 「ましょ」라고 하지 않도록 주의하세요.<br>・이 표현에는 <b>말하는 사람 자신도 포함돼요</b>. 상대에게만 하라고 시키는 말이 아니에요. 「~해 주세요」라고 말하고 싶다면 「〜てください」를 써야 해요. 길거리 안내문의 <span class='gd-jp'>ゴミは持ち帰りましょう</span>(쓰레기는 가져가요)는 부드럽게 권하는 특별한 용법이니, 직접 말할 때는 아직 이렇게 쓰지 않는 게 좋아요.<br>・처음 상대에게 제안하는데 상대가 가고 싶은지 모를 때 바로 「行きましょう」라고 하면, 내가 이미 상대 대신 정한 것처럼 들려요. 이럴 때는 먼저 「〜ませんか」로 물어보는 게 더 정중해요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 「영화 보러 가자고 약속하는」 상황에서 이 세 가지는 자주 앞뒤로 나와요.<br><b>ませんか</b>＝먼저 상대의 의향을 물어요: <span class='gd-jp'>映画を見ませんか。</span>(같이 영화 보지 않을래요?)<br><b>ましょう</b>＝승낙하고 함께 진행해요: <span class='gd-jp'>ええ、見ましょう。</span>(네, 봐요)<br><b>ましょうか</b>＝상대의 의견을 물어요: <span class='gd-jp'>何を見ましょうか。</span>(뭘 볼까요?)</div><div class='gd-warn'>판단 요령: 상대가 아직 승낙하지 않았으면 「ませんか」, 이미 정해서 같이 할 때는 「ましょう」, 상대 의견을 묻거나 먼저 도와주겠다고 할 때는 「ましょうか」를 써요.</div><div class='gd-h'>다 배운 뒤에 이어서 배울 내용</div><div class='gd-sec'>친한 친구에게는 이렇게 정중하지 않아도 되니, 더 편한 말투로 바꿀 수 있어요. <span class='gd-pair'><span class='gd-jp'>行きましょう</span> → <span class='gd-jp'>行こう</span></span> 이건 N4에서 「의지형」을 배울 때 알려 드릴게요.</div>","n5-7":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'><span class='gd-jp'>静かです</span>는 「지금 조용해요」라는 뜻이에요. 「<b>예전에</b> 조용했어요」라고 말하려면 <span class='gd-jp'>です</span>를 <span class='gd-jp'>でした</span>로 바꾸면 돼요: <span class='gd-jp'>静かでした</span>. 한국어에서 「조용해요」가 「조용했어요」로 바뀌는 것처럼, 일본어도 문장 끝을 과거 모양으로 바꾸는 거예요. 이 변화는 명사와 <b>완전히 똑같아요</b>(<span class='gd-jp'>学生でした</span>). 하나를 익히면 두 개를 익힌 셈이에요.</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>な형용사는 명사 앞에 올 때 「な」를 붙이는 형용사예요. <span class='gd-jp'>静かな部屋</span>, <span class='gd-jp'>きれいな花</span> 같은 것들이죠.<br>첫 번째 단계: 「な」를 빼요. 남은 부분을 「어간」(본체)이라고 해요.<br><span class='gd-pair'><span class='gd-jp'>静かな</span> → な 빼기 → <span class='gd-jp'>静か</span></span><br>두 번째 단계: 뒤에 원하는 꼬리를 붙여요.<br>현재: <span class='gd-jp'>静かです</span>(조용해요) ／ <span class='gd-jp'>静かじゃありません</span>(조용하지 않아요)<br>과거: <span class='gd-jp'>静かでした</span>(예전에 조용했어요) ／ <span class='gd-jp'>静かじゃありませんでした</span>(예전에 조용하지 않았어요)</div><div class='gd-sec'><span class='gd-tag'>과거 긍정</span>그때는 그랬다는 뜻이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は暇でした。</span>(어제는 한가했어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは簡単でした。</span>(시험은 쉬웠어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、野菜が嫌いでした。</span>(어릴 때 채소를 싫어했어요)</div><div class='gd-sec'><span class='gd-tag'>과거 부정</span>그때는 그렇지 않았다는 뜻이에요. <span class='gd-jp'>あまり</span>(별로)와 자주 함께 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋はあまりきれいじゃありませんでした。</span>(방이 별로 깨끗하지 않았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>あまり有名じゃありませんでした。</span>(그때는 별로 유명하지 않았어요)</div><div class='gd-h'>그 밖에 자주 듣는 표현</div><div class='gd-sec'><span class='gd-tag'>좀 더 격식 있게</span><span class='gd-jp'>じゃ</span>를 <span class='gd-jp'>では</span>로 바꿔요: <span class='gd-jp'>静かではありませんでした</span>. 글이나 격식 있는 자리에서 써요.<br><span class='gd-tag'>구어체 존댓말</span><span class='gd-jp'>静かじゃなかったです</span>는 뜻이 같고, 일상 대화에서 아주 자주 들려요.<br><span class='gd-tag'>친구 사이</span>でした는 <span class='gd-jp'>だった</span>로, 부정은 <span class='gd-jp'>じゃなかった</span>로 바꿔요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、暇だった。</span>(어제 한가했어)</div><div class='gd-ex-line'>・<span class='gd-jp'>全然大変じゃなかった。</span>(전혀 힘들지 않았어)</div><div class='gd-h'>자주 틀리는 부분</div><div class='gd-warn'>・「な」는 빼야 해요. <span class='gd-jp'>静かでした</span>라고 하고, 「静かなでした」는 틀려요.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>有名</span>는 끝에 「い」가 있지만 <b>な형용사</b>예요. <span class='gd-jp'>きれいでした</span>라고 하고, 「きれいかったです」는 틀려요.<br>・과거 부정을 「静かじゃないでした」처럼 스스로 조합하면 안 돼요. 정확한 표현은 <span class='gd-jp'>静かじゃありませんでした</span> 또는 <span class='gd-jp'>静かじゃなかったです</span>예요.<br>・<span class='gd-jp'>あまり</span> 뒤에는 반드시 부정이 와요. <span class='gd-jp'>あまり暇じゃありませんでした</span>처럼 말하고, 「あまり暇でした」라고는 할 수 없어요.</div><div class='gd-h'>닮은 표현과 구별해요</div><div class='gd-sec'><b>い형용사의 과거</b>는 변화 방식이 완전히 달라요. い를 <span class='gd-jp'>かった</span>로 바꾸고 です를 붙여요. 어제 묵은 호텔을 예로 들어 볼게요.<br><span class='gd-jp'>ホテルは静かでした。</span>(호텔은 조용했어요: な형용사)<br><span class='gd-jp'>ホテルは高かったです。</span>(호텔은 비쌌어요: い형용사)<br>반대로 い형용사에 でした를 붙일 수도 없어요. 「高いでした」라고는 말하지 않아요.</div><div class='gd-sec'><b>になりました</b>는 「～하게 <b>됐어요</b>」라는 뜻으로, 단순한 과거 상태가 아니라 변화를 말해요.<br><span class='gd-jp'>町は静かでした。</span>(그때 이 동네는 조용했어요)<br><span class='gd-jp'>町は静かになりました。</span>(이 동네가 조용해졌어요: 전에는 조용하지 않았어요)</div><div class='gd-warn'>판단 요령: 먼저 な형용사인지 확인하고, 맞으면 「な를 빼고 ＋ でした」를 써요. 한국어로 「~해졌어요」라고 말하고 싶을 때는 <span class='gd-jp'>になりました</span>를 써요.</div><div class='gd-h'>다 익혔다면 다음으로</div><div class='gd-sec'>다음은 い형용사의 과거 <span class='gd-jp'>〜かったです</span>를 배워 봐요. 두 가지를 함께 연습하면 더 이상 헷갈리지 않아요.</div>","n5-8":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'>「어제는 <b>추웠어요</b>」「라멘이 <b>맛있었어요</b>」처럼 「전에 어땠는지」를 말할 때 쓰는 문형이에요. 한국어에서 「춥다 → 추웠어요」처럼 어미가 바뀌듯이, 일본어 い형용사(끝이 「い」인 형용사로, <span class='gd-jp'>暑い</span>, <span class='gd-jp'>おいしい</span> 같은 것들)도 <b>형용사 자체가 모양을 바꿔요</b>: <span class='gd-pair'><span class='gd-jp'>暑いです</span> → <span class='gd-jp'>暑かったです</span></span>.</div><div class='gd-h'>어떻게 바꿀까요</div><div class='gd-sec'><span class='gd-tag'>과거・긍정</span>맨 끝의 「い」를 빼고 「かったです」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → い 빼기 → <span class='gd-jp'>暑かったです</span></span><br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしかったです</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は寒かったです。</span>(어제는 추웠어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしかったです。</span>(이 라멘은 맛있었어요)</div><div class='gd-sec'><span class='gd-tag'>과거・부정</span>「い」를 「く」로 바꾸고 「なかったです」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → い를 く로 바꾸기 → <span class='gd-jp'>難しくなかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>テストは難しくなかったです。</span>(시험은 어렵지 않았어요)</div><div class='gd-sec'>다른 표현인 <span class='gd-jp'>難しくありませんでした</span>도 뜻이 같아요. 조금 더 격식 있게 들리고, 둘 다 맞는 표현이에요.</div><div class='gd-sec'><span class='gd-tag'>특별한 하나</span><span class='gd-jp'>いい</span>(좋다)는 활용할 때 먼저 <span class='gd-jp'>よい</span>로 돌아가서 바꿔요. 그냥 외워 두세요.<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかったです</span></span>(좋았어요), <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくなかったです</span></span>(좋지 않았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>天気はよくなかったです。</span>(날씨가 별로 좋지 않았어요)</div><div class='gd-h'>가장 자주 듣는 모습</div><div class='gd-sec'>친구가 여행에서 돌아와서 누가 소감을 물으면 이렇게 묻고 답해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行はどうでしたか。</span>(여행은 어땠어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(아주 즐거웠어요)</div><div class='gd-sec'>질문은 <span class='gd-jp'>でした</span>를 쓰지만 대답은 <span class='gd-jp'>楽しかったです</span>예요. 질문에 끌려가서 「楽しいでした」라고 말하지 않도록 조심하세요.</div><div class='gd-h'>자주 틀리는 부분</div><div class='gd-warn'>・<span class='gd-jp'>暑いでした</span>라고는 <b>말할 수 없어요</b>. い형용사의 과거는 「かった」로 만들고, でした를 붙이는 게 아니에요.<br>・<span class='gd-jp'>暑かったでした</span>라고 해도 안 돼요. 「かった」가 이미 과거예요. 뒤의 です는 문장을 공손하게 만들 뿐이라서 でした로 바꿀 필요가 없어요.<br>・「かった」 가운데에는 작은 っ가 있어서 한 박자 쉬어야 해요. あつ<b>か</b>っ<b>た</b>처럼요. 「あつかた」로 읽으면 어색하게 들려요.<br>・<span class='gd-jp'>いい</span>는 「いかったです」「いくなかったです」로 바꿀 수 없어요. 무조건 <span class='gd-jp'>よ</span>부터 시작해서 바꿔요.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>有名</span>는 끝에 「い」 소리가 있지만 な형용사예요. 「きれかったです」로 바꾸면 안 되고, <span class='gd-jp'>きれいでした</span>라고 해요.</div><div class='gd-h'>닮은 표현과 구별해요</div><div class='gd-sec'>똑같이 「지난주 여행」을 말해 볼게요.<br><b>い형용사</b>: <span class='gd-jp'>ホテルは高かったです。</span>(호텔은 비쌌어요)<br><b>な형용사</b>: <span class='gd-jp'>ホテルはきれいでした。</span>(호텔은 깨끗했어요)<br><b>명사</b>: <span class='gd-jp'>天気は雨でした。</span>(날씨는 비였어요)<br>い형용사는 스스로 「かった」로 바뀌고, な형용사와 명사는 です를 でした로 바꿔요.</div><div class='gd-warn'>판단 요령: 먼저 사전에서 찾을 때 「い」로 끝나는 い형용사인지 확인하세요. 맞으면 「〜かったです」를 쓰고, 아니면(きれい, 元気, 雨 같은 것들) 「〜でした」를 써요.</div><div class='gd-h'>다 익혔다면 다음으로</div><div class='gd-sec'>です를 빼면 친구 사이에 쓰는 말이 돼요: <span class='gd-jp'>昨日、寒かった。</span>(어제 엄청 추웠어). 「～해지다」라는 뜻의 「〜くなります」도 이어서 배워 보세요: <span class='gd-jp'>寒くなりました。</span>(추워졌어요)</div>","n5-5":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'>「〜です」는 '~이에요/예요', 「〜でした」는 <b>'(그때) ~였어요/이었어요'</b>예요. 한국어에서 과거를 말할 때 어미가 바뀌는 것처럼, 일본어도 <b>과거를 말할 때는 です를 でした로 바꿔요</b>.</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'><span class='gd-tag'>이다</span>명사 뒤에 바로 でした를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生でした</span></span><span class='gd-pair'><span class='gd-jp'>休みです</span> → <span class='gd-jp'>休みでした</span></span></div><div class='gd-sec'><span class='gd-tag'>아니다</span>먼저 현재형 「じゃありません」을 쓰고, 그 뒤에 でした를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃありませんでした</span></span><br>글에서는 좀 더 격식 있는 <span class='gd-jp'>ではありませんでした</span>를 써요. 뜻은 같아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でした。</span>(어제는 비가 왔어요 / 비 오는 날이었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>先週の月曜日は祝日でした。</span>(지난주 월요일은 공휴일이었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みじゃありませんでした。</span>(어제는 휴일이 아니었어요)</div><div class='gd-h'>가장 자주 듣는 형태예요</div><div class='gd-sec'><span class='gd-tag'>과거 질문</span>문장 끝에 か를 붙이면 질문이 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みでしたか。</span>(어제는 쉬는 날이었어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、休みでした。</span>(네, 쉬는 날이었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、休みじゃありませんでした。</span>(아니요, 쉬는 날이 아니었어요)</div><div class='gd-sec'><span class='gd-tag'>친구 버전</span>친한 친구에게는 でした를 <b>だった</b>로, じゃありませんでした를 <b>じゃなかった</b>로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>雨でした</span> → <span class='gd-jp'>雨だった</span></span><span class='gd-pair'><span class='gd-jp'>休みじゃありませんでした</span> → <span class='gd-jp'>休みじゃなかった</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분이에요</div><div class='gd-warn'>・「昨日」가 앞에 있으니 충분하다고 생각해서 <span class='gd-jp'>昨日は休みです</span>처럼 현재형 그대로 말하기 쉬워요. 일본어에서는 <span class='gd-jp'>休みでした</span>로 바꿔야 해요.<br>・'아니었다'를 만들 때 가장 자주 틀려요. <span class='gd-jp'>学生じゃないでした</span>, <span class='gd-jp'>学生じゃでした</span>는 둘 다 틀렸고, <span class='gd-jp'>学生じゃありませんでした</span>라고 말해야 해요.<br>・일상 회화에서는 <span class='gd-jp'>学生じゃなかったです</span>도 자주 들려요. 이것도 공손하고 맞는 표현이니 들어도 놀라지 마세요.<br>・でした는 명사(와 な형용사) 뒤에만 붙일 수 있어요. <span class='gd-jp'>寒い</span>, <span class='gd-jp'>高い</span> 같은 い형용사에는 바로 でした를 붙일 수 없어요. <span class='gd-jp'>寒いでした</span>는 틀린 말이고, <span class='gd-jp'>寒かったです</span>라고 해야 해요.</div><div class='gd-h'>비슷하게 생긴 표현과 구별해요</div><div class='gd-sec'>똑같이 '어제' 일을 말해도 앞에 오는 말이 다르면 끝부분도 달라져요.<br><b>명사</b>＋でした: <span class='gd-jp'>昨日は雨でした。</span>(어제는 비 오는 날이었어요)<br><b>동사</b>는 ます를 ました로 바꿔요: <span class='gd-jp'>昨日は雨が降りました。</span>(어제 비가 내렸어요)<br><b>い형용사</b>는 い를 かったです로 바꿔요: <span class='gd-jp'>昨日は寒かったです。</span>(어제는 추웠어요)<br><b>な형용사</b>는 명사처럼 でした를 붙여요: <span class='gd-jp'>昨日は静かでした。</span>(어제는 조용했어요)</div><div class='gd-warn'>구별 요령: 앞이 명사나 な형용사면 でした, 동사면 ました, い형용사(寒い, 高い 등)면 かったです를 써요.<br>주의: <span class='gd-jp'>きれい</span>, <span class='gd-jp'>有名</span>, <span class='gd-jp'>嫌い</span>는 끝이 い라도 な형용사라서 でした를 써요. 예를 들어 <span class='gd-jp'>きれいでした</span>라고 하고, きれかったです라고는 하지 않아요.</div><div class='gd-h'>이걸 익히고 나면 이어서 배워요</div><div class='gd-sec'>동사의 과거 <span class='gd-jp'>〜ました・〜ませんでした</span>와 い형용사의 과거 <span class='gd-jp'>〜かったです</span>를 세 가지 함께 외워 두세요. 그러면 과거 이야기를 할 때 막히지 않아요.</div>","n5-6":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'>「〜ました」는 「〜ます」의 <b>과거형</b>이고, 「〜ませんでした」는 「〜ません」의 과거형이에요. 한국어에서 '갔어요'처럼 어미가 바뀌는 것과 똑같이, 일본어도 동사의 끝을 바꿔요. <span class='gd-pair'><span class='gd-jp'>行きます</span>(가요) → <span class='gd-jp'>行きました</span>(갔어요)</span>. ます처럼 공손한 말투라서 선생님이나 점원에게 써도 실례가 되지 않아요.</div><div class='gd-h'>어떻게 바꿀까요: ます형만 알면 끝이에요</div><div class='gd-sec'>'마시다'를 예로 네 가지 형태를 한 번에 볼게요.<br>현재, 해요: <span class='gd-jp'>飲みます</span>(마셔요)<br>현재, 안 해요: <span class='gd-jp'>飲みません</span>(안 마셔요)<br>과거, 했어요: <span class='gd-jp'>飲みました</span>(마셨어요)<br>과거, 안 했어요: <span class='gd-jp'>飲みませんでした</span>(안 마셨어요)<br><br>규칙은 딱 두 가지예요. <b>ます는 ました로 바꿔요</b>. <b>ません 뒤에는 でした를 붙여요</b>.<br>모두 ます형에서 바꾸기 때문에 세 가지 동사 그룹의 규칙이 완전히 같아요.<br><b>1그룹(5단 동사)</b>: <span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きました</span></span><br><b>2그룹(1단 동사)</b>: <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べました</span></span><br><b>3그룹(する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しました</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ました</span>(きました)</span></div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>했어요</span>이미 일어난 일을 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>先月、札幌へ行きました。</span>(지난달에 삿포로에 갔어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見ました。</span>(어제 영화를 봤어요)</div><div class='gd-sec'><span class='gd-tag'>안 했어요</span>과거의 그 시간 동안 하지 않은 일을 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ご飯を食べませんでした。</span>(오늘 아침에는 아침밥을 안 먹었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題をしませんでした。</span>(숙제를 안 했어요)</div><div class='gd-sec'><span class='gd-tag'>상대에게 물어요</span>뒤에 か를 붙이면 질문이 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、何をしましたか。</span>(주말에 뭐 했어요?)</div><div class='gd-h'>헷갈리기 쉬운 부분이에요</div><div class='gd-warn'>・과거 부정은 「ません＋<b>でした</b>」인데, 「食べませんました」처럼 말하는 사람이 많아요. 이건 틀렸어요.<br>・<span class='gd-jp'>来ました</span>는 <b>きました</b>라고 읽어요. こました가 아니에요.<br>・「ました」의 「し」는 아주 약하게 발음될 때가 많아서 「ma-shta」처럼 들려요. 들을 때 소리가 하나 빠졌다고 생각하지 마세요.<br>・'아직 안 먹었어요'에는 ませんでした를 쓰지 않아요. 친구가 <span class='gd-jp'>もう食べましたか。</span>(벌써 먹었어요?)라고 물었을 때 아직 안 먹었고 조금 있다가 먹을 거라면 <span class='gd-jp'>いいえ、まだです。</span>(아니요, 아직이에요)라고 대답해요. <span class='gd-jp'>食べませんでした</span>는 '그때 안 먹었어요'라는 뜻이고, 이미 지나간 일이에요.<br>・<span class='gd-jp'>分かりました</span>는 '알겠어요, 네'라는 뜻으로, 과거의 일이 아니라 지금의 상태를 말해요. 점원이나 동료가 이렇게 대답하면 '알겠습니다'라는 뜻이에요.</div><div class='gd-h'>비슷하게 생긴 표현과 구별해요</div><div class='gd-sec'>과거형을 배우면 「ました」와 「でした」를 가장 자주 헷갈려요. '어제 파티'를 예로 한 번에 정리해 볼게요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、パーティーに行きました。</span>(어제 파티에 갔어요: 동사는 ました)</div><div class='gd-ex-line'>・<span class='gd-jp'>料理は和食でした。</span>(요리는 일식이었어요: 명사는 でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>会場はきれいでした。</span>(행사장이 깨끗하고 예뻤어요: な형용사는 でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(아주 즐거웠어요: い형용사는 かったです)</div><div class='gd-sec'>자주 틀리는 예예요.<br>「学生ました」→ <span class='gd-jp'>学生でした</span>라고 해야 해요<br>「行きでした」→ <span class='gd-jp'>行きました</span>라고 해야 해요<br>「おいしいでした」→ <span class='gd-jp'>おいしかったです</span>라고 해야 해요</div><div class='gd-warn'>구별 요령: 앞이 동사면 ました, 명사나 な형용사면 でした, い형용사면 かったです를 써요.</div><div class='gd-h'>이걸 익히고 나면 이어서 배워요</div><div class='gd-sec'>친구와 이야기할 때는 과거형을 ます 없는 말투로 바꾸는데, 이것을 'た형／なかった형'이라고 해요. <span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span></div>","n5-3":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'><span class='gd-jp'>静か</span>(조용하다), <span class='gd-jp'>きれい</span>(예쁘다), <span class='gd-jp'>親切</span>(친절하다) 같은 형용사를 일본어에서는 <b>な형용사</b>라고 해요. '조용해요'는 <span class='gd-jp'>静かです</span>, '조용하지 않아요'는 <span class='gd-jp'>静かじゃありません</span>이라고 해요. 명사 문장과 쓰임이 거의 같고, 규칙이 딱 하나만 더 있어요. <b>명사 바로 앞에 올 때는 「な」를 붙여야 한다</b>는 거예요.</div><div class='gd-h'>な형용사란?</div><div class='gd-sec'>상태나 느낌을 나타내는 말로, 한국어로는 대개 '~해요', '~한'에 해당해요. 명사를 꾸밀 때 な가 붙어서 'な형용사'라고 불러요. 카드에 적힌 '어간'은 단어장에 나와 있는 원래 모양을 말해요. 예를 들어 <span class='gd-jp'>静か</span>에는 뒤에 아무것도 붙이지 않아요.<br>먼저 가장 자주 쓰는 단어들을 외워 두세요.<br><span class='gd-jp'>静か</span>(조용하다), <span class='gd-jp'>きれい</span>(예쁘다, 깨끗하다), <span class='gd-jp'>元気</span>(건강하다, 활기차다), <span class='gd-jp'>有名</span>(유명하다), <span class='gd-jp'>便利</span>(편리하다), <span class='gd-jp'>暇</span>(한가하다), <span class='gd-jp'>大変</span>(힘들다), <span class='gd-jp'>好き</span>(좋아하다), <span class='gd-jp'>嫌い</span>(싫어하다), <span class='gd-jp'>上手</span>(잘하다)</div><div class='gd-h'>어떻게 이어요?</div><div class='gd-sec'><span class='gd-tag'>긍정</span>원래 모양에 그대로 <span class='gd-jp'>です</span>를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この喫茶店は静かです。</span>(이 카페는 조용해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くは便利です。</span>(역 근처는 편리해요)</div><div class='gd-sec'><span class='gd-tag'>부정</span>원래 모양에 그대로 <span class='gd-jp'>じゃありません</span>을 붙여요. 앞의 글자는 전혀 바꾸지 않아요.<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇じゃありません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暇じゃありません。</span>(오늘은 한가하지 않아요)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は有名じゃありません。</span>(이 동네는 별로 유명하지 않아요)</div><div class='gd-sec'>부정에는 뜻이 같은 표현이 두 가지 더 있어요. <span class='gd-jp'>ではありません</span>은 좀 더 격식 있는 말로 교과서나 글에 자주 나오고, <span class='gd-jp'>じゃないです</span>는 좀 더 구어체지만 마찬가지로 정중해요.</div><div class='gd-sec'><span class='gd-tag'>질문</span>뒤에 <span class='gd-jp'>か</span>만 붙이면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変ですか。</span>(일은 힘든가요?)</div><div class='gd-h'>명사 앞에 올 때: な를 붙여요</div><div class='gd-sec'>'조용한 마을', '친절한 사람'이라고 하고 싶을 때는 중간에 <span class='gd-jp'>な</span>를 넣어요. 한국어의 '~한/~ㄴ'에 해당한다고 생각하면 쉬워요.<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋<span class='gd-jp'>町</span> → <span class='gd-jp'>静かな町</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かな町です。</span>(조용한 마을이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>京都はきれいな所です。</span>(교토는 아름다운 곳이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>親切な人ですね。</span>(친절한 사람이네요)</div><div class='gd-sec'>기억하기는 간단해요. <b>뒤에 です가 오면 な를 붙이지 않고, 뒤에 명사가 오면 な를 붙여요</b>.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>는 끝에 「い」가 있어서 い형용사처럼 보이지만 사실 な형용사예요. 부정은 <span class='gd-jp'>きれいじゃありません</span>이고, 「きれくないです」가 아니에요.<br>・です 앞에는 な를 붙이지 마세요. <span class='gd-jp'>静かです</span>가 맞고, 「静かなです」는 틀려요.<br>・명사 앞에서 な를 빼먹으면 안 돼요. 그렇다고 の를 넣어도 안 돼요. <span class='gd-jp'>静かな町</span>이 맞고, 「静か町」도 「静かの町」도 틀려요.<br>・<span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span>의 대상에는 <b>が</b>를 써요. <span class='gd-jp'>猫が好きです</span>(고양이를 좋아해요). 한국어는 '고양이를 좋아해요'처럼 '를'을 쓰다 보니 「猫を好きです」라고 쓰는 학습자가 많아요. 처음에는 が를 쓴다고 외워 두세요.<br>・「嫌いです」라고 바로 말하면 좀 세게 들려요. 일본 사람들은 <span class='gd-jp'>あまり好きじゃありません</span>(별로 좋아하지 않아요)이라고 많이 말해요. 훨씬 부드럽게 들려요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>같은 '이 가게'를 말할 때도 품사에 따라 부정 형태가 달라요.<br><b>い형용사</b>: 끝의 い를 くない로 바꿔요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くないです。</span>(이 가게는 싸지 않아요)</div><div class='gd-sec'><b>な형용사</b>: 본체는 그대로 두고 뒤에 じゃありません을 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店はきれいじゃありません。</span>(이 가게는 깨끗하지 않아요)</div><div class='gd-sec'><b>명사</b>: な형용사와 마찬가지로 뒤에 じゃありません을 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここは銀行じゃありません。</span>(여기는 은행이 아니에요)</div><div class='gd-warn'>구분 요령: 단어를 외울 때 な까지 함께 <span class='gd-jp'>きれいな</span>, <span class='gd-jp'>静かな</span>처럼 외우세요. 「～な＋명사」로 쓰는 말은 부정할 때 그냥 じゃありません을 붙이면 되고, い형용사만 い를 くない로 바꿔요.</div><div class='gd-h'>다 배웠다면 이어서 배워요</div><div class='gd-sec'>과거형은 です를 でした로 바꿔요. <span class='gd-jp'>昨日は暇でした。</span>(어제는 한가했어요)</div>","n5-4":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>'춥다', '비싸다', '맛있다'처럼 사물의 상태를 나타내는 말을 일본어에서는 <b>い형용사</b>라고 해요. 마지막 글자가 모두 「い」이기 때문이에요. 예를 들면 <span class='gd-jp'>寒い</span>, <span class='gd-jp'>高い</span>, <span class='gd-jp'>おいしい</span>가 있어요.<br>정중하게 '추워요'라고 하려면 뒤에 바로 <b>です</b>를 붙여요. '춥지 않아요'라고 하려면 마지막의 い를 <b>く</b>로 바꾸고 <b>ないです</b>를 붙여요.</div><div class='gd-h'>어떻게 이어요?</div><div class='gd-sec'><span class='gd-tag'>긍정</span>원래 모양에 그대로 です를 붙여요. 마지막의 い는 바꾸지 않아요.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いです</span></span></div><div class='gd-sec'><span class='gd-tag'>부정</span>마지막의 い를 く로 바꾸고 ないです를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い를 く로 → <span class='gd-jp'>寒く</span> → <span class='gd-jp'>寒くないです</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くないです</span></span><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしくないです</span></span><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくないです</span></span></div><div class='gd-sec'>교과서에서는 <span class='gd-jp'>寒くありません</span>도 볼 수 있어요. 뜻은 같고 조금 더 격식 있게 들려요. 일상 대화에서는 「くないです」만으로 충분해요.</div><div class='gd-h'>실제로 말해 봐요</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいです。</span>(이 라면은 맛있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は広くないです。</span>(이 방은 넓지 않아요)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はあまり寒くないです。</span>(오늘은 별로 춥지 않아요)</div><div class='gd-sec'>한국어로 '추워요'라고 하면 그 자체로 충분하듯이, <span class='gd-jp'>寒いです</span>도 그것만으로 완전한 문장이에요. 억지로 「とても」를 붙일 필요가 없어요. 정말 춥다고 강조하고 싶을 때만 <span class='gd-jp'>とても寒いです</span>라고 해요.<br>또 <span class='gd-jp'>あまり</span> 뒤에 부정이 오면 '<b>별로</b> ~하지 않아요'라는 뜻이에요. 그냥 '~하지 않아요'보다 완곡해서 일본 사람들이 아주 많이 써요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>는 예외예요. 부정은 <b><span class='gd-jp'>よくないです</span></b>이고, いくないです가 아니에요. いい는 원래 <span class='gd-jp'>よい</span>에서 온 말이라서 활용할 때 よ를 써요. <span class='gd-jp'>かっこいい</span>도 마찬가지로 부정은 <span class='gd-jp'>かっこよくないです</span>예요.<br>・'춥지 않아요'를 寒いじゃないです라고 하면 안 돼요. い형용사의 부정은 반드시 い를 く로 바꾸고, じゃない는 쓰지 않아요.<br>・중간에 だ를 넣지 마세요. 寒いだです는 틀린 문장이에요. 정중하게 말할 때는 <span class='gd-jp'>寒いです</span>, 친구에게는 그냥 <span class='gd-jp'>寒い</span>라고 해요.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>有名</span>도 끝이 「い」로 들리지만 な형용사예요. 부정은 <span class='gd-jp'>きれいじゃないです</span>이고, きれくないです가 아니에요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>같은 '이 방은 ~하지 않아요'라도 앞에 어떤 품사가 오느냐에 따라 부정하는 방법이 달라요.<br><b>い형용사</b>: い를 く로 바꾸고 ないです를 붙여요<br>・<span class='gd-jp'>この部屋は明るくないです。</span>(이 방은 밝지 않아요)<br><b>な형용사</b>: 뒤에 じゃないです를 붙여요<br>・<span class='gd-jp'>この部屋は静かじゃないです。</span>(이 방은 조용하지 않아요)<br><b>명사</b>: 뒤에 じゃないです를 붙여요<br>・<span class='gd-jp'>ここは私の部屋じゃないです。</span>(여기는 제 방이 아니에요)</div><div class='gd-warn'>구분 요령: 원래 끝이 「い」인 말은 い를 く로 바꾸고 ないです를 붙여요. な형용사와 명사는 그냥 じゃないです를 붙여요. きれい, 嫌い, 有名은 な형용사이니 특히 조심하세요.</div><div class='gd-h'>다 배웠다면 이어서 배워요</div><div class='gd-sec'>과거형: <span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒かったです</span></span>(전에 추웠어요)<br>변화를 나타내는 표현: <span class='gd-jp'>寒くなります</span>(추워져요). 부정에서 쓴 「く」가 여기서도 다시 나와요.</div>","n5-9":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「〜ませんか」는 한국어의 <b>「같이 ~할래요?」</b>예요. 글자만 보면 「~하지 않아요?」 같은 부정 의문문처럼 보이지만, 권유할 때 일본 사람들은 이 표현으로 「~하실래요?」 하고 정중하게 물어봐요. 결정권을 상대에게 넘기니까 상대도 거절하기 편하고, 그래서 예의 바르게 들려요. 한국어의 「같이 가지 않을래요?」와 느낌이 비슷하죠.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>권유</span>상대에게 같이 어디 가자거나 같이 뭘 하자고 할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>今度の日曜日、山登りに行きませんか。</span>(이번 일요일에 등산 갈래요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に昼ご飯を食べませんか。</span>(같이 점심 먹을래요?)</div><div class='gd-sec'><span class='gd-tag'>음식 권하기, 제안</span>먹을 것이나 마실 것을 권하거나, 상대에게 뭔가를 제안할 때도 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、食べませんか。</span>(이 케이크 드실래요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休みませんか。</span>(잠깐 쉴까요?)</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>동사를 먼저 ます형으로 만든 다음, 「ます」를 「<b>ませんか</b>」로 바꾸면 끝이에요.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きませんか</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べませんか</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しませんか</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ませんか</span>（きませんか）</span><br>사실 「ません」(~하지 않아요) 뒤에 의문의 「か」를 붙인 것뿐이에요.</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>〜でも〜ませんか</span>명사 뒤에 「でも」를 붙이면 「~라도」, 「~ 같은 거」라는 뜻이 돼요. 권유가 더 편하고 부담 없게 들려요.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーでも飲みませんか。</span>(커피라도 한잔 할래요?)</div><div class='gd-sec'><span class='gd-tag'>대답하는 법</span>수락: <span class='gd-jp'>いいですね。</span>(좋아요), <span class='gd-jp'>ぜひ。</span>(꼭 가요)<br>거절: <span class='gd-jp'>すみません、その日はちょっと…。</span>(죄송해요, 그날은 좀…)</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・부정형이니까 「안 가요?」라고 직역해서 읽으면 안 돼요. 권유할 때 <span class='gd-jp'>行きませんか</span>는 「갈래요?」이지 「안 가세요?」가 아니에요.<br>・거절할 때 <span class='gd-jp'>いいえ、行きません。</span>(아니요, 안 가요)라고 곧바로 말하면 너무 딱딱하고 상대에게 상처가 될 수 있어요. 일본 사람들은 「<span class='gd-jp'>ちょっと…</span>」 하고 말끝을 흐려요. 그러면 상대도 알아듣고요.<br>・「<b>제가</b> ~해 드릴까요?」라는 뜻으로는 ませんか를 쓸 수 없어요. <span class='gd-jp'>持ちませんか</span>는 상대에게 들어 달라는 말이에요. 「제가 들어 드릴까요?」는 <span class='gd-jp'>持ちましょうか</span>라고 해야 해요.<br>・친한 친구에게는 그렇게 정중할 필요 없이, 보통형에 억양만 올려서 말해요: <span class='gd-jp'>行かない？</span>(갈래?)</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 상황인 영화 보러 가는 대화로 비교해 볼게요.<br><b>ませんか</b>＝아직 정하지 않아서 상대의 의향을 먼저 물어봐요: <span class='gd-jp'>一緒に映画を見ませんか。</span>(같이 영화 볼래요?)<br><b>ましょう</b>＝이미 이야기가 됐거나 둘 다 하고 싶을 때 가볍게 밀어 줘요: <span class='gd-jp'>いいですね。見ましょう。</span>(좋아요, 봐요)<br><b>ましょうか</b>＝먼저 나서서 「제가 ~할까요?」 하고 도움을 제안해요: <span class='gd-jp'>チケット、買いましょうか。</span>(티켓은 제가 살까요?)</div><div class='gd-sec'>그래서 가장 흔한 순서는 먼저 「ませんか」로 권유하고, 상대가 고개를 끄덕이면 「ましょう」로 같이 정하는 거예요. 처음부터 「ましょう」라고 하면 상대에게 묻지도 않고 정해 버린 것처럼 들릴 수 있어요.</div><div class='gd-warn'>구분 요령: 아직 「할래요?」 하고 묻는 중이면 ませんか, 이미 「그렇게 해요」 하고 정했으면 ましょう, 「제가 도와 드릴게요」면 ましょうか를 써요.</div>","n5-10":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「〜なります」는 한국어의 <b>「~해지다」「~이/가 되다」</b>예요. 날씨가 더웠다가 추워질 때, 방이 어질러졌다가 깨끗해질 때, 아이가 자라서 어른이 될 때처럼 <b>한 상태에서 다른 상태로 변할 때</b>는 일본어로 なります를 써요.</div><div class='gd-h'>접속 방법: 앞에 오는 말부터 확인해요</div><div class='gd-sec'><b>い형용사</b>: 마지막 「い」를 「く」로 바꾸고 なります를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い를 く로 → <span class='gd-jp'>寒くなります</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくなります</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くなります</span></span></div><div class='gd-sec'><b>な형용사</b>: 뒤에 「に」를 붙이고 なります를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいになります</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気になります</span></span><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きになります</span></span></div><div class='gd-sec'><b>명사</b>: な형용사와 똑같이 「に」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春になります</span></span><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者になります</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寒くなりましたね。</span>(추워졌네요)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋がきれいになりました。</span>(방이 깨끗해졌어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本が好きになりました。</span>(일본이 좋아졌어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>来月、二十歳になります。</span>(다음 달에 스무 살이 돼요)</div><div class='gd-h'>なります와 なりました, 어떻게 고를까요</div><div class='gd-sec'>한국어로 「추워졌어요」처럼 이미 변했을 때는 일본어도 <b>なりました</b>를 써요. 이미 변해서 지금은 그 상태라는 뜻이에요.<br><b>なります</b>는 「~이/가 될 거예요」「곧 ~해져요」처럼 아직 일어나지 않았거나 늘 그렇게 되는 일을 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>もうすぐ夏になります。</span>(곧 여름이 돼요)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んで、よくなりました。</span>(약을 먹고 좋아졌어요)</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>는 예외예요. <span class='gd-jp'>よくなります</span>라고 해야 하고, いくなります라고는 하지 않아요. 병이 나았을 때도, 날씨가 좋아졌을 때도 <span class='gd-jp'>よくなりました</span>라고 해요.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>きらい</span>, <span class='gd-jp'>有名</span>는 끝소리가 「い」지만 な형용사예요. <span class='gd-jp'>きれいになります</span>가 맞고, きれくなります는 틀려요.<br>・명사와 な형용사 뒤의 「に」는 빼먹으면 안 돼요. <span class='gd-jp'>先生になりました</span>가 맞고, 先生なりました는 틀려요.<br>・「날씨가 추워졌어요」라고 하고 싶을 때 <span class='gd-jp'>寒いです</span>라고만 하는 분이 많아요. 이건 그냥 「지금 추워요」라는 뜻이라 「변했다」는 느낌이 없어요. 추워졌다는 걸 강조하려면 <span class='gd-jp'>寒くなりました</span>라고 해야 해요.<br>・「무엇이 변했는지」를 말하는 앞부분에는 <span class='gd-jp'>が</span>(또는 <span class='gd-jp'>は</span>)를 쓰고, を는 쓰지 않아요. <span class='gd-jp'>部屋がきれいになりました</span>처럼요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>다음 과의 「〜くします・〜にします」는 한 글자만 다른데 뜻은 달라요. 같은 방이 깨끗해지는 상황으로 비교해 볼게요.<br><b>なります</b>＝<b>사물이</b> 어떤 상태로 <b>변한다</b>고 말해요. 초점은 결과예요: <span class='gd-jp'>部屋がきれいになりました。</span>(방이 깨끗해졌어요)<br><b>します</b>＝<b>누군가가</b> 사물을 어떤 상태로 <b>만든다</b>고 말해요. 초점은 누가 손을 댔는지예요: <span class='gd-jp'>部屋をきれいにしました。</span>(방을 깨끗하게 청소했어요)<br>한 쌍 더 볼게요: <span class='gd-jp'>音が大きくなりました。</span>(소리가 커졌어요)／<span class='gd-jp'>音を小さくしてください。</span>(소리를 작게 해 주세요)</div><div class='gd-warn'>구분 요령: 한국어로 「~이/가 ~해지다·~이/가 되다」면 <b>が＋なります</b>, 「~을/를 ~하게 하다·~게 만들다」면 <b>を＋します</b>를 써요.</div><div class='gd-h'>익히고 나면 이어서 배워 보세요</div><div class='gd-sec'>동사에는 なります를 바로 붙일 수 없어요. 「~할 수 있게 됐어요」라고 말하려면 N4의 「〜ようになります」를 써요: <span class='gd-jp'>日本語が話せるようになりました。</span>(일본어를 할 수 있게 됐어요)</div>","n5-16":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「も」는 한국어의 <b>「도」</b>와 거의 같아요. 위치도 한국어와 똑같아서, <b>'도'를 붙일 말 바로 뒤</b>에 붙여요(<span class='gd-jp'>私も</span>＝나도).</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><span class='gd-tag'>は・が・を</span>이 세 가지는 <b>빼고 も로 바꿔요</b>. 한국어에서 은/는/이/가/을/를을 빼고 '도'를 붙이는 것과 같아요.<br><span class='gd-pair'><span class='gd-jp'>私は</span> → <span class='gd-jp'>私も</span></span><span class='gd-pair'><span class='gd-jp'>猫が</span> → <span class='gd-jp'>猫も</span></span><span class='gd-pair'><span class='gd-jp'>コーヒーを</span> → <span class='gd-jp'>コーヒーも</span></span></div><div class='gd-sec'><span class='gd-tag'>に・で・へ・と</span>이 조사들은 <b>그대로 두고</b> 뒤에 も를 더해요. 한국어의 '에도', '에서도'와 같은 느낌이에요.<br><span class='gd-pair'><span class='gd-jp'>大阪に</span> → <span class='gd-jp'>大阪にも</span></span><span class='gd-pair'><span class='gd-jp'>家で</span> → <span class='gd-jp'>家でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>大阪にも行きました。</span>(오사카에도 갔어요)</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>~도</span>앞에서 한 이야기에 같은 내용을 하나 더 보탤 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：私は学生です。B：私も学生です。</span>(A: 저는 학생이에요. B: 저도 학생이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>A：コーヒーが好きです。B：私も。</span>(A: 커피를 좋아해요. B: 저도요)</div><div class='gd-sec'><span class='gd-tag'>AもBも</span>둘 다 같다는 뜻으로, 「A도 B도 ~」예요. 뒤에 부정이 오면 「둘 다 ~않다」가 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンもケーキも好きです。</span>(빵도 케이크도 좋아해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>肉も魚も食べません。</span>(고기도 생선도 안 먹어요)</div><div class='gd-sec'><span class='gd-tag'>의문사＋も＋부정</span>「아무것도」「아무도」「어디에도」처럼, 뒤에는 반드시 부정이 와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べませんでした。</span>(오늘 아침에는 아무것도 안 먹었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室には誰もいません。</span>(교실에는 아무도 없어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末はどこにも行きませんでした。</span>(주말에는 어디에도 안 갔어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>はも</span>, <span class='gd-jp'>がも</span>, <span class='gd-jp'>をも</span> 같은 표현은 없어요. は・が・を는 그냥 も로 바꿔야 해요.<br>・も가 누구 뒤에 붙느냐에 따라 '도'의 대상이 달라지고, 뜻도 많이 달라져요.<br><span class='gd-jp'>私もコーヒーを飲みます。</span>(다른 사람이 커피를 마시고, <b>나도</b> 마셔요)<br><span class='gd-jp'>私はコーヒーも飲みます。</span>(나는 차를 마시고, <b>커피도</b> 마셔요)<br>한국어로는 둘 다 '나도 커피를 마셔요'처럼 들릴 수 있지만, 일본어는 も 바로 앞의 말이 '도'의 대상이에요. 사람이 '도'인지 커피가 '도'인지 먼저 생각해 보세요.<br>・<span class='gd-jp'>何も</span>, <span class='gd-jp'>誰も</span> 뒤에는 부정이 와요. '뭐든 좋아해요'라고 말하고 싶을 때 何も好きです라고 하면 안 되고, 다른 표현(<span class='gd-jp'>何でも好きです</span> 등, 나중에 배워요)을 써야 해요.<br>・'어디에도 안 갔어요'는 <span class='gd-jp'>どこにも</span>라고 해요. に를 빠뜨리지 마세요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><b>AとB</b>＝그냥 두 가지를 나열해요: <span class='gd-jp'>パンとケーキが好きです。</span>(빵과 케이크를 좋아해요)<br><b>AもBも</b>＝「둘 <b>다</b>」를 강조해요: <span class='gd-jp'>パンもケーキも好きです。</span>(빵도 케이크도 둘 다 좋아해요)<br>접속 방법도 달라요. と는 가운데에 한 번만 넣고, も는 <b>각각의 뒤에 모두 붙여요</b>.</div><div class='gd-warn'>구별 요령: 그냥 나열할 때는 と, 「둘 다 ~」를 강조하고 싶을 때는 〜も〜も를 쓰세요.</div>","n5-17":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「の」는 한국어의 <b>「의」</b>와 비슷해요. 명사 두 개를 이어 주고, 앞의 말이 뒤의 말을 설명해요. <span class='gd-jp'>私の本</span>＝내 책. 순서도 한국어와 같아서, 앞에 「누구의, 어디의」를 말하고 뒤에 물건 자체가 와요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>명사A＋の＋명사B＝「A의 B」. 주인공은 B이고, A는 「어떤 B인지」를 보충 설명해요.<br><span class='gd-pair'><span class='gd-jp'>弟</span>＋<span class='gd-jp'>車</span> → <span class='gd-jp'>弟の車</span></span>(동생의 차)<br><span class='gd-pair'><span class='gd-jp'>数学</span>＋<span class='gd-jp'>教科書</span> → <span class='gd-jp'>数学の教科書</span></span>(수학 교과서)</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>누구의 물건</span>물건의 주인을 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の本です。</span>(이건 제 책이에요)</div><div class='gd-sec'><span class='gd-tag'>소속</span>어느 회사, 어느 학교 사람인지 말해요. 자기소개나 전화할 때 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>さくら銀行の山田です。</span>(사쿠라 은행의 야마다예요)</div><div class='gd-sec'><span class='gd-tag'>어떤 내용</span>그 물건이 무엇에 관한 것인지 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>数学の教科書を忘れました。</span>(수학 교과서를 깜빡했어요)</div><div class='gd-sec'><span class='gd-tag'>어디의</span>물건이나 사람이 어디에서 왔는지, 어디에 있는지 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾のお茶はおいしいです。</span>(대만 차는 맛있어요)</div><div class='gd-h'>뒤의 명사는 생략할 수 있어요</div><div class='gd-sec'>무엇을 말하는지 모두가 알 때는 B를 말하지 않고 「A の」만 말해도 돼요. <span class='gd-jp'>私の</span>는 「제 것」이라는 뜻이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>「これは誰の傘ですか。」「私のです。」</span>(「이건 누구 우산이에요?」「제 거예요.」)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>한국어에서는 「의」를 자주 생략하지만, 일본어에서는 생략할 수 없어요.</b> 한국어는 「우리 엄마」「내 친구」「일본어 선생님」처럼 「의」 없이 말하지만, 일본어는 <span class='gd-jp'>私の母</span>, <span class='gd-jp'>私の友達</span>, <span class='gd-jp'>日本語の先生</span>처럼 の를 꼭 넣어야 해요. 「私母」「日本語先生」라고 하면 틀려요.<br>・<b>の가 여러 개 이어져도 그대로 붙여요.</b> 「내 친구의 차」처럼 한국어에서는 하나만 쓰거나 생략하기도 하지만, 일본어는 두 개 다 필요해요: <span class='gd-jp'>私の友達の車</span>.<br>・<b>「이 책」은 <span class='gd-jp'>この本</span>이고, 「これの本」가 아니에요.</b> <span class='gd-jp'>この</span> 자체가 「이」라는 뜻이라서, 뒤에 명사를 바로 붙이면 되고 の는 필요 없어요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>한국어에서 「의」는 명사 뒤에만 붙고, 형용사는 「새 차」「예쁜 차」처럼 형태를 바꿔서 명사를 꾸며요. 일본어도 앞에 오는 품사에 따라 달라져요.<br><b>명사</b>(사람, 물건, 장소)는 の를 붙여요: <span class='gd-jp'>日本の車</span>(일본 차)<br><b>い형용사</b>(<span class='gd-jp'>新しい</span>, <span class='gd-jp'>おいしい</span> 등)는 の 없이 바로 이어요: <span class='gd-jp'>新しい車</span>(새 차). 「新しいの車」는 틀려요<br><b>な형용사</b>(<span class='gd-jp'>きれい</span>, <span class='gd-jp'>静か</span> 등)는 な를 붙여요: <span class='gd-jp'>きれいな車</span>(예쁜 차). 「きれいの車」는 틀려요</div><div class='gd-warn'>구별 요령: 앞이 「누구, 무엇, 어디」 같은 명사일 때만 の를 쓰고, 「어떠한지」를 나타내는 형용사일 때는 の를 쓰지 않아요.</div><div class='gd-h'>다 배운 뒤에 이어서 배워요</div><div class='gd-sec'>「の」에는 또 다른 역할이 있어요. 동사 뒤에 붙어서 동작을 「~하는 것」으로 바꿔 줘요. 예를 들면 <span class='gd-jp'>本を読むのが好きです。</span>(책 읽는 것을 좋아해요)처럼요. 이건 나중에 「형식명사 の」에서 배우는데, 여기서 배운 「의」와는 다른 용법이에요.</div>","n5-20":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>「へ」는 한국어의 <b>「～로」「～쪽으로」</b>에 가까워요. 장소 뒤에 붙여서 어디를 향해 이동하는지 알려 줘요. <span class='gd-jp'>日本へ行きます</span>는 「일본으로 가요」, 즉 「일본에 가요」라는 뜻이에요. 글자는 へ로 쓰지만 조사로 쓸 때는 <b>「e」로 읽고</b>, 「he」로 읽지 않아요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>장소＋へ＋이동 동사(<span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span> 같은 동사)예요.<br><span class='gd-pair'><span class='gd-jp'>学校</span> → <span class='gd-jp'>学校へ行きます</span></span>(학교에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、京都へ行きます。</span>(내일 교토에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは去年日本へ来ました。</span>(다나카 씨는 작년에 일본에 왔어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>6時にうちへ帰ります。</span>(6시에 집에 돌아가요)</div><div class='gd-sec'>상대방에게 어디에 가는지 물을 때는 장소 자리에 <span class='gd-jp'>どこ</span>를 넣으면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、どこへ行きますか。</span>(주말에 어디에 가요?)</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・읽는 법: 조사 へ는 「e」로 읽어요. <span class='gd-jp'>は</span>를 조사로 쓸 때 「wa」로 읽는 것과 같은 경우예요. 하지만 <b>쓸 때는 반드시 へ로 써야 해요</b>. え로 쓰면 안 돼요.<br>・뒤에는 「이동」 동사가 와야 해요. 한국어로는 「도서관에 공부하러 가요」가 자연스럽지만, 「도서관에서 공부해요」처럼 동작이 일어나는 장소에는 <span class='gd-jp'>で</span>를 써요. <span class='gd-jp'>図書館で勉強します</span>라고 해야 하고, <span class='gd-jp'>図書館へ勉強します</span>라고 하면 안 돼요.<br>・시간에는 へ를 쓸 수 없어요. 「내일 가요」는 <span class='gd-jp'>明日、行きます</span>라고 하고, 明日へ라고 하지 않아요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><span class='gd-tag'>へ와 に</span>어디로 「가다, 오다, 돌아가다」라고 말할 때는 둘 다 대부분 바꿔 쓸 수 있고, 뜻도 같아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>東京へ行きます。</span>(도쿄에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>東京に行きます。</span>(도쿄에 가요)</div><div class='gd-sec'>굳이 차이를 말하면 <b>へ</b>는 「그 방향을 향해」, <b>に</b>는 「그 지점에 도착」하는 느낌이에요. 일상 대화에서는 に를 더 많이 써요. 「도착」이 핵심이라면, 예를 들어 <span class='gd-jp'>着きます</span>(도착해요)는 보통 に를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着きました。</span>(역에 도착했어요)</div><div class='gd-sec'><span class='gd-tag'>へ와 で</span>へ는 「어디로 가는지」, で는 「어디에서 무엇을 하는지」를 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館へ行きます。</span>(도서관에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館で勉強します。</span>(도서관에서 공부해요)</div><div class='gd-warn'>구별 요령: 뒤에 「行く, 来る, 帰る」 같은 이동 동사가 오면 へ와 に 둘 다 쓸 수 있어요. 「어디에서 무엇을 한다」는 で를 써요. 시간에는 へ를 쓸 수 없어요. 7時, 月曜日처럼 구체적인 시점에는 に를 붙이고, 明日, 来週 같은 시간어에는 조사를 붙이지 않아요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'><span class='gd-jp'>から</span>(~부터)와 <span class='gd-jp'>まで</span>(~까지)를 함께 쓰면 이동의 출발점과 도착점을 완전하게 말할 수 있어요. 그다음에 「で(교통수단)」를 배우면 <span class='gd-jp'>電車で会社へ行きます</span>(전철을 타고 회사에 가요)처럼 말할 수 있어요.</div>","n5-21":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>「で」를 교통수단 뒤에 붙이면 한국어의 <b>「～을 타고」「～로」「～을 운전해서」</b>에 해당해요. 한국어는 교통수단에 따라 동사가 달라지지만, 일본어는 무엇을 타든 전부 「교통수단＋で」예요. 뒤에는 <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>만 붙이면 돼요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>교통수단＋で＋行きます／来ます／帰ります예요. 앞에는 명사를 그대로 두고, 따로 활용하지 않아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で会社に行きます。</span>(전철을 타고 회사에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>自転車で学校へ行きます。</span>(자전거를 타고 학교에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>バスで帰ります。</span>(버스를 타고 집에 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>飛行機で来ました。</span>(비행기를 타고 왔어요)</div><div class='gd-sec'>잘 보세요. 한국어에서는 「타고, 운전해서」처럼 나뉘는 표현이 일본어에서는 전부 똑같이 「で」예요. <span class='gd-jp'>車で行きます</span>도 마찬가지예요. 직접 운전할 수도 있고 다른 사람의 차를 탈 수도 있는데, 일본어는 이를 따로 구분하지 않아요.</div><div class='gd-h'>「어떻게 왔어요?」라고 묻고 싶을 때</div><div class='gd-sec'>교통수단 자리에 「何」를 넣으면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>何で来ましたか。</span>(뭘 타고 왔어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>タクシーで来ました。</span>(택시를 타고 왔어요)</div><div class='gd-sec'>여기서 「何で」는 <b>なにで</b>라고 읽어요. なんで라고 읽으면 「왜 왔어요?」로 들리기 쉬워요.</div><div class='gd-h'>헷갈리기 쉬운 점</div><div class='gd-warn'>・<b>걸어갈 때는 で를 쓰지 않아요</b>. 「足で行きます」라고 하지 말고 <span class='gd-jp'>歩いて行きます</span>(걸어서 가요)라고 해요. 이 문장은 일단 통째로 외워 두세요.<br>・「버스에 타다」라는 동작에는 「に」를 써요. <span class='gd-jp'>バスに乗ります</span>(버스를 타요)라고 해요. 「バスで乗ります」라고 말하는 사람이 많은데 틀린 표현이에요.<br>・순서는 바꿔도 돼요. <span class='gd-jp'>電車で東京へ行きます</span>와 <span class='gd-jp'>東京へ電車で行きます</span>는 둘 다 맞아요. 「で」가 교통수단 바로 뒤에 붙어 있기만 하면 돼요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><b>で(교통수단)</b>＝무엇으로 「이동」하는지를 나타내요. <span class='gd-jp'>バスで駅へ行きます。</span>(버스를 타고 역에 가요)<br><b>に＋乗ります</b>＝어떤 차량에 「타는」지를 나타내요. <span class='gd-jp'>駅でバスに乗ります。</span>(역에서 버스를 타요)<br><b>で(동작 장소)</b>＝어디에서 무엇을 하는지를 나타내요. 위 문장의 <span class='gd-jp'>駅で</span>는 「역에서」라는 뜻이에요. 앞에 온 것이 교통수단이 아니라 장소예요.</div><div class='gd-warn'>구별 요령: 뒤에 「가다, 오다, 돌아가다」가 오면 교통수단 뒤에 で를 써요. 뒤에 「乗ります」가 오면 に를 써요. 앞에 교통수단이 아니라 장소가 오면 그 で는 「～에서」라는 뜻이에요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>이 「で」는 사실 「～로, ～을 써서」라는 뜻이라서 교통수단뿐 아니라 젓가락으로 먹기, 일본어로 말하기에도 쓰여요. <span class='gd-jp'>はしで食べます。</span>(젓가락으로 먹어요) 이것이 다음 카드인 「조사 で(수단・도구)」예요.</div>","n5-18":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「か」는 한국어의 <b>「~까?」</b>에 해당해요. 문장 맨 끝에 か를 붙이면 평서문이 의문문으로 바뀌어요. <span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですか</span></span>, 「학생입니다」가 「학생입니까?」가 되는 거예요.</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>정중한 표현은 아주 간단해요. 문장 끝이 <b>です</b>나 <b>ます</b>이면 바로 뒤에 か만 붙이면 되고, 앞부분은 하나도 바꾸지 않아도 돼요.<br><span class='gd-pair'><span class='gd-jp'>日本人です</span> → <span class='gd-jp'>日本人ですか</span></span><br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですか</span></span><br><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かですか</span></span><br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますか</span></span><br><span class='gd-pair'><span class='gd-jp'>食べました</span> → <span class='gd-jp'>食べましたか</span></span></div><div class='gd-h'>언제 쓰나요</div><div class='gd-sec'><span class='gd-tag'>맞는지 물을 때</span>상대방이 「はい」나 「いいえ」로 대답하면 되는 질문이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本の本ですか。</span>(이건 일본 책이에요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、おいしいですか。</span>(이 라멘, 맛있어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、学校へ行きますか。</span>(내일 학교에 가요?)</div><div class='gd-sec'>대답할 때 명사문은 보통 <span class='gd-jp'>はい、そうです。</span>(네, 맞아요) 또는 <span class='gd-jp'>いいえ、違います。</span>(아니요, 아니에요)를 써요. 동사나 형용사는 원래 말을 한 번 더 말하면 돼요. <span class='gd-jp'>はい、行きます。</span>(네, 갈 거예요) / <span class='gd-jp'>いいえ、行きません。</span>(아니요, 안 가요)</div><div class='gd-sec'><span class='gd-tag'>의문사와 함께</span>문장에 「무엇, 어디, 언제」 같은 말이 있어도 か를 똑같이 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅はどこですか。</span>(실례합니다, 역이 어디예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、何を食べましたか。</span>(어제 뭐 먹었어요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>의문사가 있어도 か를 붙여요</b>: 한국어는 「이게 뭐예요?」처럼 해요체에서 「?」만 붙이면 되니까 か를 빼먹는 사람이 많아요. 하지만 일본어 정중한 표현에서는 꼭 か를 붙여서 <span class='gd-jp'>何ですか</span>라고 해야 하고, 「何です」만 말하면 안 돼요.<br>・<b>끝을 올려 말해요</b>: 「ですか」의 か는 올려 읽어요. <span class='gd-jp'>そうですか</span>는 올리면 「그래요?」라는 질문이고, 내리면 「아, 그렇군요」처럼 알겠다는 뜻이 돼서 의미가 달라요.<br>・<b>친구에게는 보통 か를 붙이지 않아요</b>: です、ます가 없는 말투로 끝을 올리면 바로 의문문이 돼요. <span class='gd-jp'>明日、行く？</span>(내일 가?), <span class='gd-jp'>これ、おいしい？</span>(이거 맛있어?) 반말에 か를 바로 붙이면(예: 「行くか」) 세고 거칠게 들리니까 초보자는 아직 쓰지 않는 게 좋아요.<br>・명사 의문문을 친구에게 말할 때는 <span class='gd-jp'>学生？</span>라고 해요. 「学生だか」라고 하면 의문문이 아니에요.<br>・<b>문장부호</b>: 교재나 격식 있는 글에서는 か 자체가 질문을 나타내니까 뒤에 보통 「。」를 찍어요. LINE 메시지나 만화에서는 「？」도 자주 보여요. 둘 다 볼 수 있어요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><b>ますか</b>＝상대방이 그 일을 하는지, 할 건지 단순히 물어요.<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、パーティーに行きますか。</span>(내일 파티에 가요?)</div><b>ませんか</b>＝<b>상대방에게 권유</b>해요. 같이 하자는 뜻이에요.<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、一緒にパーティーに行きませんか。</span>(내일 같이 파티에 가지 않을래요?)</div>두 문장은 아주 조금만 달라 보이지만, 첫 번째는 상대방의 계획을 묻는 말이고 두 번째는 함께 가자고 권하는 말이에요.</div><div class='gd-warn'>구별 요령: 상대방이 하는지 안 하는지만 알고 싶으면 「ますか」, 같이 하자고 권하고 싶으면 「ませんか」를 써요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>「何、どこ、いつ、だれ」 같은 의문사를 익히면 다양한 질문을 할 수 있어요. 그다음 「〜ませんか」를 배우면 상대방에게 먼저 권유도 할 수 있어요.</div>","n5-19":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「に」를 시간 뒤에 붙이면 한국어의 「7시<b>에</b>」「3월<b>에</b>」처럼 어떤 일을 특정한 시점에 콕 짚어 줘요. 한국어와 아주 비슷해서 이해하기 쉬울 거예요. 일본어에서는 <b>숫자가 있는 시간</b>이라면 반드시 に를 붙여요. <span class='gd-jp'>7時に起きます。</span>(7시에 일어나요)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>시간을 나타내는 말 바로 뒤에 に를 붙이면 돼요.<br><span class='gd-pair'><span class='gd-jp'>7時</span> → <span class='gd-jp'>7時に</span></span><span class='gd-pair'><span class='gd-jp'>3月</span> → <span class='gd-jp'>3月に</span></span><span class='gd-pair'><span class='gd-jp'>2025年</span> → <span class='gd-jp'>2025年に</span></span></div><div class='gd-h'>언제 붙이고, 언제 붙이지 않을까요</div><div class='gd-sec'>이 문법에서 정말 기억해야 할 부분이에요. 시간을 나타내는 말은 세 가지로 나뉘어요.</div><div class='gd-sec'><span class='gd-tag'>반드시 붙여요</span>숫자가 있는 시간: 몇 시, 몇 분, 몇 월, 몇 년, 며칠이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝6時に散歩します。</span>(아침 6시에 산책해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>3月に日本へ行きます。</span>(3월에 일본에 가요)</div><div class='gd-sec'>숫자는 없지만 특정한 날을 분명히 가리킬 때도 붙여요. <span class='gd-jp'>誕生日</span>, <span class='gd-jp'>クリスマス</span>, <span class='gd-jp'>夏休み</span> 같은 말이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日にケーキを食べます。</span>(생일에 케이크를 먹어요)</div><div class='gd-sec'><span class='gd-tag'>붙여도 안 붙여도 돼요</span>요일이에요. 붙이면 더 분명해지니까 초보자는 <b>일단 붙이는 게 가장 안전해요</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>金曜日に歓迎会があります。</span>(금요일에 환영회가 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日に休みます。</span>(일요일에 쉬어요)</div><div class='gd-sec'><span class='gd-tag'>붙이면 안 돼요</span>①「지금」을 기준으로 하는 시간: <span class='gd-jp'>今日</span>, <span class='gd-jp'>明日</span>, <span class='gd-jp'>昨日</span>, <span class='gd-jp'>今週</span>, <span class='gd-jp'>来年</span>, <span class='gd-jp'>今</span>.<br>판단 방법: 이런 말은 오늘 말할 때와 다음 주에 말할 때 가리키는 날이 달라져요. 「지금」을 따라 움직이는 말이라서 に를 붙이지 않아요. 한국어에서도 「내일에」 「오늘에」라고 잘 하지 않죠.<br>②「매~」를 뜻하는 시간: <span class='gd-jp'>毎日</span>, <span class='gd-jp'>毎朝</span>, <span class='gd-jp'>毎週</span>. 이런 말은 특정한 한 시점이 아니라 정해진 주기로 반복된다는 뜻이라서 に를 붙이지 않아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、映画を見ます。</span>(내일 영화를 볼 거예요)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝コーヒーを飲みます。</span>(매일 아침 커피를 마셔요)</div><div class='gd-sec'>두 종류의 시간을 함께 쓰는 경우도 흔해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝7時に起きます。</span>(매일 아침 7시에 일어나요)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日の3時に会いましょう。</span>(내일 3시에 만나요)</div><div class='gd-warn'>한 문장에 시간이 두 개 있으면 각각 규칙대로 해요. 지금을 기준으로 하는 시간(<span class='gd-jp'>明日</span>…)과 「매~」 시간(<span class='gd-jp'>毎朝</span>…)에는 붙이지 않고, 숫자가 있는 시간(<span class='gd-jp'>7時</span>, <span class='gd-jp'>3時</span>…)에는 붙여요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・に를 빼먹는 경우: 「7時起きます」라고 하면 틀려요. <span class='gd-jp'>7時に起きます</span>라고 해야 해요.<br>・반대로 너무 많이 붙이는 경우: 「明日に行きます」 「毎日に勉強します」는 둘 다 틀려요. <span class='gd-jp'>明日</span>, <span class='gd-jp'>毎日</span> 뒤에는 바로 이어서 말해요.<br>・시간을 물을 때 <span class='gd-jp'>何時</span>에는 に를 붙이고, <span class='gd-jp'>いつ</span>에는 붙이지 않아요. <span class='gd-jp'>何時に起きますか。</span>(몇 시에 일어나요?), <span class='gd-jp'>いつ日本へ行きますか。</span>(언제 일본에 가요?)<br>・「時」와 「時間」은 달라요. <span class='gd-jp'>2時に勉強します</span>는 「2시에 공부해요」이고, <span class='gd-jp'>2時間勉強します</span>는 「2시간 공부해요」예요. <b>얼마나 오래</b>인지 시간의 길이를 말할 때는 に를 붙이지 않아요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>같은 「7시」라도 뒤에 오는 조사에 따라 뜻이 달라져요.<br><b>に</b>＝바로 그 시점이에요. <span class='gd-jp'>7時に起きます。</span>(7시에 일어나요)<br><b>から</b>＝그 시간부터 시작해서 계속 이어져요. <span class='gd-jp'>7時から勉強します。</span>(7시부터 공부해요)<br><b>まで</b>＝그 시간까지 계속돼요. <span class='gd-jp'>7時まで寝ます。</span>(7시까지 자요)</div><div class='gd-warn'>구별 요령: 한국어의 「~에」는 に, 「~부터」는 から, 「~까지」는 まで로 생각하면 돼요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>に는 시간만 나타내는 게 아니라 사물이 어디에 있는지도 나타내요(n5-33 존재 위치). <span class='gd-jp'>部屋に猫がいます。</span>(방에 고양이가 있어요) 같은 に라도 앞에 시간이 오는지 장소가 오는지를 보고 판단하면 돼요.</div>","n5-22":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「と」는 한국어의 <b>「~와/과」「~(이)랑」「~하고」</b>에 해당해요. 「친구와 영화를 봐요」라고 말하고 싶으면 「친구」 뒤에 と를 붙이면 돼요: <span class='gd-jp'>友達と映画を見ます</span>. と 앞에는 <b>이 일을 나와 함께 하는 사람</b>이 와요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>아주 간단해요: <b>사람＋と＋하는 일</b>. 「함께」를 강조하고 싶다면 と 뒤에 <span class='gd-jp'>一緒に</span>(함께)를 붙여도 돼요. 뜻은 같고, 「함께」라는 느낌만 더 뚜렷해져요.<br><span class='gd-pair'><span class='gd-jp'>友達と</span> → <span class='gd-jp'>友達と一緒に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>友達と映画を見ました。</span>(친구와 영화를 봤어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>母と一緒に料理を作ります。</span>(엄마와 함께 요리를 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、犬と散歩します。</span>(매일 아침 강아지와 산책해요)</div><div class='gd-sec'>「누구와」라고 물을 때는 <span class='gd-jp'>誰と</span>를 쓰고, 대답은 「사람＋とです」라고 간단히 해도 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰と行きますか。</span>(누구와 가요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達とです。</span>(친구와요)</div><div class='gd-sec'>「나」까지 말하고 싶다면 주인공에는 は를, 함께하는 사람에는 と를 써요: <span class='gd-jp'>私は友達と京都へ行きます。</span>(저는 친구와 교토에 가요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・혼자서 할 때는 <span class='gd-jp'>一人で</span>라고 해요. 一人と가 아니에요. 사람 수나 한 무리의 사람을 말할 때도 で를 써요: <span class='gd-jp'>二人で</span>、<span class='gd-jp'>家族で</span>、<span class='gd-jp'>みんなで</span>.<br>・一緒に는 넣어도 되고 빼도 되는 조연이에요. と만 있어도 이미 「누구와 함께」라는 뜻이에요. 반대로 一緒に만 말하고 상대를 말하지 않는 건 상대가 누군지 모두 알기 때문이에요: <span class='gd-jp'>一緒に帰りましょう。</span>(같이 돌아가요)<br>・<span class='gd-jp'>結婚する</span>처럼 반드시 두 사람이 있어야 하는 일에도 と를 쓰고, 보통 一緒に는 붙이지 않아요: <span class='gd-jp'>田中さんと結婚しました。</span>(다나카 씨와 결혼했어요)</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'>と에는 다른 용법도 있어요. 두 가지를 이어 주는, 한국어의 「A와 B」(나열)예요. 두 문장을 비교해 보세요.<br><span class='gd-jp'>母とケーキを食べました。</span>(엄마와 케이크를 먹었어요) → 엄마는 <b>함께 먹은 사람</b><br><span class='gd-jp'>パンとケーキを食べました。</span>(빵과 케이크를 먹었어요) → 빵과 케이크 모두 <b>먹은 음식</b></div><div class='gd-warn'>판단 요령: と 앞이 「함께 행동하는 사람」이면 여기서 배운 「누구와 함께」이고, と 앞뒤가 나란히 놓인 두 사물이면 「A와 B」예요.</div><div class='gd-h'>다 배운 다음에 이어서 배워요</div><div class='gd-sec'>「〜ませんか」와 함께 쓰면 상대에게 권유할 수 있어요: <span class='gd-jp'>週末、私と映画を見ませんか。</span>(주말에 저와 영화 보러 갈래요?)</div>","n5-23":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「を」는 명사 뒤에 붙는 작은 표지로, <b>「이것이 동작의 대상이에요」</b>라는 뜻이에요. 한국어의 「~을/를」과 비슷해요. 한국어처럼 일본어도 동사가 문장 맨 끝에 오기 때문에 「を」로 <b>무엇을 먹는지, 무엇을 보는지</b>를 표시해 줘요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>명사＋を＋동사. 일본어는 「대상을 먼저 말하고 동작은 마지막」 순서예요. 한국어와 어순이 같아서 편해요.<br><span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンを食べます</span></span>(빵을 먹어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲みます。</span>(물을 마셔요)</div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見ます。</span>(영화를 봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日日本語を勉強します。</span>(매일 일본어를 공부해요)</div><div class='gd-h'>언제 쓸까</div><div class='gd-sec'><span class='gd-tag'>동작의 대상</span>가장 중요하고 가장 많이 쓰는 용법이에요. 무엇을 먹고, 마시고, 사고, 하는지를 나타내요. 처음에는 이것부터 확실히 익히세요.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニで傘を買いました。</span>(편의점에서 우산을 샀어요)</div><div class='gd-sec'><span class='gd-tag'>지나가는 장소</span>「걷다, 산책하다, 건너다(다리, 길)」 같은 이동 동사와 함께 쓰여, <b>그 장소를 지나가거나 가로지른다</b>는 뜻을 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園を散歩します。</span>(공원을 산책해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>橋を渡ります。</span>(다리를 건너요)</div><div class='gd-sec'><span class='gd-tag'>떠나는 장소</span>「나가다, 내리다」 같은 동사와 함께 쓰여, <b>그곳에서 떠난다</b>는 뜻을 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に家を出ます。</span>(8시에 집을 나가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>(다음 역에서 전철을 내려요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・「を」는 <b>o</b>로 읽어요. 「お」와 똑같이 읽고, wo라고 읽지 않아요. 다만 컴퓨터나 휴대폰으로 입력할 때는 <b>wo</b>라고 쳐야 나와요.<br>・발음이 같아도 쓸 때는 반드시 「を」로 써야 하고, 「お」로 쓰면 안 돼요.<br>・「좋아하다, 알다, 원하다」에는 を를 쓰지 않아요. 교과서의 표준 표현은 <span class='gd-jp'>猫が好きです</span>、<span class='gd-jp'>英語がわかります</span>예요. 한국어는 「고양이를 좋아해요」처럼 「를」을 쓰지만, 일본어에서는 猫を好きです라고 하면 안 돼요.<br>・한국어는 「친구를 만나요」「전철을 타요」처럼 「를」을 쓰지만, 일본어에서는 に를 써야 해요: <span class='gd-jp'>友達に会います</span>、<span class='gd-jp'>電車に乗ります</span>. 한편 「내리다」는 <span class='gd-jp'>電車を降ります</span>예요. 탈 때는 に, 내릴 때는 を로 나눠서 기억하세요.<br>・<b>한 동사에 を를 두 번 쓰지 마세요</b>: <span class='gd-jp'>日本語を勉強をします</span>는 부자연스러워요(勉強します에는 を가 하나만 올 수 있어요). <span class='gd-jp'>日本語を勉強します</span> 또는 <span class='gd-jp'>日本語の勉強をします</span>라고 하세요. 서로 다른 동사에 を가 하나씩 붙는 것은 괜찮아요. 예: <span class='gd-jp'>本を読んで、ご飯を食べます。</span>(책을 읽고 밥을 먹어요)<br>・친구끼리 대화할 때는 を를 자주 생략해요: <span class='gd-jp'>ご飯、食べた？</span>(밥 먹었어?) 이건 구어체예요. 직접 문장을 쓸 때는 먼저 を를 제대로 넣으세요.</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'><b>を vs が</b>: 같은 일본어라도 동작에는 を, 감정이나 능력에는 が를 써요.<br><span class='gd-jp'>日本語を勉強します。</span>(일본어를 공부해요: 동작)<br><span class='gd-jp'>日本語が好きです。</span>(일본어를 좋아해요: 감정)<br><span class='gd-jp'>日本語がわかります。</span>(일본어를 알아요: 능력)</div><div class='gd-sec'><b>を vs で</b>: 같은 다리라도 「다리를 건너다」는 を, 「다리 위에서 다른 일을 하다」는 で를 써요.<br><span class='gd-jp'>橋を渡ります。</span>(다리를 건너요: 다리 위를 걸어서 지나가요)<br><span class='gd-jp'>橋で写真を撮ります。</span>(다리에서 사진을 찍어요: 다리는 일을 하는 장소일 뿐이고, 찍는 대상인 「写真」에 を를 써요)</div><div class='gd-warn'>판단 요령: 「동작이 이 대상에 직접 가해지는가?」를 스스로 물어보세요. 그렇다면 を, 「좋아하다, 알다, 원하다」라면 が, 「어디에서 하는지」를 말할 뿐이라면 で를 써요.</div><div class='gd-h'>다 배운 다음에 이어서 배워요</div><div class='gd-sec'>동사 중에는 짝을 이루어, 하나는 を를 쓰고 하나는 が를 쓰는 것이 있어요: <span class='gd-jp'>ドアを開けます</span>(문을 열어요), <span class='gd-jp'>ドアが開きます</span>(문이 열려요). 이것이 「자동사·타동사」예요. を를 익힌 뒤에 이어서 보면 술술 이해될 거예요.</div>","n5-13":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>일본어는 같은 말도 두 가지로 표현해요. <b>정중체(丁寧体)</b>는 「です・ます」가 들어간 <b>정중한 버전</b>이고, <b>보통체(普通体)</b>는 です・ます를 뺀 <b>친구 버전</b>이에요. 뜻은 완전히 같고, 말투만 달라요. 상사에게 메시지를 보낼 때는 ‘네, 내일 가겠습니다’라고 쓰고, 친구에게는 그냥 ‘응, 내일 가’라고 하는 것과 비슷해요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>정중체</span>선생님, 상사, 점원, 손님, 처음 만난 사람, 그리고 나보다 나이가 많고 친하지 않은 사람에게 써요. 어떤 말투를 써야 할지 모르겠을 때는 정중체를 쓰면 실례가 될 일이 없어요.</div><div class='gd-sec'><span class='gd-tag'>보통체</span>가족, 친한 친구, 같은 반 친구, 나보다 어린 사람에게 써요. 일기를 쓰거나 혼잣말을 하거나 메모를 할 때도 보통체를 써요. 예의를 차릴 상대가 없으니까요.</div><div class='gd-h'>같은 말, 두 가지 표현</div><div class='gd-sec'>‘내일 갈 거예요?’라고 묻고 싶을 때예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行きますか。</span>（내일 가세요?: 선생님께）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、行きます。</span>（네, 갈 거예요）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行く？</span>（내일 갈 거야?: 친구에게）</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、行く。</span>（응, 갈 거야）</div><div class='gd-sec'>친구 버전의 의문문을 잘 보세요. <b>문장 끝의 か가 사라지고, 대신 끝을 올려서 말해요</b>. 대답의 「はい」도 「うん」으로 바뀌어요.</div><div class='gd-h'>바꾸는 법: 정중한 버전에서 친구 버전으로</div><div class='gd-sec'><b>명사, な형용사</b>: です를 だ로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かだ</span></span><br>부정과 과거도 함께 바뀌어요.<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><span class='gd-pair'><span class='gd-jp'>学生でした</span> → <span class='gd-jp'>学生だった</span></span></div><div class='gd-sec'><b>い형용사</b>: です만 빼면 되고, <b>だ는 붙이지 않아요</b>.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高い</span></span><span class='gd-pair'><span class='gd-jp'>高くないです</span> → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span></div><div class='gd-sec'><b>동사</b>: ます형을 사전형으로 되돌려요. 사전에 실려 있는 형태예요.<br>1그룹(5단 동사): ます 앞의 음을 같은 행의 「う」단 음으로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → き를 く로 바꿔서 → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲む</span></span><br>2그룹(1단 동사): ます를 빼고 る를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br>3그룹(する・来る): 그냥 외우면 돼요.<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span><br>그 밖에 자주 쓰는 형태예요: <span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>読んでいます</span> → <span class='gd-jp'>読んでいる</span></span><br>부정형과 과거형의 자세한 활용은 ‘사전형・ない형’과 ‘た형’ 레슨에서 차근차근 알려 줄게요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・い형용사에는 だ를 붙이지 않아요. <span class='gd-jp'>高い</span>라고만 하면 되고, 「高いだ」는 틀린 말이에요.<br>・친구와 이야기할 때 「<span class='gd-jp'>雨だ。</span>」라고만 하면 딱딱하게 들려요. 혼잣말을 하거나 무언가를 선언하는 느낌이거든요. 평소에는 よ나 ね를 붙이는 경우가 많아요. <span class='gd-jp'>明日、雨だよ。</span>（내일 비 와）<br>・명사, な형용사의 보통체 의문문에서는 だ를 빼요. <span class='gd-jp'>学生？</span>（학생이야?）처럼 말하고, 「学生だ？」라고는 하지 않아요.<br>・보통체가 ‘무례한 말투’인 건 아니에요. ‘아주 친한 사이’에서 쓰는 말투예요. 선생님께 보통체를 쓰면 실례지만, 반대로 친한 친구에게 계속 です・ます로 말하면 상대는 거리감을 느끼거나 화가 났나 하고 생각할 수 있어요.<br>・한 사람에게 말할 때는 초보자일수록 한 가지 말투로 통일하세요. 한 문장은 ます, 다음 문장은 보통체로 섞으면 듣기에 아주 어수선해요.<br>・<span class='gd-jp'>読んでいる</span>는 구어에서 <span class='gd-jp'>読んでる</span>로 줄여 말하는 일이 많아요. 들었을 때 같은 뜻이라는 걸 알아 두세요.</div><div class='gd-h'>다 배우고 나서 이어서 볼 내용</div><div class='gd-sec'>보통체는 대화에서만 쓰는 게 아니에요. 많은 문법은 앞에 반드시 보통체가 와야 하고, 문장 전체가 정중해도 마찬가지예요. <span class='gd-jp'>明日は雨だと思います。</span>（내일은 비가 올 것 같아요）<br>다음 단계로 ‘보통형 총정리’를 보세요. 품사별 현재, 과거, 긍정, 부정을 한 번에 정리할 수 있어요.</div>","n5-14":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>‘~하지 않아요’의 정중한 표현은 두 가지가 있어요. <span class='gd-jp'>食べません</span>과 <span class='gd-jp'>食べないです</span>이고, 둘 다 ‘안 먹어요’라는 뜻이에요. 차이는 정장과 캐주얼 재킷의 차이쯤이에요. <b>ません이 더 격식 있고</b>, <b>ないです는 더 편해요</b>. 둘 다 정중해서 선생님이나 점원에게 말해도 실례가 되지 않아요.</div><div class='gd-h'>바꾸는 법: 먼저 동사가 어느 그룹인지 보세요</div><div class='gd-sec'><span class='gd-jp'>ません</span> 버전은 간단해요. ます를 ません으로 바꾸기만 하면 돼요. <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みません</span></span><br><span class='gd-jp'>ないです</span> 버전은 ない형(동사의 ‘~하지 않아’ 반말형) 뒤에 <span class='gd-jp'>です</span>를 붙여요.</div><div class='gd-sec'><b>1그룹(5단 동사)</b>: 마지막 음을 같은 행의 「あ」단 음으로 바꾸고 ない를 붙인 다음, です를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む를 ま로 바꿔서 → <span class='gd-jp'>飲まないです</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないです</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らないです</span></span><br>마지막이 「う」인 동사는 「わ」로 바꿔요: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わないです</span></span></div><div class='gd-sec'><b>2그룹(1단 동사)</b>: 「る」를 빼고 ないです를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないです</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ないです</span></span></div><div class='gd-sec'><b>3그룹(딱 두 개뿐이라 그냥 외워요)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないです</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないです</span>（こないです）</span></div><div class='gd-h'>형용사, 명사도 두 가지가 있어요</div><div class='gd-sec'><b>い형용사</b>: 마지막 「い」를 「く」로 바꾸고, ないです나 ありません을 붙여요.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くないです</span></span>＝<span class='gd-jp'>寒くありません</span><br><b>な형용사, 명사</b>: 그대로 じゃないです나 じゃありません을 붙여요.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かじゃないです</span></span>＝<span class='gd-jp'>静かじゃありません</span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃないです</span></span>＝<span class='gd-jp'>学生じゃありません</span><br>더 격식 있게 말하고 싶다면 じゃ를 では로 바꾸세요: <span class='gd-jp'>学生ではありません</span>.</div><div class='gd-sec'>과거의 ‘~하지 않았어요’도 두 가지예요. <span class='gd-jp'>食べませんでした</span>＝<span class='gd-jp'>食べなかったです</span>, <span class='gd-jp'>寒くありませんでした</span>＝<span class='gd-jp'>寒くなかったです</span>.</div><div class='gd-h'>언제 어느 쪽을 쓸까요</div><div class='gd-sec'><span class='gd-tag'>격식 있는 자리</span>이메일, 직장, 면접, 윗사람에게 말할 때는 ません이 더 안전해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は会社に行きません。</span>（저는 내일 회사에 안 가요）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は学生ではありません。</span>（저는 학생이 아니에요）</div><div class='gd-sec'><span class='gd-tag'>일상 대화</span>점원, 이웃, 별로 친하지 않은 같은 반 친구와 이야기할 때는 ないです를 자주 들을 수 있어요. 형용사의 <span class='gd-jp'>くないです</span>, <span class='gd-jp'>じゃないです</span>는 평소 말할 때 ありません보다 더 많이 쓰기도 해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>肉はあまり食べないです。</span>（저는 고기를 별로 안 먹어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、高くないですよ。</span>（이 가게, 안 비싸요）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はそんなに寒くないですね。</span>（오늘은 그렇게 춥지 않네요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・두 가지를 섞어 쓰면 안 돼요. <span class='gd-jp'>食べないません</span>도, <span class='gd-jp'>食べませんです</span>도 없는 말이에요.<br>・<span class='gd-jp'>ある</span>의 ‘없다’는 특별해요. 곧바로 <span class='gd-jp'>ない</span>가 되고, あらない라는 말은 없어요. <span class='gd-jp'>時間がありません</span>＝<span class='gd-jp'>時間がないです</span>（시간이 없어요）.<br>・<span class='gd-jp'>いい</span>는 <span class='gd-jp'>よくないです</span>가 되고, いくないです가 아니에요.<br>・<span class='gd-jp'>買う</span>는 <span class='gd-jp'>買わない</span>이고, 買あない가 아니에요.<br>・<span class='gd-jp'>来ない</span>는 <b>こない</b>라고 읽고, きない가 아니에요.<br>・모든 곳에서 서로 바꿔 쓸 수 있는 건 아니에요. <span class='gd-jp'>すみません</span>은 정해진 사과 표현이라 すまないです라고는 하지 않아요. 상대에게 권유하는 <span class='gd-jp'>一緒に行きませんか</span>（같이 갈래요?）도 ません으로 말하는 게 가장 자연스럽고 정중해요.</div><div class='gd-h'>비슷하게 생긴 것과 구별하기</div><div class='gd-sec'>ないです를 배우고 나면 말하다가 <span class='gd-jp'>です</span>를 빠뜨리는 사람이 많아요. 똑같이 ‘오늘은 안 가요’라고 말할 때를 비교해 볼게요.<br>선생님께: <span class='gd-jp'>今日は行きません。</span>／<span class='gd-jp'>今日は行かないです。</span>（둘 다 괜찮아요）<br>친구에게: <span class='gd-jp'>今日は行かない。</span>（친구 버전이라, 선생님께 쓰면 너무 편한 말투예요）</div><div class='gd-warn'>구별하는 요령: 문장 끝에 <span class='gd-jp'>ます</span>(ません)나 <span class='gd-jp'>です</span>가 있으면 정중한 버전이고, 둘 다 없으면 친구 버전이에요.</div><div class='gd-h'>다 배우고 나서 이어서 볼 내용</div><div class='gd-sec'>언제 です를 빼고 <span class='gd-jp'>行かない</span>처럼 바로 말해도 되는지 궁금하다면 ‘정중체와 보통체’, ‘사전형・ない형’ 레슨을 이어서 보세요.</div>","n5-28":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>「や」는 한국어의 <b>「A나 B 같은 것」</b>과 비슷해요. 많은 것 중에서 대표로 몇 개만 골라 말하면서, 상대방에게 <b>그 밖에도 더 있고 전부를 다 말한 건 아니라는 것</b>을 알려 줘요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>명사＋<b>や</b>＋명사로 쓰고, 마지막에 「<b>など</b>」(등등)를 자주 붙여요. 뒤에 와야 할 조사(を、が、に…)는 그대로 맨 끝에 붙이면 돼요.<br><span class='gd-pair'><span class='gd-jp'>牛乳</span>＋<span class='gd-jp'>卵</span> → <span class='gd-jp'>牛乳や卵</span></span><br><span class='gd-pair'><span class='gd-jp'>牛乳や卵</span> → <span class='gd-jp'>牛乳や卵など</span></span>(など를 붙이면 '그 밖에도 있다'는 느낌이 더 분명해져요)</div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>(냉장고에 우유나 달걀 같은 게 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除や洗濯をします。</span>(주말에는 청소나 빨래 같은 걸 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で寿司やラーメンなどを食べました。</span>(일본에서 초밥이나 라멘 등을 먹었어요)</div><div class='gd-sec'>세 개를 들어도 괜찮아요. 사이사이마다 や를 넣으세요.</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上にペンやノートや辞書などがあります。</span>(책상 위에 펜, 공책, 사전 등이 있어요)</div><div class='gd-h'>비슷하게 생긴 말과 구분하기</div><div class='gd-sec'>「と」도 명사를 이어 주지만 뜻은 꽤 달라요. 같은 가방 안에 든 물건을 말한다고 해 볼게요.<br><b>と</b>＝<b>이게 전부</b>: <span class='gd-jp'>かばんに財布と鍵があります。</span>(가방에 지갑과 열쇠가 있어요. 딱 이 두 가지예요)<br><b>や</b>＝<b>예를 들어 말함, 그 밖에도 있음</b>: <span class='gd-jp'>かばんに財布や鍵があります。</span>(가방에 지갑이나 열쇠 같은 게 있어요. 다른 물건도 있어요)</div><div class='gd-warn'>구분 요령: '딱 이것뿐'이라고 말할 수 있으면 と를, 예를 몇 개만 든 거고 마음속에 '…같은 것'이 남아 있으면 や를 쓰세요.</div><div class='gd-h'>자주 틀리는 부분</div><div class='gd-warn'>・や는 <b>명사만 연결할 수 있어요</b>. 동작을 예로 들 때는 「食べるや飲む」라고 할 수 없고, 「〜たり〜たりします」를 써야 해요: <span class='gd-jp'>食べたり飲んだりします</span>(먹기도 하고 마시기도 해요).<br>・마지막 명사 뒤에는 <b>や를 또 붙이지 않아요</b>. 「ペンやノートや」로 끝내지 않고, '등등'이라는 뜻을 더하고 싶으면 など를 붙여요: <span class='gd-jp'>ペンやノートなど</span>.<br>・한국어의 '와/과, 랑'에는 '누구와 함께'라는 뜻도 있지만 や에는 그런 뜻이 없어요. '친구랑 가요'는 <span class='gd-jp'>友達と行きます</span>이고, 友達や行きます라고 할 수 없어요.<br>・물건이 아주 많을 때만 や를 쓰는 게 아니에요. 두 개만 들어도 전혀 문제없어요. 핵심은 '전부 다 말한 건 아니다'라는 느낌이에요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>동작을 예로 드는 표현은 「〜たり〜たりします」예요: <span class='gd-jp'>休みの日は映画を見たり、買い物をしたりします。</span>(쉬는 날에는 영화를 보기도 하고 쇼핑을 하기도 해요)</div>","n5-29":"<div class='gd-h'>한 문장으로 이해하기</div><div class='gd-sec'>이 「で」는 한국어의 <b>'~(으)로'</b>예요. 젓가락으로 먹고, 일본어로 말하고, 전화로 연락할 때처럼, 일본어에서는 그 대상 뒤에 「で」를 붙여요: <span class='gd-jp'>はしで食べます</span>(젓가락으로 먹어요).</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>도구</span>손에 들고 무언가를 할 때 쓰는 물건이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>はしで食べます。</span>(젓가락으로 먹어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ボールペンで書いてください。</span>(볼펜으로 써 주세요)</div><div class='gd-sec'><span class='gd-tag'>언어</span>어떤 언어로 말하거나 쓰는지를 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話しましょう。</span>(일본어로 이야기해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>これは英語で何と言いますか。</span>(이건 영어로 뭐라고 해요?)</div><div class='gd-sec'><span class='gd-tag'>방법</span>어떤 방식으로 하는지를 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>母と電話で話しました。</span>(엄마와 전화로 이야기했어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ネットでチケットを買いました。</span>(인터넷으로 티켓을 샀어요)</div><div class='gd-sec'><span class='gd-tag'>재료</span>무엇으로 만들었는지를 나타내요. 완성된 뒤에도 원래 재료를 알아볼 수 있을 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>紙で花を作りました。</span>(종이로 꽃을 만들었어요)</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>아주 간단해요. <b>명사 뒤에 바로 「で」를 붙이면</b> 되고, 형태는 바뀌지 않아요.<br><span class='gd-pair'><span class='gd-jp'>スプーン</span> → <span class='gd-jp'>スプーンで</span></span><span class='gd-pair'><span class='gd-jp'>英語</span> → <span class='gd-jp'>英語で</span></span><br>하려는 일은 평소처럼 「を」로 동사 앞에 이어 줘요: <span class='gd-jp'>スプーンでスープを飲みます。</span>(숟가락으로 국을 마셔요)</div><div class='gd-h'>자주 틀리는 부분</div><div class='gd-warn'>・한국어의 '~(으)로'처럼 일본어의 「で」도 명사 <b>뒤에</b> 붙어요. 어순이 같으니 '젓가락으로'는 「はしで」로 그대로 옮기면 돼요.<br>・초보자는 도구를 목적어로 착각해서 「はしを食べます」라고 하기 쉬운데, 이러면 '젓가락을 먹어요'라는 뜻이 돼요. 도구 뒤에는 <b>で</b>를 써야 해요.<br>・'무엇으로'라고 물을 때는 <span class='gd-jp'>何で</span>라고 하고, <b>なにで</b>라고 읽어요: <span class='gd-jp'>何で書きますか。</span>(뭐로 써요?) なんで라고 읽으면 회화에서 '왜'라는 뜻으로 들리기 쉬워요.</div><div class='gd-h'>비슷하게 생긴 말과 구분하기</div><div class='gd-sec'><b>で(장소)</b>: 어디에서 하는지를 나타내요. <span class='gd-jp'>教室で書きます。</span>(교실에서 써요)<br><b>で(도구)</b>: 무엇으로 하는지를 나타내요. <span class='gd-jp'>ペンで書きます。</span>(펜으로 써요)<br>두 가지를 한 문장에 함께 쓸 수도 있어요: <span class='gd-jp'>教室でペンで書きます。</span>(교실에서 펜으로 써요)<br>참고로 <span class='gd-jp'>バスで行きます</span>(버스로 가요)의 「で」도 사실은 '어떤 방법으로'라는 뜻이라서, 이 카드와 같은 개념이에요.</div><div class='gd-warn'>구분 요령: 앞에 '장소'가 오면 '~에서', 앞에 '사용하는 물건, 언어, 방법'이 오면 '~(으)로'예요.</div><div class='gd-sec'><b>日本語を話します</b>: 일본어를 할 줄 알아요. 일본어는 내가 할 수 있는 대상이에요.<br><b>日本語で話します</b>: 일본어로 말해요. 일본어는 소통 수단이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話します。</span>(저는 일본어를 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>店員と日本語で話しました。</span>(점원과 일본어로 이야기했어요)</div><div class='gd-warn'>구분 요령: '나는 무슨 언어를 할 줄 안다'고 말할 때는 を를, '이번에는 무슨 언어로 소통한다'고 말할 때는 で를 쓰세요.</div>","n5-26":"<div class='gd-h'>한 줄로 먼저 이해해요</div><div class='gd-sec'>「まで」는 한국어의 <b>「~까지」</b>예요. <b>끝나는 지점</b>이 어디인지 알려 줘요. 시간의 끝(5시까지)일 수도 있고, 장소의 끝(역까지)일 수도 있어요. 「から」(~부터)와 짝을 이뤄 자주 쓰여요. <span class='gd-jp'>から</span>는 시작점이고, <span class='gd-jp'>まで</span>는 끝점이에요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>시간</span>어떤 일을 계속하다가 그 시각이 되면 멈춰요.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>(5시까지 기다려요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は11時まで寝ました。</span>(어제는 11시까지 잤어요)</div><div class='gd-sec'><span class='gd-tag'>장소</span>이동해서 어디까지 가는지를 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩きます。</span>(역까지 걸어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>空港までバスで行きます。</span>(공항까지 버스로 가요)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>아주 간단해요. 명사 뒤에 바로 まで를 붙이면 되고, 형태는 바뀌지 않아요.<br><span class='gd-pair'><span class='gd-jp'>6時</span> → <span class='gd-jp'>6時まで</span></span><span class='gd-pair'><span class='gd-jp'>金曜日</span> → <span class='gd-jp'>金曜日まで</span></span><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京まで</span></span></div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>から～まで</span>어디부터 어디까지, 몇 시부터 몇 시까지처럼 범위를 한 번에 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>9時から5時まで働きます。</span>(9시부터 5시까지 일해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>東京から大阪まで新幹線で行きます。</span>(도쿄에서 오사카까지 신칸센으로 가요)</div><div class='gd-sec'><span class='gd-tag'>～までです</span>뒤에 바로 です를 붙여요. 영업시간이나 수업 시간을 말할 때 정말 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は夜10時までです。</span>(이 가게는 밤 10시까지예요)</div><div class='gd-sec'><span class='gd-tag'>いつまで・どこまで</span>「언제까지」「어디까지」를 물어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>いつまで日本にいますか。</span>(언제까지 일본에 있어요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・まで는 동작이 그 시점까지 <b>계속 이어진다</b>는 뜻이에요. 한국어 「까지」는 '5시까지 와 주세요'처럼 기한을 말할 때도 쓰니까 조심하세요. 이 말을 그대로 「5時まで来てください」라고 하면 어색해요. 기한이라면 뒤에서 배울 までに를 써야 해요. 단순히 '5시에 와 주세요'라고 하고 싶다면 <span class='gd-jp'>5時に来てください</span>라고 하면 돼요.<br>・「金曜日まで休みです」는 보통 금요일<b>까지 포함</b>해요. 금요일도 쉬는 날이에요.<br>・まで는 끝점만 나타낼 뿐 '간다'는 뜻을 스스로 갖고 있지 않아요. 뒤에 동사가 꼭 필요해요. <span class='gd-jp'>駅まで歩きます</span>, <span class='gd-jp'>駅まで行きます</span>처럼요.</div><div class='gd-h'>비슷하게 생긴 말과 구별해요</div><div class='gd-sec'><b>に(시점)</b>＝그 시점에 <b>한 번 일어나요</b>: <span class='gd-jp'>11時に寝ました。</span>(11시에 잤어요)<br><b>まで</b>＝그 시간까지 <b>계속 해요</b>: <span class='gd-jp'>11時まで寝ました。</span>(11시까지 쭉 잤어요)<br>한 글자 차이인데, 하나는 11시에 잠자리에 든 거고 다른 하나는 11시에야 일어난 거예요.</div><div class='gd-sec'><b>までに</b>＝그 시간 <b>전에 끝내요</b>(기한): <span class='gd-jp'>5時までに帰ります。</span>(5시까지는 돌아올게요)<br><b>まで</b>＝그 시간까지 계속 이어져요: <span class='gd-jp'>5時まで待ちます。</span>(5시까지 계속 기다릴게요)</div><div class='gd-warn'>판단 요령: '몇 시까지 계속'이면 まで, '몇 시 전에 끝내야 해요'면 までに, '몇 시에 그 일을 해요'면 に를 써요.</div><div class='gd-h'>다 익혔다면 다음으로 배워 봐요</div><div class='gd-sec'>まで 뒤에 に를 붙이면 <span class='gd-jp'>までに</span>가 되고, 기한을 말할 때 써요: <span class='gd-jp'>金曜日までに出してください。</span>(금요일까지 제출해 주세요)</div>","n5-27":"<div class='gd-h'>한 줄로 먼저 이해해요</div><div class='gd-sec'>이 「と」는 한국어의 <b>「와/과」「하고」</b>예요. 물건을 하나씩 늘어놓아요. 그리고 <b>내가 말한 게 전부고, 다른 건 없다</b>는 뜻도 있어요. 친구에게 '빵과 우유를 샀어요'라고 하면 딱 그 두 가지만 산 거잖아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンと牛乳を買いました。</span>(빵과 우유를 샀어요)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>명사＋と＋명사, <b>양쪽 모두 명사</b>여야 해요. 다 늘어놓은 뒤, 맨 끝에 문장에서 필요한 조사(を、が、は…)를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>鍵</span>＋<span class='gd-jp'>財布</span> → <span class='gd-jp'>鍵と財布を持ってきました</span></span>(열쇠와 지갑을 가져왔어요)<br>세 개 이상이면 각각의 사이에 と를 넣어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日と水曜日と金曜日に授業があります。</span>(월요일, 수요일, 금요일에 수업이 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>父と母は台北に住んでいます。</span>(부모님은 타이베이에 살아요)</div><div class='gd-sec'>주문할 때도 정말 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーとケーキをお願いします。</span>(커피와 케이크 부탁해요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>조사는 맨 마지막 명사 뒤에만</b> 붙여요. <span class='gd-jp'>鍵と財布を持ってきました</span>가 맞고, 「鍵を財布を持ってきました」나 「鍵をと財布を持ってきました」처럼 말하면 안 돼요.<br>・と는 <b>명사만 이을 수 있어요</b>. 한국어 '와/과'도 명사를 잇는 말이라 '싸고 맛있다', '밥을 먹고 TV를 보다'처럼 형용사나 동작은 '~고'로 이어야 하죠. 일본어도 마찬가지로 と로는 형용사나 동작을 잇지 못하고, 나중에 배울 て형을 써요.<br>・と는 '딱 이것들뿐'이라는 뜻이에요. 말하지 않은 다른 것이 더 있다면 や를 써야 해요.</div><div class='gd-h'>비슷하게 생긴 말과 구별해요</div><div class='gd-sec'><span class='gd-tag'>と vs や</span>가방에 뭘 가져왔는지 말할 때를 비교해 볼게요.<br><span class='gd-jp'>鍵と財布を持ってきました。</span>(열쇠와 지갑을 가져왔어요: 딱 이 두 가지)<br><span class='gd-jp'>鍵や財布を持ってきました。</span>(열쇠나 지갑 같은 걸 가져왔어요: 다른 것도 있어요)</div><div class='gd-sec'><span class='gd-tag'>나열 vs 함께</span>と에는 또 다른 쓰임이 있어요. 「누구와 함께」 어떤 일을 한다는 뜻이에요.<br><b>나열의 と</b>: A와 B를 한 묶음으로 만들고, 뒤에 は、が、を 같은 조사가 붙어서 함께 문장의 한 성분이 돼요.<br><span class='gd-jp'>友達と私は映画を見ました。</span>(친구와 나는 영화를 봤어요: 「友達と私」가 한 묶음이고 뒤에 は가 붙어요)<br><b>함께의 と</b>: 「사람＋と」로, 누구와 뒤의 동작을 하는지 설명해요. 뒤에 명사가 나와도 그 명사는 별개의 성분이라서 と 앞의 사람과 묶이지 않아요.<br><span class='gd-jp'>友達と映画を見ました。</span>(친구와 영화를 봤어요: 「友達と」는 누구와 봤는지를 말하고, 「映画を」는 본 대상이에요. '친구와 영화'가 아니에요)<br>'함께'를 강조하고 싶을 때는 <span class='gd-jp'>友達と一緒に映画を見ました</span>처럼 말하는 경우가 많아요.</div><div class='gd-warn'>판단 요령: と 앞의 명사를 따로 문장에 넣어 보세요. <span class='gd-jp'>鍵を持ってきました</span>, <span class='gd-jp'>財布を持ってきました</span>가 둘 다 자연스러우면 'A와 B'예요. 「友達と映画を見ました」를 「友達を見ました」로 바꾸면 뜻이 이상해지죠? 그럴 때의 と는 '누구와 함께'예요.</div>","n5-32":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>한국어에서는 「강아지를 좋아해요」 「한국어를 알아요」처럼 대부분 을/를을 쓰니까, 일본어에서도 <span class='gd-jp'>を</span>를 쓰고 싶어져요. 하지만 일본어에서는 <b>좋아하다, 싫어하다, 잘하다, 못하다, 알다(이해하다), 할 수 있다, 갖고 싶다</b> 앞의 대상에는 <b>が</b>를 써요. 고정된 짝으로 외워 두면 돼요.</div><div class='gd-h'>어떤 말 앞에 が를 쓸까요</div><div class='gd-sec'><span class='gd-tag'>좋아하다・싫어하다</span><span class='gd-jp'>好き</span>(좋아해요), <span class='gd-jp'>嫌い</span>(싫어해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>チョコレートが好きです。</span>(초콜릿을 좋아해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は野菜が嫌いです。</span>(저는 채소를 싫어해요)</div><div class='gd-sec'><span class='gd-tag'>잘하다・못하다</span><span class='gd-jp'>上手</span>(잘해요, 능숙해요), <span class='gd-jp'>下手</span>(못해요, 서툴러요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは歌が上手です。</span>(다나카 씨는 노래를 잘해요)</div><div class='gd-sec'><span class='gd-tag'>알다・할 수 있다</span><span class='gd-jp'>わかります</span>(알아요, 이해해요), <span class='gd-jp'>できます</span>(할 수 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語がわかります。</span>(한국어를 알아요)</div><div class='gd-ex-line'>・<span class='gd-jp'>テニスができます。</span>(테니스를 칠 수 있어요)</div><div class='gd-sec'><span class='gd-tag'>갖고 싶다</span><span class='gd-jp'>ほしい</span>(갖고 싶어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいかばんがほしいです。</span>(새 가방을 갖고 싶어요)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>대상(명사)＋が＋위의 말들이에요.<br>「누가」 좋아하는지 말하려면 맨 앞에 「사람＋は」를 놓아요. <span class='gd-jp'>私は犬が好きです。</span>(저는 강아지를 좋아해요)<br>이 문장에서 <span class='gd-jp'>は</span>는 「지금 이야기하는 건 나」라는 뜻이고, <span class='gd-jp'>が</span>는 「좋아하는 대상은 강아지」라는 뜻이에요. 둘이 각자 역할이 달라요.<br>상대가 무엇을 좋아하는지 묻고 싶으면 대상을 <span class='gd-jp'>何</span>로 바꾸면 돼요. <span class='gd-jp'>何が好きですか。</span>(무엇을 좋아해요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・한국어 감각대로 を를 쓰면 안 돼요. <span class='gd-jp'>韓国語がわかります</span>라고 해야 하고, 韓国語をわかります는 틀려요. 「좋아하다」도 마찬가지예요. 먼저 <span class='gd-jp'>犬が好きです</span>를 통째로 외워 두세요.<br>・<span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>上手</span>, <span class='gd-jp'>下手</span>는 동사가 아니라서 뒤에 <span class='gd-jp'>です</span>를 붙이고, ます는 붙일 수 없어요.<br>・「좋아하지 않아요」라고 할 때는 일본 사람들이 が를 は로 바꿔 말하는 일이 많아요. <span class='gd-jp'>魚は好きじゃありません。</span>(생선은 좋아하지 않아요) 「다른 건 괜찮은데 이건 별로」라는 느낌이 나서 아주 자연스러워요.<br>・<span class='gd-jp'>上手</span>는 다른 사람을 칭찬할 때 써요. 자기 입으로 「저는 잘해요」라고 하면 자랑처럼 들려서, 자기 이야기를 할 때는 보통 이렇게 쓰지 않아요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>가장 헷갈리기 쉬운 건 <b>を</b>(목적어)예요. 같은 대상이 다른 말 앞에 올 때를 비교해 보세요.<br><span class='gd-jp'>日本語を勉強します。</span>(일본어를 공부해요): 「공부」는 내가 하는 동작이라서 を를 써요.<br><span class='gd-jp'>日本語がわかります。</span>(일본어를 알아요): 「알다」는 내가 가진 능력이라서 が를 써요.<br><span class='gd-jp'>料理を作ります。</span>(요리를 만들어요): 동작이라서 を를 써요.<br><span class='gd-jp'>料理が上手です。</span>(요리를 잘해요): 실력이라서 が를 써요.</div><div class='gd-warn'>판별 요령: 「하는」 동작(먹다, 읽다, 만들다, 사다)이면 を를 쓰고, 마음의 느낌이나 몸에 지닌 능력(좋아하다, 싫어하다, 잘하다, 알다, 할 수 있다, 갖고 싶다)이면 が를 써요.</div><div class='gd-h'>다 배운 뒤에 이어서 배우면 좋은 것</div><div class='gd-sec'><span class='gd-jp'>ほしい</span>의 용법은 「<span class='gd-jp'>〜が欲しいです・〜たいです</span>」로 이어서 보면 좋아요. 「～을 갖고 싶다, ～하고 싶다」를 말하는 법을 배워요.</div>","n5-24":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「で」는 한국어의 <b>「~에서 ~해요」</b>와 같아요. 장소를 하나의 무대라고 생각해 보세요. 「で」는 \"이 동작은 이 무대 위에서 일어나요\"라고 알려 주는 말이에요.<br><span class='gd-jp'>カフェで仕事をします。</span>(카페에서 일해요)</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>장소 뒤에 바로 「で」를 붙이고, 그다음에 하는 동작을 이어 주세요.<br><span class='gd-pair'><span class='gd-jp'>図書館</span> → <span class='gd-jp'>図書館で勉強します</span></span>(도서관에서 공부해요)<br><span class='gd-pair'><span class='gd-jp'>家</span> → <span class='gd-jp'>家で晩ご飯を食べます</span></span>(집에서 저녁을 먹어요)<br>장소는 크든 작든 상관없어요. 나라, 도시, 가게, 방, 심지어 「여기」도 돼요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>어떤 곳에서 하는 일</span>먹기, 마시기, 사기, 보기, 공부하기, 일하기, 놀기, 사람 기다리기 등 '하는' 동작이라면 장소 뒤에 で를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で友達を待ちます。</span>(역에서 친구를 기다려요)</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートで靴を買いました。</span>(백화점에서 신발을 샀어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってもいいですか。</span>(여기에서 사진 찍어도 돼요?)</div><div class='gd-sec'><span class='gd-tag'>어디에서 했는지 묻기</span>「どこで」로 물어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、どこで買いましたか。</span>(그 가방, 어디에서 샀어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこで昼ご飯を食べますか。</span>(어디에서 점심을 먹을 거예요?)</div><div class='gd-h'>헷갈리는 표현과 구별하기</div><div class='gd-sec'><b>「で」와 「に」: 같은 장소라도 뒤에 오는 동사를 보세요</b><br>한국어도 「에」와 「에서」를 나눠 쓰니까 감각이 비슷해요. 그곳에 \"있는\" 건지, 그곳에서 \"무언가를 하는\" 건지를 보면 돼요.<br><span class='gd-jp'>図書館にいます。</span>(도서관에 있어요: 사람이 그곳에 있으니 に)<br><span class='gd-jp'>図書館で勉強します。</span>(도서관에서 공부해요: 그곳에서 무언가를 하니 で)<br>뒤에 <b>いる、ある</b>(있다) 같은 '존재'를 나타내는 말이 오면 に, <b>어떤 동작</b>이 오면 で를 써요.</div><div class='gd-sec'><b>「で」와 「へ」: 그곳으로 가는 건지, 이미 그곳에 있는 건지</b><br><span class='gd-jp'>図書館へ行きます。</span>(도서관에 가요: 그쪽으로 이동하니 へ)<br><span class='gd-jp'>図書館で本を読みます。</span>(도서관에서 책을 읽어요: 도착해서 무언가를 하니 で)</div><div class='gd-sec'><b>또 다른 「で」: 교통수단과 도구</b><br>「で」에는 다른 역할도 있어요. 이때는 앞에 장소가 아니라 물건이 와요. 한국어의 「~(으)로」에 해당해요.<br><span class='gd-jp'>バスで行きます。</span>(버스로 가요: 교통수단)<br><span class='gd-jp'>公園で遊びます。</span>(공원에서 놀아요: 장소)<br>앞의 말이 '장소'인지 '도구'인지 보면 구별할 수 있어요.</div><div class='gd-warn'>판단 요령: <b>사람이나 물건이 그곳에 \"있다\" → に, 그곳으로 \"가다\" → へ, 그곳에서 일을 \"하다\" → で.</b></div><div class='gd-h'>자주 하는 실수</div><div class='gd-warn'>・한국어의 「~에서」가 전부 で가 되는 건 아니에요. 「집에 있어요」는 <span class='gd-jp'>家にいます</span>이고, 家でいます가 아니에요.<br>・「도쿄에 살아요」는 に를 써야 해요: <span class='gd-jp'>東京に住んでいます</span>. 東京で住んでいます는 틀려요. 한국어에서는 \"도쿄에서 살아요\"라고도 자주 말해서 で를 쓰기 쉬워요. 「住む」는 그곳에 머무는 것이지, 그곳에서 어떤 일을 하는 게 아니에요.<br>・「일하다」는 で가 맞아요: <span class='gd-jp'>銀行で働いています</span>(은행에서 일하고 있어요). 住む가 に를 쓴다고 해서 働く까지 に로 바꾸지 마세요.<br>・行く、来る、帰る 같은 '이동' 동사의 목적지에는 で를 쓰지 않아요. <span class='gd-jp'>日本へ行きます</span>라고 해야 하고, 日本で行きます라고 하면 안 돼요.</div><div class='gd-h'>다음에 배울 것</div><div class='gd-sec'>「で」와 「を」를 함께 쓰면 완전한 한 문장을 말할 수 있어요: <b>장소＋で＋물건＋を＋동작</b>.<br><span class='gd-jp'>コンビニでお茶を買いました。</span>(편의점에서 차를 샀어요)<br>이어서 「に」(존재 위치)도 살펴보세요. 두 개를 같이 비교하면 に와 で가 더는 헷갈리지 않아요.</div>","n5-25":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「から」는 한국어의 <b>「~부터」「~에서」</b>예요. 몇 시부터, 어디에서, 누구에게서 할 때 모두 써요. 「まで」(~까지)와 함께 자주 나오는데, <span class='gd-jp'>AからBまで</span>는 \"A부터 B까지\"라는 뜻이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>아주 간단해요. <b>명사 뒤에 바로 から</b>를 붙이면 되고, 형태가 변하지 않아요.<br><span class='gd-pair'><span class='gd-jp'>9時</span> → <span class='gd-jp'>9時から</span></span>(9시부터) <span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅から</span></span>(역에서) <span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達から</span></span>(친구에게서)</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>시간의 시작점</span>어떤 시간부터 시작할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は9時からです。</span>(일은 9시부터예요)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日から夏休みです。</span>(내일부터 여름방학이에요)</div><div class='gd-sec'><span class='gd-tag'>장소의 출발점</span>어떤 곳에서 출발하거나 어디에서 왔는지 말할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>どこから来ましたか。</span>(어디에서 왔어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾から来ました。</span>(대만에서 왔어요)</div><div class='gd-sec'><span class='gd-tag'>누구에게서</span>물건이나 소식을 누가 줬는지 말할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達から電話がありました。</span>(친구에게서 전화가 왔어요)</div><div class='gd-h'>가장 많이 듣는 형태: AからBまで</div><div class='gd-sec'>범위를 말할 때는 「から」와 「まで」를 함께 자주 써요. 시간에도 장소에도 쓸 수 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日から金曜日まで働きます。</span>(월요일부터 금요일까지 일해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>家から駅まで歩きます。</span>(집에서 역까지 걸어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>何時から何時までですか。</span>(몇 시부터 몇 시까지예요?)</div><div class='gd-sec'>마지막 문장은 가게 영업시간이나 행사 시간을 물을 때 아주 유용해서, 일본에 가면 꼭 쓰게 될 거예요. 범위가 필요 없을 때는 「から」만 단독으로 써도 전혀 문제없어요.</div><div class='gd-h'>자주 하는 실수</div><div class='gd-warn'>・<b>어순은 한국어와 같아요</b>: 「から」는 한국어의 조사처럼 명사 <b>뒤</b>에 붙어요. 「역에서」는 <span class='gd-jp'>駅から</span>이고, から駅가 아니에요.<br>・한국어 「~에서」는 출발점과 동작 장소에 모두 쓰지만, 일본어는 출발점은 「から」, 동작 장소는 「で」로 나눠요. \"역에서 출발해요\"는 から, \"역에서 기다려요\"는 で예요.<br>・한국어로 \"내일<b>부터</b> 방학이에요\"라고 하듯이, <span class='gd-jp'>明日から夏休みです</span>만으로 충분해요. 「から」 자체에 \"~부터 시작\"이라는 뜻이 들어 있어서 \"시작\"을 따로 덧붙일 필요가 없어요.<br>・\"몇 시에 ~한다\"라고 말할 때는 「から」가 아니라 「に」를 써요. 아래에서 자세히 설명할게요.</div><div class='gd-h'>헷갈리는 표현과 구별하기</div><div class='gd-sec'><b>① 시작점의 から vs 시점의 に</b><br><span class='gd-jp'>9時に起きます。</span>(9시에 일어나요: 딱 그 시점 하나)<br><span class='gd-jp'>9時から勉強します。</span>(9시부터 공부해요: 그 후로 한동안 계속)<br>「일어나다」는 한순간에 끝나는 동작이라 9時から起きます라고 하면 매우 어색해요.</div><div class='gd-warn'>판단 요령: \"몇 시에 했다\"만 말할 때는 に, \"그때부터 계속 이어진다\"고 말할 때는 から를 써요.</div><div class='gd-sec'><b>② 시작점의 から vs 이유의 から</b><br>N5에서는 \"~니까, ~기 때문에\"라는 뜻의 「から」도 배워요. 생김새가 똑같으니 <b>앞에 무엇이 오는지</b>로 구별해야 해요.<br>시작점: <b>명사에 바로 から</b>를 붙여요. 예: <span class='gd-jp'>駅から</span>(역에서)<br>이유: 앞에 <b>문장 전체</b>가 와요. 명사는 먼저 だ나 です를 붙이고(<span class='gd-jp'>雨だから</span>、<span class='gd-jp'>雨ですから</span>), 동사나 い형용사는 보통형이나 정중형을 써요(<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>、<span class='gd-jp'>高いですから</span>).<br>같은 \"내일 시험\"으로 비교해 볼게요.<br><span class='gd-jp'>明日からテストです。</span>(내일부터 시험이에요)<br><span class='gd-jp'>明日テストだから、勉強します。</span>(내일 시험이니까 공부할 거예요)</div><div class='gd-warn'>판단 요령: から 앞에 시간, 장소, 사람 같은 명사만 있으면 \"~부터, ~에서\"이고, 앞에 だ／です나 동사·형용사의 보통형·정중형(<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>)이 오면 \"~니까, ~기 때문에\"예요. (「동사 て형＋から」는 또 다른 문법으로, \"~하고 나서\"라는 뜻이니 섞어서 생각하지 마세요.)</div><div class='gd-h'>다음에 배울 것</div><div class='gd-sec'>짝꿍인 「まで」(~까지)를 함께 배워 보세요. 나중에 「동사 て형＋から」＝\"~하고 나서 ~해요\"도 배울 거예요: <span class='gd-jp'>ご飯を食べてから、出かけます。</span>(밥을 먹고 나서 나가요)</div>","n5-33":"<div class='gd-h'>한 줄 핵심</div><div class='gd-sec'>이 「に」는 한국어의 <b>'~에'</b>와 같아요. 사람이나 물건이 <b>어디에 있는지</b> 알려 줄 때 써요. 한국어로 '냉장고에 우유가 있어요'라고 하죠? 일본어는 '냉장고' 뒤에 に를 붙이고, 마지막에 あります나 います로 끝내요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>문형: <b>장소＋に＋사람／물건＋が＋あります／います</b></div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳があります。</span>(냉장고에 우유가 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に先生がいます。</span>(교실에 선생님이 계세요)</div><div class='gd-sec'><b>あります와 います, 뭘 써야 할까요?</b> 그 대상이 스스로 움직이는지 보세요. 사람과 동물에는 <span class='gd-jp'>います</span>, 물건과 식물에는 <span class='gd-jp'>あります</span>를 써요. 한국어는 둘 다 '있다'로 말하지만, 일본어는 이렇게 나눠요.</div><div class='gd-h'>위치 말하기</div><div class='gd-sec'>한국어에서는 '책상 위', '상자 안', '역 앞'처럼 말을 그냥 이어 쓰지만, 일본어는 の로 위치를 연결하고 그 뒤에 に를 붙여요.<br><span class='gd-jp'>机の上に</span>(책상 위에), <span class='gd-jp'>箱の中に</span>(상자 안에), <span class='gd-jp'>駅の前に</span>(역 앞에), <span class='gd-jp'>机の下に</span>(책상 아래에)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前にコンビニがあります。</span>(역 앞에 편의점이 있어요)</div><div class='gd-h'>가장 자주 듣는 두 가지 형태</div><div class='gd-sec'><span class='gd-tag'>거기에 뭐가 있나</span>장소를 앞에 두고, 말하려는 대상에 が를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園に子供がいます。</span>(공원에 아이가 있어요)</div><div class='gd-sec'><span class='gd-tag'>그게 어디에 있나</span>'어떤 것이 어디에 있는지'를 말하고 싶을 때는 그 대상을 앞에 두고 は를 써요. に는 이번에도 장소 뒤에 붙어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>猫は机の下にいます。</span>(고양이는 책상 아래에 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>(화장실은 어디에 있어요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・여기서 あります／います는 사람이나 물건이 그곳에 「존재한다」는 뜻이에요. 행사나 일이 「열린다」는 뜻의 あります(예: <span class='gd-jp'>パーティーがあります</span>)라면 장소에 で를 써요: <span class='gd-jp'>明日、学校で試験があります。</span>(내일 학교에서 시험이 있어요)<br>・한국어에서도 '공원에 있어요'와 '공원에서 놀아요'는 조사가 다르죠? 일본어도 마찬가지예요. 동작을 하는 장소에는 で를 써요: <span class='gd-jp'>公園で遊びます</span>(O), 公園に遊びます(X).<br>・사람과 동물에는 あります를 쓸 수 없어요. <span class='gd-jp'>先生がいます</span>가 맞고, 先生があります는 틀려요.<br>・「사는 곳」을 말할 때도 に를 써요: <span class='gd-jp'>姉は大阪に住んでいます。</span>(언니는 오사카에 살고 있어요)</div><div class='gd-h'>비슷하게 생긴 표현과 구분하기</div><div class='gd-sec'>가장 많이 헷갈리는 건 <b>で(동작이 일어나는 장소)</b>예요. 같은 공원이라도 문장이 무엇을 말하는지 보세요.<br><span class='gd-jp'>公園に子供がいます。</span>(공원에 아이가 있어요: 아이가 거기 있다는 것만 말해요)<br><span class='gd-jp'>公園で子供が遊んでいます。</span>(아이가 공원에서 놀고 있어요: 거기서 동작을 하고 있어요)<br><span class='gd-jp'>公園でお祭りがあります。</span>(공원에서 축제가 있어요: 행사가 거기서 열려요)</div><div class='gd-warn'>구분 요령: 먼저 문장 끝을 보세요. 사람이나 물건이 「그곳에 있다」는 あります／います(그리고 住んでいます)에는 に를 써요. 먹다, 놀다, 사다, 일하다 같은 동작이나, 행사가 「열린다」는 뜻의 あります(예: <span class='gd-jp'>ホテルでパーティーがあります</span>)에는 で를 써요.</div><div class='gd-h'>다 배우고 나면 이어서 배워요</div><div class='gd-sec'>「존재 표현」에서는 '아무것도 없다', '아무도 없다'라고 말하는 방법을 배워요: <span class='gd-jp'>部屋に誰もいません。</span>(방에 아무도 없어요)</div>","n5-35":"<div class='gd-h'>한 줄 핵심</div><div class='gd-sec'>「が」를 문장 끝에 붙이면 한국어의 <b>'~지만'</b>과 같은 뜻이 돼요. 먼저 한 가지를 말하고, 기대와 다른 내용을 이어 가는 거죠. '이 가게는 비싸지만 맛있어요'를 일본어로 하면 <span class='gd-jp'>この店は高いですが、おいしいです。</span>예요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>앞 문장을 <b>끝까지 완전히 말하고</b>, N5에서는 보통 「です」나 「ます」로 끝내요. 그다음에 が를 붙이고 쉼표를 찍은 뒤 뒷문장을 이어요.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>雨です</span> → <span class='gd-jp'>雨ですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたいですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強しました</span> → <span class='gd-jp'>勉強しましたが、</span></span><br>앞절에 「です・ます」를 썼으면 뒷절에도 「です・ます」를 써서, 문장 전체의 공손함을 맞춰야 해요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>역접</span>앞뒤 두 내용의 방향이 반대이거나, 결과가 예상과 다를 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいですが、おもしろいです。</span>(일본어는 어렵지만 재미있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でしたが、出かけました。</span>(어제는 비가 왔지만 외출했어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲みましたが、まだ頭が痛いです。</span>(약을 먹었지만 아직 머리가 아파요)</div><div class='gd-sec'><span class='gd-tag'>말문 열기</span>부탁을 하거나 질문하기 전에 「すみませんが」나 「失礼ですが」를 먼저 붙여서 운을 띄워요. 이때의 が에는 '~지만'이라는 뜻이 없고, 말투를 더 공손하게 만들어 줄 뿐이에요. 한국어의 '실례지만, ~'과 비슷해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみませんが、駅はどこですか。</span>(실례지만, 역이 어디예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>失礼ですが、お名前は？</span>(실례지만, 성함이 어떻게 되세요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・한국어의 '~지만'이 앞절 끝에 붙듯이, が도 <b>앞절의 맨 끝</b>에 붙어요. 문장 맨 앞에서 '비록'에 해당하는 단어를 찾을 필요는 없어요.<br>・한 문장에 が가 두 번 나올 수도 있어요: <span class='gd-jp'>雨が降っていますが、行きます。</span>(비가 오고 있지만 갈 거예요). 첫 번째 が는 명사 「雨」 뒤에 붙어서 주어를 나타내는 が예요. 두 번째 が는 완결된 문장 「降っています」 뒤에 붙어 있어서 '~지만'이에요. 구분하는 방법은 간단해요. が 앞이 <b>명사 하나</b>인지, <b>이미 끝까지 말한 문장</b>인지 보세요.<br>・が를 썼다면 でも를 또 붙일 필요가 없어요. <span class='gd-jp'>高いですが、おいしいです。</span>라고만 해도 충분해요.<br>・친구와 이야기할 때 「高いが、おいしい」처럼 です・ます 없이 바로 が를 붙이면 딱딱하게 들려요. 글을 쓰는 것 같거든요. 친구 사이에서는 けど가 더 자연스러워요.</div><div class='gd-h'>비슷하게 생긴 표현과 구분하기</div><div class='gd-sec'>같은 '비싸지만 맛있어요'도 자주 쓰는 표현이 세 가지 있어요.<br><b>が</b>: <span class='gd-jp'>高いですが、おいしいです。</span> 비교적 격식 있는 표현이에요. 손님이나 윗사람에게 말할 때, 편지를 쓸 때 잘 어울려요.<br><b>けど</b>: <span class='gd-jp'>高いけど、おいしい。</span> 구어체 표현으로, 일상 대화에서 가장 많이 들어요. です를 붙여도 돼요: <span class='gd-jp'>高いですけど、おいしいです。</span><br><b>でも</b>: <span class='gd-jp'>高いです。でも、おいしいです。</span> 앞 문장을 마침표로 끝내고, 다음 문장 첫머리에서 でも로 말을 이어요.</div><div class='gd-warn'>구분 요령: 문장 중간에 이어 붙여서 격식 있게 말하고 싶으면 が, 친구와 대화할 때는 けど, 앞 문장을 이미 끝냈고 새 문장 첫머리에서 역접을 하고 싶으면 でも를 써요.</div><div class='gd-h'>다 배우고 나면 이어서 배워요</div><div class='gd-sec'>다음은 「けど」를 살펴봐요. が와 뜻은 같지만 더 구어적이라서, 친구와 이야기할 때는 거의 이 표현을 써요.</div>","n5-36":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>「けど」는 한국어의 「~지만」이나 「~는데」와 거의 비슷해요. 용법은 두 가지예요. 하나는 <b>앞뒤 내용이 반대</b>일 때예요. 「작지만 쓰기 편해요」 같은 경우죠. 다른 하나는 <b>먼저 말머리를 꺼낼</b> 때예요. 「죄송한데요, 좀 여쭤볼게 있는데……」처럼 화제를 꺼내는 거예요. 일본 사람들은 평소 대화에서 계속 쓰는 표현이에요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>앞뒤 반대</span>앞에서 한 가지를 말하고, 뒤에서 그와 반대되거나 뜻밖의 내용을 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>小さいけど、使いやすいです。</span>(작지만 쓰기 편해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いけど、おいしいです。</span>(이 가게는 싸지만 맛있어요)</div><div class='gd-sec'><span class='gd-tag'>말머리 꺼내기</span>먼저 배경을 설명한 뒤에 질문이나 권유, 부탁을 해요. 이때 けど에는 <b>「하지만」이라는 뜻이 없고</b>, 「~는데」에 가까워요. 뒤에 오는 말은 아예 하지 않고 상대가 이어서 말하게 두는 경우도 많아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日映画を見に行くけど、一緒に行かない？</span>(내일 영화 보러 가는데, 같이 갈래?)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですけど…</span>(저기요, 역에 가고 싶은데요……)</div><div class='gd-ex-line'>・<span class='gd-jp'>もしもし、田中ですけど…</span>(여보세요, 다나카인데요……)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>けど는 <b>앞 문장의 맨 끝</b>에 붙여요. 앞에는 먼저 완결된 문장이 와야 해요.<br><b>친구에게 말할 때 (です・ます를 쓰지 않아요)</b>:<br>동사와 い형용사는 그대로 붙여요: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くけど</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いけど</span></span><br>명사와 な형용사는 먼저 「だ」를 붙여요: <span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だけど</span></span><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいだけど</span></span></div><div class='gd-sec'><b>공손하게 말할 때</b>: 앞에 です・ます를 쓰고 けど를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますけど</span></span><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですけど</span></span><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですけど</span></span><br>「<span class='gd-jp'>〜たいんですけど…</span>」는 문장 전체를 고정 표현으로 외워 두세요. 길을 묻거나 부탁할 때, 창구에서 말을 꺼낼 때 모두 쓸 수 있어요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・명사와 な형용사에 だ를 빼먹기 쉬워요: <span class='gd-jp'>学生けど</span>×, <span class='gd-jp'>学生だけど</span>라고 해야 해요. <span class='gd-jp'>静かけど</span>×, <span class='gd-jp'>静かだけど</span>라고 해야 해요. 반대로 い형용사에는 だ를 <b>붙이지 않아요</b>: <span class='gd-jp'>高いだけど</span>×, 그냥 <span class='gd-jp'>高いけど</span>라고 해요.<br>・한국어의 「하지만」은 뒷문장 맨 앞에 오지만, 일본어의 けど는 <b>앞 문장의 끝</b>에 붙어요. 두 번째 문장 첫머리에서 「그렇지만」이라고 하고 싶다면 <span class='gd-jp'>でも</span>를 써야 해요(아래에서 비교해요).<br>・「〜けど…」에서 문장이 끝나는 건 말을 덜 한 게 아니라, 일본 사람들이 <b>조심스럽게 말을 단정 짓지 않는</b> 방식이에요. 한국어로 옮길 때 억지로 「하지만」이라고 하지 마세요. 「~는데요」 정도가 자연스러워요.<br>・けど는 말할 때 쓰는 표현이라 대화나 점원과 이야기할 때 아주 자연스러워요. 보고서나 공식적인 자리에서는 「が」로 바꾸는 편이 안전해요.<br>・<span class='gd-jp'>けれど</span>, <span class='gd-jp'>けれども</span>도 뜻은 같고, 길수록 더 격식 있는 표현이에요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 내용이에요. 옷이 비싸지만 샀어요.<br><b>けど</b>＝평소 말투: <span class='gd-jp'>高いけど、買いました。</span><br><b>が</b>＝좀 더 격식 있는 표현이고, 글이나 공식적인 자리에서 써요: <span class='gd-jp'>高いですが、買いました。</span><br><b>でも</b>＝첫 문장을 먼저 끝내고, 두 번째 문장 첫머리에서 「그래도」라고 할 때 써요: <span class='gd-jp'>高いです。でも、買いました。</span></div><div class='gd-sec'>말머리를 꺼내는 용법도 마찬가지예요. 윗사람이나 어른께 더 공손하게 말하고 싶다면 けど를 が로 바꿔요: <span class='gd-jp'>ちょっと聞きたいんですが…</span>(좀 여쭤보고 싶은데요……)</div><div class='gd-warn'>구분 요령: 평소 말할 때는 けど, 공식적인 자리나 글에서는 が, 두 문장으로 나눠서 두 번째 문장 첫머리에 「그렇지만」을 쓰고 싶으면 でも를 써요.</div>","n5-37":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>이 「に」는 <b>가거나 오거나 돌아가는 목적</b>을 나타내요. 한국어로 「사러 가요」「놀러 와요」라고 하죠. 일본어도 하려는 일을 앞에 두고 뒤에 「に行きます」「に来ます」를 붙여요: <span class='gd-jp'>買いに行きます</span>(사러 가요), <span class='gd-jp'>遊びに来ます</span>(놀러 와요).</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'><span class='gd-tag'>동사</span>먼저 동사를 ます형으로 바꾸고, 「ます」를 떼어 낸 뒤 「に」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>買います</span> → ます를 뗌 → <span class='gd-jp'>買いに行きます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べに行きます</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見に行きます</span></span><span class='gd-pair'><span class='gd-jp'>会います</span> → <span class='gd-jp'>会いに行きます</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>お土産を買いに行きます。</span>(기념품을 사러 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、友達に会いに行きます。</span>(주말에 친구를 만나러 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昼ごはんを食べに家へ帰ります。</span>(점심을 먹으러 집에 돌아가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>書類を届けに来ました。</span>(서류를 전달하러 왔어요)</div><div class='gd-sec'><span class='gd-tag'>명사</span><span class='gd-jp'>買い物</span>, <span class='gd-jp'>散歩</span>, <span class='gd-jp'>旅行</span>, <span class='gd-jp'>食事</span>처럼 그 자체가 「하나의 동작」인 명사는 바로 「に」를 붙일 수 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートへ買い物に行きます。</span>(백화점에 쇼핑하러 가요)</div><div class='gd-ex-line'>・<span class='gd-jp'>公園へ散歩に行きませんか。</span>(공원에 산책하러 갈래요?)</div><div class='gd-h'>한 문장에 장소와 목적이 함께 있을 때</div><div class='gd-sec'>순서는 보통 <b>장소＋へ　→　목적＋に　→　行きます</b>예요.<br><span class='gd-jp'>図書館へ本を借りに行きます。</span>(도서관에 책을 빌리러 가요)<br>장소 뒤에 「へ」를 쓰면 목적을 나타내는 に와 に가 연달아 두 번 나오지 않아서 듣기에 더 분명해요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・앞에는 <b>ます형에서 ます를 뗀 형태</b>를 써야 하고, 사전형을 그대로 놓으면 안 돼요. <span class='gd-jp'>買いに行きます</span>가 맞고, 「買うに行きます」는 틀려요.<br>・뒤에는 <b>이동을 나타내는 동사</b>만 올 수 있어요. 가장 흔한 건 <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>예요. 「일본어를 공부하려고 책을 봐요」처럼 이동과 관계없는 문장에는 이 に를 쓸 수 없어요.<br>・한국어는 「사러＋가요」 순서이고 일본어는 「買い＋に行く」라서, 어순은 비슷해요. 다만 「가러 사요」처럼 거꾸로 하지 않도록 「行きに買います」라고 말하지 마세요.<br>・원래 동사 앞에 있던 「を」는 그대로 남겨요: <span class='gd-jp'>お土産を買いに行きます</span>.<br>・<span class='gd-jp'>遊びに来てください。</span>(놀러 오세요)는 일본 사람들이 자주 하는 초대 표현이니 문장째로 외워 두세요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 「に行きます」라도 <b>に 앞에 무엇이 오느냐</b>에 따라 뜻이 달라져요.<br><b>장소＋に</b>＝<b>어디로</b> 가는지: <span class='gd-jp'>デパートに行きます。</span>(백화점에 가요)<br><b>동작＋に</b>＝<b>무엇을 하러</b> 가는지: <span class='gd-jp'>買い物に行きます。</span>(쇼핑하러 가요)<br>둘을 합치면: <span class='gd-jp'>デパートへ買い物に行きます。</span>(백화점에 쇼핑하러 가요)</div><div class='gd-warn'>구분 요령: に 앞이 「장소」면 어디로 가는지, に 앞이 「ます를 뗀 동사」나 「買い物, 散歩」 같은 동작이면 무엇을 하러 가는지를 나타내요.</div>","n5-39":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>「ね」는 한국어의 <b>「～네요」「～죠?」</b>와 비슷해요. <b>상대도 알고 있고 같이 느낄 수 있는</b> 일을 말하면서 공감을 구하거나 확인할 때 써요.<br>「よ」는 한국어의 <b>「～요!」「～거든요」</b>와 비슷해요. <b>상대가 아직 모르는</b> 일을 알려 주거나 일깨워 줄 때 써요.</div><div class='gd-h'>언제 쓰나요</div><div class='gd-sec'><span class='gd-tag'>ね：같이 공감하기</span>두 사람이 같은 것을 보고, 먹고, 느꼈을 때 말로 꺼내서 공감을 구해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>いい天気ですね。</span>（날씨가 좋네요）</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいですね。</span>（이 케이크 맛있네요）</div><div class='gd-sec'><span class='gd-tag'>ね：확인하기</span>대충은 알지만 잘못 기억하고 있지 않은지 상대에게 확인하고 싶을 때 써요. 점원이 주문을 확인할 때도 이렇게 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みですね。</span>（내일은 쉬는 날이죠?）</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒー二つですね。</span>（커피 두 잔이죠?）</div><div class='gd-sec'><span class='gd-tag'>よ：알려 주기</span>내가 알고 상대는 모르는 일을 말해요. 추천하거나 소식을 나눌 때 많이 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、安いですよ。</span>（이 가게 싸요）</div><div class='gd-ex-line'>・<span class='gd-jp'>この番組、面白いですよ。</span>（이 프로그램 재미있어요）</div><div class='gd-sec'><span class='gd-tag'>よ：일깨워 주기</span>상대가 알아채지 못한 일에 주의를 주고 싶을 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう始まりますよ。</span>（벌써 시작해요）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が来ましたよ。</span>（전철이 왔어요）</div><div class='gd-h'>어떻게 붙이나요</div><div class='gd-sec'>아주 간단해요. 문장을 다 말한 뒤 <b>맨 끝에 그대로 붙이기만</b> 하면 돼요.<br>공손한 말투: <span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいですね</span></span><span class='gd-pair'><span class='gd-jp'>始まります</span> → <span class='gd-jp'>始まりますよ</span></span><br>친구에게 하는 말투도 똑같이 그냥 붙이면 돼요: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>いいね</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くよ</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨だね</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>상대가 알 리 없는 일에는 ね를 붙이지 마세요</b>. 자기소개에서 「私は台湾人ですね」라고 하면 상대에게 “제가 대만 사람이죠?”라고 묻는 것처럼 들려서 어색해요. 그냥 <span class='gd-jp'>私は台湾人です。</span>라고 하면 돼요.<br>・<b>よ는 어조가 좀 더 강해요</b>. 선생님이나 상사의 말을 바로잡을 때 「それは違いますよ」처럼 よ를 붙이면 가르치려 드는 느낌이 날 수 있어요. 윗사람에게는 よ를 조금 아끼는 쪽이 안전해요.<br>・ね의 억양: <b>끝을 올리면</b> “～죠?” 하고 확인하는 뜻이고, <b>평평하거나 내리면</b> “정말 ～네요” 하고 감탄하는 뜻이에요.<br>・한국어에서도 말끝에 「～요」「～네요」「～죠」를 자주 붙이지만, 일본어는 문장마다 붙일 필요가 없어요. 그냥 사실을 설명할 때는 아무것도 안 붙여도 자연스러워요. 문장마다 ね, よ를 붙이면 오히려 시끄럽게 들려요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 「밖에 비가 와요」라도 상대가 아는지 모르는지에 따라 골라요.<br><b>ね</b>＝상대도 보고 있어서 같이 감탄할 때: <span class='gd-jp'>雨ですね。</span>（비가 오네요）<br><b>よ</b>＝상대가 집 안에 있어서 못 봤을 때 알려 줄 때: <span class='gd-jp'>雨ですよ。</span>（밖에 비가 와요）<br><b>か</b>＝나도 전혀 몰라서 물어볼 때: <span class='gd-jp'>雨ですか。</span>（비가 와요?）</div><div class='gd-sec'>「ね」와 「か」는 둘 다 질문이 될 수 있어요. 차이는 마음속에 답이 있느냐 없느냐예요.<br><span class='gd-jp'>明日は休みですか。</span>（내일은 쉬는 날이에요?: 몰라서 물어보는 거예요）<br><span class='gd-jp'>明日は休みですね。</span>（내일은 쉬는 날이죠?: 대충 알지만 확인하는 거예요）</div><div class='gd-warn'>판단 요령: 상대도 알고 있다→ね, 상대는 모르고 내가 알려 준다→よ, 나도 모른다→か.</div><div class='gd-h'>다 배운 뒤에 이어서 배워요</div><div class='gd-sec'>두 개를 이어 「よね」로 쓸 수도 있어요. 순서는 항상 よ가 앞이고, 「ねよ」라고는 하지 않아요. “내 기억엔 그런데, 맞죠?”라는 뜻이에요: <span class='gd-jp'>テストは明日ですよね。</span>（시험은 내일 맞죠?）</div>","n5-40":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>일본어 조사는 한국어 조사처럼 <b>하나가 여러 가지 뜻으로 쓰일 때가 많아요</b>. 앞에서 を, に, で, は, か의 가장 기본적인 쓰임을 배웠는데, 이번에는 이 조사들의 <b>다른 자주 쓰는 용법</b>을 한데 모아 볼게요. 조사를 볼 때는 뜻 하나만 외우지 말고, 앞뒤에 어떤 말이 오는지 보고 판단하세요.</div><div class='gd-h'>を：떠나는 곳, 지나가는 곳</div><div class='gd-sec'><span class='gd-tag'>떠나는 곳</span>어떤 장소에서 나오거나, 내리거나, 졸업할 때 그 장소에 を를 써요. <span class='gd-jp'>出る</span>, <span class='gd-jp'>降りる</span>, <span class='gd-jp'>卒業する</span>와 함께 자주 나와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に家を出ます。</span>（7시에 집을 나서요）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（다음 역에서 전철에서 내려요）</div><div class='gd-sec'><span class='gd-tag'>지나가는 곳</span>걷기, 달리기, 산책, 다리 건너기처럼 “이동하는” 동작에서는 지나가는 길이나 범위에 を를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、公園を散歩します。</span>（매일 아침 공원을 산책해요）</div><div class='gd-ex-line'>・<span class='gd-jp'>この橋を渡ってください。</span>（이 다리를 건너세요）</div><div class='gd-h'>に：빈도, 닿는 곳, 되다</div><div class='gd-sec'><span class='gd-tag'>빈도</span>기간＋に＋횟수＝일정 기간에 몇 번.</div><div class='gd-ex-line'>・<span class='gd-jp'>1日に3回、薬を飲みます。</span>（하루에 세 번 약을 먹어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>週に1回、プールへ行きます。</span>（일주일에 한 번 수영장에 가요）</div><div class='gd-sec'><span class='gd-tag'>물건이 닿는 곳</span>적어 넣거나, 앉거나, 넣을 때처럼 물건이 마지막에 “닿아서 머무는” 곳에는 に를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（여기에 이름을 써 주세요）</div><div class='gd-ex-line'>・<span class='gd-jp'>椅子に座ります。</span>（의자에 앉아요）</div><div class='gd-sec'><span class='gd-tag'>되다</span>명사＋になる＝～이/가 되다.</div><div class='gd-ex-line'>・<span class='gd-jp'>将来、先生になりたいです。</span>（장래에 선생님이 되고 싶어요）</div><div class='gd-h'>で：범위, 합계</div><div class='gd-sec'><span class='gd-tag'>범위</span>“～ 중에서 가장 ～”라고 할 때 그 범위에 で를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はクラスでいちばん背が高いです。</span>（형은 반에서 키가 제일 커요）</div><div class='gd-sec'><span class='gd-tag'>합계</span>수량＋で＝합쳐서, 전부 해서. 쇼핑할 때 정말 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>全部でいくらですか。</span>（전부 해서 얼마예요?）</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごは3つで500円です。</span>（사과는 세 개에 500엔이에요）</div><div class='gd-h'>は：대비하기</div><div class='gd-sec'><span class='gd-tag'>대비</span>두 가지를 나란히 놓고 비교할 때 각각에 は를 붙이면 “A는 그렇지만 B는 아니에요”라는 뜻이 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司は好きですが、刺身は苦手です。</span>（초밥은 좋아하지만 회는 잘 못 먹어요）</div><div class='gd-sec'>한쪽만 말해도 “다른 건 또 다르다”는 뉘앙스가 남아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は飲みません。</span>（술은 안 마셔요）</div><div class='gd-h'>か：둘 중 하나 고르기</div><div class='gd-sec'><span class='gd-tag'>선택</span>AかB＝A나 B, 그중에서 하나를 골라요.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日か火曜日に来てください。</span>（월요일이나 화요일에 오세요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・탈 때는 に, 내릴 때는 を예요: <span class='gd-jp'>電車に乗ります</span>, <span class='gd-jp'>電車を降ります</span>. 한국어로는 “전철을 타요 / 전철에서 내려요”라서 조사가 반대로 나와 헷갈리기 쉬워요.<br>・を의 “지나가는 곳” 용법은 이동하는 동작과 함께 써요. 공원에서 놀기, 도시락 먹기처럼 제자리에서 하는 일에는 で를 써요: <span class='gd-jp'>公園で遊びます</span>.<br>・종이에 쓰기, 의자에 앉기처럼 물건이 그곳에 “닿는” 경우는 に를 써요. 한국어 “～에”와 같다고 보면 쉬워요: <span class='gd-jp'>ここに書いてください</span>. で를 쓰면 “여기서(이 자리에서) 쓴다”는 동작의 장소가 돼요.<br>・대비의 は도 똑같이 wa로 읽어요. ha가 아니에요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>か, と, や는 모두 두 가지를 이어 주지만 뜻이 많이 달라요. 같은 음료수를 살 때도 이렇게 달라져요.<br><span class='gd-jp'>コーヒーと紅茶を買いました。</span>（커피와 홍차를 샀어요: 둘 다 샀어요）<br><span class='gd-jp'>コーヒーや紅茶を買いました。</span>（커피나 홍차 같은 걸 샀어요: 다른 것도 있어요）<br><span class='gd-jp'>コーヒーか紅茶を買います。</span>（커피나 홍차를 살 거예요: 하나만 골라요）</div><div class='gd-warn'>판단 요령: 전부 다면 と, 예를 몇 개 든다면 や, 하나만 고른다면 か.</div><div class='gd-h'>다 배운 뒤에 이어서 배워요</div><div class='gd-sec'>범위를 나타내는 で는 “어느 것이 가장 ～해요?”라는 질문으로도 쓸 수 있어요: <span class='gd-jp'>果物の中で何がいちばん好きですか。</span>（과일 중에서 뭘 제일 좋아해요?）</div>","n5-41":"<div class='gd-h'>한 문장으로 먼저 이해하기</div><div class='gd-sec'>「ます형」은 동사가 <b>공손한 겉옷</b>을 입은 모습이에요. 사전에는 <span class='gd-jp'>飲む</span>라고 나오지만, 선생님이나 가게 직원, 처음 만난 사람에게는 <span class='gd-jp'>飲みます</span>라고 말해야 해요. 이 과에서 연습할 건 딱 하나예요. <b>어떤 동사를 만나도 〜ます로 바꿀 수 있게 되는 것</b>이에요.</div><div class='gd-h'>바꾸는 방법: 먼저 동사가 어느 그룹인지 보기</div><div class='gd-sec'><span class='gd-tag'>1단계</span><b>먼저 3그룹(する・来る)부터 골라내세요.</b> 딱 두 개뿐이니 그대로 외우면 돼요.<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>「명사＋する」도 이 그룹이에요. <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'><span class='gd-tag'>2단계</span><b>나머지는 1그룹인지 2그룹인지 판단해요.</b><br>・마지막 글자가 <b>る가 아니면</b>(<span class='gd-jp'>書く</span>, <span class='gd-jp'>飲む</span>, <span class='gd-jp'>会う</span>, <span class='gd-jp'>待つ</span> 같은 동사) 무조건 1그룹이에요.<br>・마지막이 る이고, <b>る 앞의 소리가 a, u, o로 끝나면</b>(<span class='gd-jp'>分かる</span>의 か, <span class='gd-jp'>作る</span>의 く, <span class='gd-jp'>乗る</span>의 の) 무조건 1그룹이에요. (する, 来る는 1단계에서 이미 골라냈으니 여기에 포함하지 않아요.)<br>・마지막이 る이고, <b>る 앞의 소리가 i, e로 끝나면</b>(<span class='gd-jp'>見る</span>의 み, <span class='gd-jp'>食べる</span>의 べ, <span class='gd-jp'>起きる</span>의 き) 대부분 2그룹이에요. 하지만 예외로 1그룹인 동사가 몇 개 있으니 외워 두세요. <span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span>, <span class='gd-jp'>切る</span>예요.</div><div class='gd-sec'><b>1그룹(5단동사)</b>: 마지막 소리를 같은 행의 「い」단 소리로 바꾸고 ます를 붙여요.<br>오십음도에서 う단 소리를 い단으로 한 칸 옮기면 돼요. (세로 표는 한 칸 위로, 가로 표는 한 칸 왼쪽으로 가요.) う→い, く→き, ぐ→ぎ, す→し, つ→ち, ぬ→に, ぶ→び, む→み, る→り.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く를 き로 바꿈 → <span class='gd-jp'>書きます</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会います</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話します</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぎます</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊びます</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>2그룹(1단동사)</b>: 마지막의 「る」를 떼고 ます를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span><span class='gd-pair'><span class='gd-jp'>着る</span> → <span class='gd-jp'>着ます</span></span></div><div class='gd-h'>가장 자주 듣는 모습</div><div class='gd-sec'>매일 하는 습관도, 내일 할 일도 똑같이 ます형으로 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝パンを食べます。</span>（저는 매일 아침 빵을 먹어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日、日本語を勉強します。</span>（저는 매일 일본어를 공부해요）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、友達が家に来ます。</span>（내일 친구가 우리 집에 와요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・사전형 뒤에 그대로 ます를 붙이면 안 돼요. <span class='gd-jp'>飲むます</span>, <span class='gd-jp'>行くます</span>는 모두 틀린 말이에요. 먼저 마지막 소리를 바꿔야 해요.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span>, <span class='gd-jp'>切る</span>는 2그룹처럼 생겼지만 사실 1그룹이에요. <span class='gd-jp'>帰ります</span>가 맞고 帰ます는 틀려요.<br>・<span class='gd-jp'>来ます</span>는 <b>きます</b>라고 읽어요. くます도, 来ります도 아니에요. <span class='gd-jp'>する</span>도 すります가 되지 않아요.<br>・「ます」의 「す」는 아주 약하게 발음될 때가 많아서 mas처럼 들려요. 정상적인 발음이니 잘못 들은 게 아니에요.</div><div class='gd-h'>익히고 나서 이어서 배울 내용</div><div class='gd-sec'>ます를 떼고 남은 부분(<span class='gd-jp'>飲み</span>, <span class='gd-jp'>食べ</span>, <span class='gd-jp'>し</span>)은 계속 쓰게 돼요. 뒤에 다른 꼬리를 붙이면 새로운 문형이 되거든요.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>（마셨어요）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みましょう</span></span>（마셔요, 마시자요）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたいです</span></span>（마시고 싶어요）</div>","n5-42":"<div class='gd-h'>한 문장으로 먼저 이해하기</div><div class='gd-sec'>て형은 동사의 <b>「연결 고리」</b>예요. 레고 블록 위에 다른 블록을 끼울 수 있는 볼록한 부분 같은 거죠. 한국어로 「일어나서 세수해요」라고 하듯이, 일본어도 「일어나다」를 て형으로 바꾸고 그 뒤에 다음 동작을 이어요. 「～해 주세요」「～하고 있어요」처럼 중요한 문형 중에도 동사를 먼저 て형으로 바꿔야 이어지는 것이 많아서, <b>가장 중요한 활용</b>이라고 불러요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>동작 잇기</span>여러 동작을 순서대로 이어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、顔を洗います。</span>（아침에 일어나서 세수해요）</div><div class='gd-sec'><span class='gd-tag'>문형 잇기</span>뒤에 다른 말을 붙여서 새로운 뜻을 만들어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（여기에 이름을 써 주세요）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べています。</span>（지금 밥을 먹고 있어요）</div><div class='gd-sec'><span class='gd-tag'>친구 사이의 부탁</span>친구에게 말할 때는 て형만 말해도 가볍게 「～해 줘」 하고 부탁하는 말이 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと待って。</span>（잠깐만 기다려 줘）</div><div class='gd-h'>바꾸는 방법: 먼저 동사가 어느 그룹인지 보기</div><div class='gd-sec'><b>2그룹(1단동사)</b>: 가장 쉬워요. 「る」를 떼고 「て」를 붙이면 돼요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span></div><div class='gd-sec'><b>3그룹(딱 두 개, 그대로 외우기)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span><br><span class='gd-jp'>勉強する</span> 같은 「명사＋する」도 똑같아요. <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強して</span></span></div><div class='gd-sec'><b>1그룹(5단동사)</b>: <b>마지막 글자</b>가 무엇인지 보고 다섯 묶음으로 나눠요.<br><b>う・つ・る → って</b><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br><b>む・ぶ・ぬ → んで</b>(탁점이 있는 で예요)<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んで</span></span><br><b>く → いて</b><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span></span><br><b>ぐ → いで</b><br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いで</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br><b>す → して</b><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span></span><br><b>유일한 예외</b>: <span class='gd-jp'>行く</span>는 규칙대로라면 「行いて」가 되어야 하지만, 실제로는 <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span>예요.</div><div class='gd-sec'>외우기 쉬운 공식이에요. 입에 붙을 때까지 읽어 보세요. <b>うつる って、むぶぬ んで、く いて、ぐ いで、す して, 行く는 行って</b></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span>는 2그룹처럼 생겼지만 사실 1그룹이에요. <span class='gd-jp'>帰って</span>가 맞고 帰て는 틀려요.<br>・<span class='gd-jp'>行って</span>는 예외지만, <span class='gd-jp'>書いて</span>, <span class='gd-jp'>聞いて</span>처럼 く로 끝나는 다른 동사는 그대로 규칙을 따라요. 전부 って로 바꾸면 안 돼요.<br>・ぐ는 <b>いで</b>, む・ぶ・ぬ는 <b>んで</b>로 바뀌는데, 泳いて, 飲んて처럼 잘못 쓰는 사람이 많아요. 탁점을 빠뜨리지 마세요.<br>・작은 「っ」는 한 박자를 쉬어야 해요. <span class='gd-jp'>来て</span>(きて, 와)와 <span class='gd-jp'>切って</span>(きって, 잘라)는 이 한 박자만 다르지만 뜻은 완전히 달라요.<br>・<span class='gd-jp'>来て</span>는 <b>きて</b>라고 읽어요. こて나 くて가 아니에요.<br>・て형 자체에는 과거나 현재가 없고, <b>마지막 동사</b>가 시제를 정해요. <span class='gd-jp'>シャワーを浴びて、寝ました。</span>（샤워하고 잤어요）</div><div class='gd-h'>익히고 나서 이어서 배울 내용</div><div class='gd-sec'>て형이 익숙해지면 <b>た형(과거의 보통체)은 거의 덤으로 얻는 셈이에요.</b> 규칙이 완전히 똑같고, て를 た로, で를 だ로 바꾸기만 하면 돼요.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>이어서 「～てください」(～해 주세요), 「～ています」(～하고 있어요), 「～てから」(～한 뒤에)를 배워 볼 수 있어요. 모두 이 카드의 활용을 바탕으로 해요.</div>","n5-45":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>보통형은 「です・ます」를 뗀 <b>친구끼리 쓰는 말투</b>예요. 여러 문형 앞에 붙는 기본형이기도 해요. 모든 단어에는 네 가지 모양이 있어요. 한국어의 「간다／안 간다／갔다／안 갔다」와 딱 맞아떨어져요. 바로 <b>현재 긍정, 현재 부정, 과거 긍정, 과거 부정</b>이에요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>친한 사람과 말할 때</span>가족이나 친구 사이에서는 ます를 쓰지 않고 바로 보통형으로 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見た。</span>（어제 영화를 봤어）</div><div class='gd-sec'><span class='gd-tag'>문형에 이어질 때</span>문장 전체가 정중해도 중간에서는 보통형으로 바꾼 뒤 뒤의 문형을 이어 붙이는 경우가 많아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>（내일은 비가 올 것 같아요）</div><div class='gd-h'>어떻게 바뀔까요: 먼저 동사의 종류부터 확인해요</div><div class='gd-sec'><b>1그룹(5단 동사)</b><br>부정: 마지막 음을 같은 행의 「あ」단 음으로 바꾸고 ない를 붙여요.<span class='gd-pair'><span class='gd-jp'>行く</span> → く를 か로 바꿈 → <span class='gd-jp'>行かない</span></span><br>과거: て형을 만드는 방법과 같고, て를 た로 바꾸기만 하면 돼요.<span class='gd-pair'><span class='gd-jp'>行って</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>과거 부정: ない의 「い」를 「かった」로 바꿔요.<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかった</span></span><br>한 세트로 볼까요: <span class='gd-jp'>買う／買わない／買った／買わなかった</span></div><div class='gd-sec'><b>2그룹(1단 동사)</b>: 제일 쉬워요. 「る」를 떼고 ない, た, なかった를 붙이면 끝이에요.<br><span class='gd-jp'>食べる／食べない／食べた／食べなかった</span><br><span class='gd-jp'>見る／見ない／見た／見なかった</span></div><div class='gd-sec'><b>3그룹(딱 두 개, 그냥 외워요)</b><br><span class='gd-jp'>する／しない／した／しなかった</span><br><span class='gd-jp'>来る／来ない／来た／来なかった</span>（くる／こない／きた／こなかった）<br><span class='gd-jp'>勉強する</span>처럼 「명사＋する」인 동사는 する가 바뀌는 대로 따라가요. <span class='gd-jp'>勉強しない</span>、<span class='gd-jp'>勉強した</span>、<span class='gd-jp'>勉強しなかった</span>가 돼요.</div><div class='gd-h'>형용사와 명사는 어떻게 바뀔까요</div><div class='gd-sec'><b>い형용사</b>: 부정은 마지막 い를 くない로, 과거는 い를 かった로 바꿔요.<br><span class='gd-jp'>高い／高くない／高かった／高くなかった</span></div><div class='gd-sec'><b>な형용사</b>: 뒤에 だ, じゃない, だった, じゃなかった를 붙여요.<br><span class='gd-jp'>静かだ／静かじゃない／静かだった／静かじゃなかった</span></div><div class='gd-sec'><b>명사</b>: な형용사와 변하는 방식이 똑같아요.<br><span class='gd-jp'>学生だ／学生じゃない／学生だった／学生じゃなかった</span></div><div class='gd-warn'>작은 발견: 동사든 형용사든 명사든 부정은 마지막이 모두 「ない」예요. 과거로 바꾸는 방법도 같아요: <span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかった</span></span>. 이 방법만 기억하면 네 번째(과거 부정)는 따로 외울 필요가 거의 없어요.</div><div class='gd-h'>ます・です와 비교하며 기억해요</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><br><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span><br>い형용사가 가장 편해요. です만 떼면 돼요: <span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span><br>な형용사와 명사는 です를 だ로 바꿔요: <span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・う로 끝나는 1그룹 동사는 부정에서 「わ」로 바뀌어요. <span class='gd-jp'>買わない</span>이지, 買あない가 아니에요.<br>・<span class='gd-jp'>ある</span>의 부정은 <span class='gd-jp'>ない</span>예요. あらない가 아니에요.<br>・<span class='gd-jp'>行く</span>의 과거는 <span class='gd-jp'>行った</span>예요. 行いた가 아니에요.<br>・<span class='gd-jp'>いい</span>는 활용하면 よ로 시작하는 형태로 바뀌어요: <span class='gd-jp'>よくない</span>、<span class='gd-jp'>よかった</span>、<span class='gd-jp'>よくなかった</span>.<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>는 い형용사처럼 보이지만 사실 な형용사예요. <span class='gd-jp'>きれいじゃない</span>라고 해야 하고, きれくない가 아니에요.<br>・い형용사 뒤에는 だ를 붙일 수 없어요. <span class='gd-jp'>高い</span>라고만 하고, 高いだ라고 하면 안 돼요.<br>・명사나 な형용사를 바로 「だ」로 끝내면 말투가 조금 딱딱해요. 친구와 이야기할 때는 だ를 생략하거나 뒤에 よ를 붙이는 경우가 많아요. 예: <span class='gd-jp'>学生だよ</span>.<br>・보통형으로 친구에게 질문할 때는 보통 か를 붙이지 않고 끝을 올려서 말해요: <span class='gd-jp'>明日、来る？</span>（내일 올 거야?）</div><div class='gd-h'>배운 다음에 이어서 볼 내용</div><div class='gd-sec'>보통형에 문형을 붙일 때는 명사와 な형용사의 「だ」를 특히 조심해야 해요. 남겨 두기도 하고, 떼기도 하고, な로 바꾸기도 해요.<br><span class='gd-jp'>静かだと思う。</span>（조용하다고 생각해: だ를 남김）<br><span class='gd-jp'>静かでしょう。</span>（조용하겠지요: だ를 뗌）<br><span class='gd-jp'>学生なの？</span>（학생이야?: だ를 な로 바꿈）<br>이런 내용은 「～でしょう」와 형식명사 「の」 수업에서 하나씩 설명할게요.</div>","n5-46":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어에서는 「높<b>은</b> 산」「예<b>쁜</b> 꽃」처럼 형용사가 명사 앞에서 모양이 바뀌어요(～ㄴ/은). 일본어는 두 가지로 나뉘어요. <b>い형용사는 그대로 명사 앞에 붙고</b>, <b>な형용사는 중간에 「な」를 넣어요</b>. 이 「な」의 위치가 한국어의 「～ㄴ/은」 자리와 비슷해요.</div><div class='gd-h'>어떻게 이을까요</div><div class='gd-sec'><b>い형용사</b>(끝이 い인 형용사): 아무것도 바꾸지 않고 그대로 명사 앞에 둬요.<br><span class='gd-pair'><span class='gd-jp'>高い</span>＋<span class='gd-jp'>山</span> → <span class='gd-jp'>高い山</span></span>（높은 산）<br><span class='gd-pair'><span class='gd-jp'>新しい</span>＋<span class='gd-jp'>靴</span> → <span class='gd-jp'>新しい靴</span></span>（새 신발）</div><div class='gd-sec'><b>な형용사</b>: 뒤에 「な」를 먼저 붙이고 명사를 이어요.<br><span class='gd-pair'><span class='gd-jp'>きれい</span>＋な＋<span class='gd-jp'>花</span> → <span class='gd-jp'>きれいな花</span></span>（예쁜 꽃）<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋な＋<span class='gd-jp'>部屋</span> → <span class='gd-jp'>静かな部屋</span></span>（조용한 방）</div><div class='gd-h'>가장 자주 듣는 모양</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい靴を買いました。</span>（새 신발을 샀어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>これはおいしいケーキですね。</span>（이거 맛있는 케이크네요）</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな部屋がいいです。</span>（조용한 방이 좋아요）</div><div class='gd-ex-line'>・<span class='gd-jp'>好きな食べ物は何ですか。</span>（좋아하는 음식이 뭐예요?）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span>는 끝이 い이지만 사실 <b>な형용사</b>예요. <span class='gd-jp'>きれいな花</span>、<span class='gd-jp'>きらいな食べ物</span>라고 해야 하고, きれい花라고 하면 안 돼요.<br>・한국어의 「～의」를 떠올리면서 중간에 「の」를 넣는 사람이 많아요. 「高いの山」「静かの部屋」는 모두 틀려요. い형용사는 아무것도 붙이지 않고, な형용사는 「な」를 붙여요.<br>・한국어로는 「많은 사람」이라고 하니까 「多い人」이라고 말하고 싶어지지만, 이렇게는 쓸 수 없어요. <span class='gd-jp'>たくさんの人</span>라고 해야 해요.<br>・<span class='gd-jp'>大きな家</span>、<span class='gd-jp'>小さな店</span>를 보게 될 수도 있어요. 잘못 쓴 게 아니라, <span class='gd-jp'>大きい</span>、<span class='gd-jp'>小さい</span>에는 따로 있는 형태예요. 이 형태는 명사 앞에서만 쓸 수 있어요. <span class='gd-jp'>大きい家</span>、<span class='gd-jp'>大きな家</span> 둘 다 맞아요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'><span class='gd-tag'>문장 끝 vs 명사 앞</span>な형용사의 「な」는 <b>뒤에 명사가 올 때만 나타나요</b>. 문장 끝에서는 바로 です를 붙여요.<br><span class='gd-jp'>この部屋は静かです。</span>（이 방은 조용해요）<br><span class='gd-jp'>静かな部屋です。</span>（조용한 방이에요）<br>「この部屋は静かなです」라고는 말할 수 없어요.</div><div class='gd-sec'><span class='gd-tag'>명사＋の</span>앞에 오는 말이 <b>명사</b>라면 중간에는 「な」가 아니라 「の」를 써요.<br><span class='gd-jp'>日本の車</span>（일본 차: 명사＋の）<br><span class='gd-jp'>新しい車</span>（새 차: い형용사는 바로 연결）<br><span class='gd-jp'>きれいな車</span>（예쁜 차: な형용사＋な）</div><div class='gd-warn'>판단 요령: 앞에 오는 말이 무엇인지 먼저 스스로 물어보세요. い형용사는 그대로 붙이고, な형용사는 な를, 명사는 の를 넣어요.</div><div class='gd-h'>배운 다음에 이어서 볼 내용</div><div class='gd-sec'>형용사는 동사를 꾸며 줄 수도 있어요. 예를 들어 <span class='gd-jp'>早く起きます</span>（일찍 일어나요）처럼요. 이것을 「형용사의 부사적 용법」이라고 해요.</div>","n5-43":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>사전형은 「〜ます」의 <b>반말 버전</b>이에요. 사전에서 찾으면 나오는 모양이기도 해요. ない형은 「〜ません」의 <b>반말 버전</b>이에요. 선생님께는 <span class='gd-jp'>行きます</span>／<span class='gd-jp'>行きません</span>이라고 하고, 친구에게는 <span class='gd-jp'>行く</span>／<span class='gd-jp'>行かない</span>라고 해요. 뜻은 같고 말투만 좀 더 편해요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>친구·가족과 대화할 때</span>ます와 마찬가지로 현재의 습관이나 아직 일어나지 않은 일에 써요. 질문은 끝을 올려서 말하면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、何時に起きる？</span>（내일 몇 시에 일어나?）</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に起きる。</span>（7시에 일어나요）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は学校に行かない。</span>（저는 오늘 학교에 안 가요）</div><div class='gd-ex-line'>・<span class='gd-jp'>私はお酒を飲まない。</span>（저는 술을 안 마셔요）</div><div class='gd-h'>활용법: 먼저 동사가 어느 그룹인지 확인해요</div><div class='gd-sec'><b>먼저 ます형에서 사전형으로 바꾸기</b><br><b>1그룹(5단동사)</b>: ます 앞의 소리를 같은 행의 「う」단 소리로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → み를 む로 바꾸기 → <span class='gd-jp'>飲む</span></span><span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span></span><span class='gd-pair'><span class='gd-jp'>歌います</span> → <span class='gd-jp'>歌う</span></span><span class='gd-pair'><span class='gd-jp'>帰ります</span> → <span class='gd-jp'>帰る</span></span><br><b>2그룹(1단동사)</b>: ます를 る로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>起きます</span> → <span class='gd-jp'>起きる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br><b>3그룹(딱 두 개뿐이니 그냥 외워요)</b>: <span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span></div><div class='gd-sec'><b>다음으로 사전형에서 ない형으로 바꾸기</b><br><b>1그룹(5단동사)</b>: 마지막 소리를 같은 행의 「あ」단 소리로 바꾸고 ない를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く를 か로 바꾸기 → <span class='gd-jp'>書かない</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たない</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らない</span></span><br>마지막이 「う」일 때는 「あ」가 아니라 <b>「わ」로 바꿔요</b>.<br><span class='gd-pair'><span class='gd-jp'>買う</span> → う를 わ로 바꾸기 → <span class='gd-jp'>買わない</span></span><span class='gd-pair'><span class='gd-jp'>歌う</span> → <span class='gd-jp'>歌わない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>2그룹(1단동사)</b>: る를 떼고 ない를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きない</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>3그룹(그냥 외워요)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>「명사＋する」도 똑같아요: <span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話しない</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・「う」로 끝나는 동사는 「あない」로 바꾸면 안 돼요. <span class='gd-jp'>買わない</span>가 맞고, 買あない는 틀려요.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span>는 2그룹처럼 생겼지만 사실 1그룹이에요. <span class='gd-jp'>帰らない</span>가 맞고, 帰ない는 틀려요.<br>・来る는 읽는 법이 세 가지라서 잘 구분해야 해요. <span class='gd-jp'>来る</span>는 くる, <span class='gd-jp'>来ます</span>는 きます, <span class='gd-jp'>来ない</span>는 こない로 읽어요.<br>・<span class='gd-jp'>ある</span>(있다)의 부정은 あらない가 아니라 <span class='gd-jp'>ない</span>예요. <span class='gd-jp'>お金がない。</span>（돈이 없어요）<br>・ない형은 '안 ~한다'이지 '~할 수 없다'가 아니에요. <span class='gd-jp'>食べない</span>는 '안 먹어요'이고, '못 먹어요'가 아니에요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'>같은 '내일은 안 와요'라도 누구에게 말하느냐에 따라 달라져요.<br>선생님이나 상사에게: <span class='gd-jp'>明日は来ません。</span><br>친구나 가족에게: <span class='gd-jp'>明日は来ない。</span><br>뜻은 완전히 같고 공손함의 정도만 달라요. 한국어의 존댓말과 반말 차이를 떠올리면 쉬워요. 어른께 <span class='gd-jp'>来ない</span>라고 하면 버릇없게 들리고, 친한 친구에게 계속 <span class='gd-jp'>来ません</span>이라고 하면 거리감이 느껴져요.</div><div class='gd-warn'>구분 요령: <span class='gd-jp'>ます</span>는 사전형과, <span class='gd-jp'>ません</span>은 ない형과 짝이에요. 먼저 상대가 누구인지 생각하고 어느 쪽을 쓸지 정하세요.</div><div class='gd-h'>다 익힌 다음에 배울 것</div><div class='gd-sec'>사전형과 ない형 뒤에는 여러 문법을 이어 붙일 수 있어요. 예를 들어 상대에게 하지 말라고 부탁할 때는 이렇게 말해요. <span class='gd-jp'>ここで写真を撮らないでください。</span>（여기서 사진을 찍지 말아 주세요） 다음 단계로 과거 표현도 배워 보세요. <span class='gd-jp'>行った</span>／<span class='gd-jp'>行かなかった</span></div>","n5-44":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>た형은 「〜ました」의 <b>반말 버전</b>이고, なかった형은 「〜ませんでした」의 <b>반말 버전</b>이에요. 선생님께는 「<span class='gd-jp'>昨日、映画を見ました</span>」라고 하고, 친구에게는 「<span class='gd-jp'>昨日、映画を見た</span>」라고 해요. 둘 다 '어제 영화를 봤어요'라는 뜻이고, 말투만 좀 더 편해요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>친한 사람과 지난 일을 얘기할 때</span>친구나 가족끼리 이미 일어난 일을 말할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、渋谷で友達に会った。</span>（어제 시부야에서 친구를 만났어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べなかった。</span>（오늘 아침에는 아무것도 안 먹었어요）</div><div class='gd-sec'><span class='gd-tag'>혼잣말, 일기 쓸 때</span>공손하게 말할 상대가 없을 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、傘を忘れた。</span>（아, 우산을 깜빡했어요）</div><div class='gd-sec'><span class='gd-tag'>다른 문법에 이어 쓸 때</span>뒤에 붙는 문법 중 많은 것이 먼저 た형으로 바꿔야 이어지니까 이건 꼭 알아야 해요.</div><div class='gd-h'>た형 만드는 법: 먼저 동사가 어느 그룹인지 확인해요</div><div class='gd-sec'><b>て형을 이미 안다면 제일 쉬워요</b>: て형의 「て」를 「た」로, 「で」를 「だ」로 바꾸면 끝이에요.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>1그룹(5단동사)</b>: 마지막 소리를 보고 아래처럼 바꿔요.<br>う・つ・る로 끝나면 → った: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待った</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰った</span></span><br>ぬ・む・ぶ로 끝나면 → んだ: <span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んだ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んだ</span></span><br>く로 끝나면 → いた: <span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><br>ぐ로 끝나면 → いだ: <span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><br>す로 끝나면 → した: <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>유일한 예외: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>（く로 끝나지만 行いた가 아니에요）</div><div class='gd-sec'><b>2그룹(1단동사)</b>: 마지막 「る」를 떼고 「た」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きた</span></span></div><div class='gd-sec'><b>3그룹(딱 두 개뿐이니 그냥 외워요)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>なかった형 만드는 법</div><div class='gd-sec'>먼저 ない형으로 바꾼 다음 「ない」를 「なかった」로 바꿔요. 세 그룹 모두 같은 방법이에요.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span> → <span class='gd-jp'>会わなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span> → <span class='gd-jp'>しなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない） → <span class='gd-jp'>来なかった</span>（こなかった）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はどこにも行かなかった。</span>（어제는 아무 데도 안 갔어요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>行く</span>의 た형은 <span class='gd-jp'>行った</span>예요. 行いた가 아니에요.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>知る</span>는 2그룹처럼 생겼지만 사실 1그룹이에요. <span class='gd-jp'>帰った</span>, <span class='gd-jp'>走った</span>가 맞고, 帰た, 走た는 틀려요.<br>・<span class='gd-jp'>来た</span>는 <b>きた</b>, <span class='gd-jp'>来なかった</span>는 <b>こなかった</b>로 읽어요. 같은 한자인데 읽는 법이 달라요.<br>・<span class='gd-jp'>ある</span>의 부정은 あらない가 아니라 그냥 <span class='gd-jp'>ない</span>이고, 과거는 <span class='gd-jp'>なかった</span>예요. <span class='gd-jp'>時間がなかった。</span>（그때 시간이 없었어요）<br>・한국어에서는 '아직 안 먹었어요'처럼 과거형으로 '아직 안 했다'를 말하지만, 일본어에서는 이때 <span class='gd-jp'>食べなかった</span>를 쓰지 않아요. なかった는 '그때 하지 않았다'처럼 이미 지나간 일을 말해요. '지금까지 아직 안 했다'는 <span class='gd-jp'>まだ食べていない</span>라고 해요.<br>・た형과 なかった형은 친구 사이에서 쓰는 말투예요. 윗사람에게 지난 일을 말할 때는 문장 끝을 항상 「〜ました」나 「〜ませんでした」로 해요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'><b>た형 vs ました</b>: 뜻은 완전히 같고, 누구에게 말하느냐만 달라요.<br><span class='gd-jp'>昨日、映画を見ました。</span>（선생님께: 저는 어제 영화를 봤어요）<br><span class='gd-jp'>昨日、映画を見た。</span>（친구에게: 나 어제 영화 봤어）<br>부정도 마찬가지예요. <span class='gd-jp'>行きませんでした</span>와 <span class='gd-jp'>行かなかった</span>는 둘 다 '안 갔다'인데, 앞의 것은 공손하고 뒤의 것은 좀 더 편한 말투예요.</div><div class='gd-sec'><b>た vs て</b>: 소리는 하나 차이지만 기능은 완전히 달라요. 「た」는 말을 끝맺으며 이미 했다는 뜻이고, 「て」는 말이 아직 끝나지 않아 뒤에 이어지거나 부탁할 때 써요.<br><span class='gd-jp'>ご飯を食べた。</span>（밥을 먹었어요）<br><span class='gd-jp'>ご飯を食べて、すぐ寝た。</span>（밥을 먹고 바로 잤어요）</div><div class='gd-warn'>구분 요령: 문장이 여기서 끝나고 일이 이미 일어났다 → た, 뒤에 말이 더 이어진다 → て, 윗사람이나 손님에게 말한다 → ました, ませんでした로 바꿔요.</div><div class='gd-h'>다 익힌 다음에 배울 것</div><div class='gd-sec'>た형 뒤에 「り」를 붙이면 「〜たり〜たりします」가 돼요. 이것저것 한다는 뜻이에요. <span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（주말에는 영화를 보기도 하고 쇼핑을 하기도 해요）<br>た형에 「あとで」를 붙이면 '~한 후에'라는 뜻이에요. <span class='gd-jp'>ご飯を食べたあとで、散歩します。</span>（밥을 먹은 후에 산책해요）</div>","n5-47":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어에서는 동작이 어떻게 이루어지는지 말할 때 '일찍 일어나요', '깨끗하게 청소했어요'처럼 동사 앞에 부사를 붙이죠. 일본어도 같아요. 형용사의 <b>끝부분을 조금 바꾸면</b> 동사 앞에 놓고 그 동작을 어떻게 하는지 설명할 수 있어요.</div><div class='gd-h'>어떻게 바꿀까: 먼저 어떤 형용사인지 보세요</div><div class='gd-sec'><b>い형용사 (「い」로 끝나는 형용사)</b>: 마지막 「い」를 「く」로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>早い</span> → い를 く로 → <span class='gd-jp'>早く</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きく</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>明日は早く起きます。</span>(내일은 일찍 일어나요)</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を大きく書いてください。</span>(이름을 크게 써 주세요)</div><div class='gd-sec'><b>な형용사 (명사를 꾸밀 때 「な」가 붙는 형용사)</b>: 그대로 「に」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → に를 붙여서 → <span class='gd-jp'>静かに</span></span><br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいに</span></span><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部屋をきれいに掃除しました。</span>(방을 깨끗하게 청소했어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館では静かに話してください。</span>(도서관에서는 조용히 말해 주세요)</div><div class='gd-sec'><b>예외는 외워 두세요</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よく</span></span>예요. いく가 아니에요. いい로 끝나는 말도 마찬가지예요. 예를 들면 <span class='gd-pair'><span class='gd-jp'>かっこいい</span> → <span class='gd-jp'>かっこよく</span></span>처럼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(어제는 잘 잤어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>かっこよく踊りたいです。</span>(멋있게 춤추고 싶어요)</div><div class='gd-h'>한국어와 어순이 같아요</div><div class='gd-sec'>한국어도 '춤을 잘 춰요', '글씨를 예쁘게 써요'처럼 꾸미는 말이 동사 <b>앞에</b> 와요. 일본어도 똑같이 <b>먼저 어떻게 하는지 말하고, 그다음에 동작을 말해요</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは上手に踊ります。</span>(다나카 씨는 춤을 잘 춰요)</div><div class='gd-ex-line'>・<span class='gd-jp'>字をきれいに書きます。</span>(글씨를 예쁘게 써요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>有名</span>는 끝에 い가 있지만 사실은 な형용사예요. <span class='gd-jp'>きれいに</span>라고 해야 하고, きれく는 틀려요.<br>・형용사의 원래 모양을 그대로 동사 앞에 놓을 수는 없어요. 早い起きます라고 하면 안 되고 <span class='gd-jp'>早く起きます</span>라고 해야 해요. 静かな話します도 안 되고 <span class='gd-jp'>静かに話します</span>라고 해야 해요.<br>・<span class='gd-jp'>よく</span>는 '잘'이라는 뜻 외에 '자주'라는 뜻으로도 많이 써요. <span class='gd-jp'>よく行きます</span>는 '자주 가요'예요. 앞뒤 문맥을 보고 판단하세요.<br>・<span class='gd-jp'>早く</span>와 <span class='gd-jp'>速く</span>는 둘 다 はやく로 읽지만, 「早く」는 시간이 이른 것(일찍), 「速く」는 속도가 빠른 것(빨리)이에요. <span class='gd-jp'>早く起きます</span>(일찍 일어나요), <span class='gd-jp'>速く走ります</span>(빨리 달려요).</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>지난 과에서 배운 <b>형용사가 명사를 꾸미는 형태</b>와 이번 과가 아주 헷갈리기 쉬워요. 차이는 <b>뒤에 무엇이 오는지</b>만 보면 돼요.<br>명사(사람, 물건)가 오면: い형용사는 그대로, な형용사는 「な」를 붙여요.<br>동사(동작)가 오면: い형용사는 「く」로 바꾸고, な형용사는 「に」를 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな人です。</span>(조용한 사람이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>静かに話します。</span>(조용히 말해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>早い電車に乗ります。</span>(이른 시간의 전철을 타요)</div><div class='gd-ex-line'>・<span class='gd-jp'>早く来てください。</span>(일찍 와 주세요)</div><div class='gd-warn'>판단 요령: 뒤에 '사물'이 오면 「〜い／〜な」, 뒤에 '동작'이 오면 「〜く／〜に」를 써요.</div><div class='gd-h'>다 배운 뒤에 이어서 배우면 좋아요</div><div class='gd-sec'>같은 く／に라도 뒤에 <span class='gd-jp'>なります</span>가 오면 '~해지다', <span class='gd-jp'>します</span>가 오면 '~하게 만들다'라는 뜻이 돼요. <span class='gd-jp'>寒くなりました。</span>(추워졌어요), <span class='gd-jp'>静かにしてください。</span>(조용히 해 주세요)</div>","n5-48":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어에서는 '<b>지난주에 빌린</b> 책', '<b>동생이 다니는</b> 학교'처럼 긴 말을 명사 앞에 붙여서 어떤 것인지 설명하죠. 일본어도 똑같이 <b>명사 앞에 놓고</b>, 순서도 한국어와 거의 같아요. 다른 점은 하나뿐이에요. <b>사이에 연결하는 말을 따로 넣지 않고</b> 그대로 붙여요.<br><span class='gd-jp'>先週借りた本</span>(지난주에 빌린 책)</div><div class='gd-h'>어떻게 연결할까</div><div class='gd-sec'>명사를 꾸미는 부분에는 <b>보통형</b>을 써요. 친구끼리 말할 때처럼 ます와 です가 없는 형태이고, 이것을 명사 바로 앞에 붙이면 돼요.<br><span class='gd-pair'><span class='gd-jp'>本を借りました</span> → <span class='gd-jp'>借りた</span></span> → <span class='gd-jp'>先週借りた本</span></div><div class='gd-sec'><span class='gd-tag'>동사</span>어떤 형태를 쓰느냐에 따라 뜻이 달라져요.<br><span class='gd-jp'>見る映画</span>(볼 영화)<br><span class='gd-jp'>見ない映画</span>(안 보는 영화)<br><span class='gd-jp'>見た映画</span>(본 영화)<br><span class='gd-jp'>見なかった映画</span>(안 본 영화)<br><span class='gd-jp'>見ている映画</span>(보고 있는 영화)</div><div class='gd-sec'><span class='gd-tag'>い형용사로 끝날 때</span>그대로 이어요.<br><span class='gd-jp'>髪が長い人</span>(머리가 긴 사람)</div><div class='gd-sec'><span class='gd-tag'>な형용사로 끝날 때</span>현재 긍정일 때는 だ를 <b>な</b>로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>交通が便利だ</span> → <span class='gd-jp'>交通が便利な町</span></span>(교통이 편리한 도시)<br>「便利だ町」라고 하면 안 돼요.</div><div class='gd-sec'><span class='gd-tag'>명사로 끝날 때</span>현재 긍정일 때는 だ를 <b>の</b>로 바꿔요. な가 아니에요.<br><span class='gd-pair'><span class='gd-jp'>母が日本人だ</span> → <span class='gd-jp'>母が日本人の友達</span></span>(어머니가 일본인인 친구)<br>「日本人だ友達」도 아니고 「日本人な友達」도 아니에요.</div><div class='gd-sec'>과거나 부정일 때는 바꿀 필요 없이 그대로 이어요.<br><span class='gd-jp'>静かじゃない部屋</span>(조용하지 않은 방)<br><span class='gd-jp'>昔、先生だった人</span>(예전에 선생님이었던 사람)</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'>'○○한 명사'라는 한 덩어리를 큰 명사 하나처럼 문장 안에 넣어 쓸 수 있어요. 정중하게 말하고 싶다면 <b>문장 끝만 です・ます로</b> 하고, 앞부분은 보통형 그대로 두면 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは母が作ったケーキです。</span>(이건 어머니가 만든 케이크예요)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日見た映画はおもしろかったです。</span>(어제 본 영화는 재미있었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で行きたい所はどこですか。</span>(일본에서 가고 싶은 곳은 어디예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くにある店で会いましょう。</span>(역 근처에 있는 가게에서 만나요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・'빌린 책'처럼 연결하는 말이 있다고 느껴서 の를 넣고 싶어지지만: 「借りたの本」은 틀려요. <span class='gd-jp'>借りた本</span>라고 해야 해요.<br>・꾸미는 부분 안에는 ます를 쓰지 마세요. 「買いました本」은 틀려요. <span class='gd-jp'>買った本</span>라고 해야 해요. 정중함은 문장 끝의 です・ます에 맡기세요.<br>・그 부분에서 '누가 했는지'는 <b>が</b>를 써야 하고 は는 쓸 수 없어요. 「私は作った料理」는 틀리고 <span class='gd-jp'>私が作った料理</span>(내가 만든 요리)라고 해야 해요. <span class='gd-jp'>私の作った料理</span>처럼 が가 の로 바뀐 형태도 볼 수 있는데, 뜻은 같아요.<br>・な형용사는 <b>な</b>로(<span class='gd-jp'>静かな部屋</span>), 명사는 <b>の</b>로(<span class='gd-jp'>医者の父</span>, 의사인 아버지) 바꾸니까 섞어 쓰지 마세요.<br>・<span class='gd-jp'>見た映画</span>는 '본', <span class='gd-jp'>見る映画</span>는 '볼, 평소에 보는'이라는 뜻이니 시제를 잘 골라야 해요.</div><div class='gd-h'>비슷하게 생긴 것과 구분하기</div><div class='gd-sec'>같은 책 이야기라도 앞에 어떤 품사가 오느냐에 따라 の를 넣을지 말지가 정해져요.<br><span class='gd-jp'>私の本</span>(내 책): 앞이 명사라서 の를 넣어요<br><span class='gd-jp'>私が買った本</span>(내가 산 책): 앞이 동사라서 그대로 이어요<br><span class='gd-jp'>新しい本</span>(새 책): 앞이 い형용사라서 그대로 이어요</div><div class='gd-warn'>판단 요령: 명사 바로 앞에 있는 말이 명사일 때만 の를 붙이고, 동사나 い형용사라면 그대로 이어요. 한국어의 '-ㄴ/는'에 해당하는 말은 따로 신경 쓰지 않아도 돼요.</div><div class='gd-h'>다 배운 뒤에 이어서 배우면 좋아요</div><div class='gd-sec'>「〜とき」(~할 때)도 똑같은 연결 방식을 써요. <span class='gd-jp'>日本へ行くとき</span>(일본에 갈 때), <span class='gd-jp'>子どものとき</span>(어릴 때).</div>","n5-49":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>「の」는 동작을 <b>「하나의 일」로 묶어 주는</b> 역할을 해요. 한국어의 「사진을 찍<b>는 것</b>」과 같아요. 한국어에서는 「수영하는 것」처럼 동사 뒤에 「-는 것」을 붙이죠? 일본어도 마찬가지로 동사 뒤에 먼저 「の」를 붙여서 「수영하는 것」으로 만들어야, 그 뒤에 <span class='gd-jp'>は</span>, <span class='gd-jp'>が</span>, <span class='gd-jp'>を</span>를 이을 수 있어요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>동사는 <b>보통형</b>(사전에 나오는 기본형이에요. 예: <span class='gd-jp'>泳ぐ</span>, <span class='gd-jp'>撮る</span>. ます를 뗀 <span class='gd-jp'>泳ぎ</span>, <span class='gd-jp'>撮り</span>가 아니에요)에 바로 「の」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぐの</span></span>(수영하는 것)<br><span class='gd-pair'><span class='gd-jp'>写真を撮る</span> → <span class='gd-jp'>写真を撮るの</span></span>(사진을 찍는 것)<br>「어떤 일을 하지 않는 것」은 ない형에 の를 붙여요: <span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないの</span></span>(먹지 않는 것)</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>のが好き・上手</span>어떤 일을 좋아하는지, 잘하는지 말할 때 써요. 뒤에 <span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>上手</span>, <span class='gd-jp'>下手</span>가 오면 「が」를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>小説を読むのが好きです。</span>(저는 소설 읽는 것을 좋아해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>母は料理を作るのが上手です。</span>(어머니는 요리를 아주 잘하세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は歌うのが下手です。</span>(저는 노래를 정말 못 불러요)</div><div class='gd-sec'><span class='gd-tag'>のは＋感想</span>먼저 어떤 일을 말하고, 그 일에 대한 느낌을 이어서 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>写真を撮るのは楽しいです。</span>(사진 찍는 것은 재미있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を話すのは難しいです。</span>(일본어를 말하는 것은 어려워요)</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べないのは体によくないです。</span>(아침을 먹지 않는 것은 몸에 좋지 않아요)</div><div class='gd-sec'><span class='gd-tag'>のを＋動作</span>「그 일」을 동작의 대상으로 삼아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を出すのを忘れました。</span>(숙제를 내는 것을 잊어버렸어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来るのを待っています。</span>(다나카 씨가 오기를 기다리고 있어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・동사를 그대로 넣으면 안 돼요. <span class='gd-jp'>泳ぐが好きです</span>는 틀린 문장이고, <span class='gd-jp'>泳ぐのが好きです</span>라고 해야 해요.<br>・の 앞에는 ます형을 쓸 수 없어요. 「泳ぎますのが好きです」라고 하지 않아요. 정중함은 문장 끝의 <span class='gd-jp'>です</span>만으로 충분해요.<br>・원래 명사인 말에는 の를 또 붙이지 않아요. <span class='gd-jp'>音楽が好きです</span>(저는 음악을 좋아해요)처럼 말하고, 「音楽のが好きです」라고 하면 안 돼요.<br>・<span class='gd-jp'>好き</span>, <span class='gd-jp'>上手</span> 앞에는 「が」를 써요. 한국어 「~하는 것을 좋아해요」의 「을/를」에 이끌려서 「を」를 쓰지 않도록 조심하세요.<br>・<span class='gd-jp'>私の本</span>(내 책)의 「の」와는 달라요. 그건 앞이 명사이고 「의」라는 뜻이고, 여기서는 앞이 동사이고 「~하는 것」이라는 뜻이에요.</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'>「こと」도 동작을 「하나의 일」로 바꿔 줘요. 많은 경우 둘 다 쓸 수 있어요.<br><span class='gd-jp'>本を読むのが好きです。</span>／<span class='gd-jp'>本を読むことが好きです。</span>(둘 다 「책 읽는 것을 좋아해요」라는 뜻이고, こと는 조금 더 격식 있게 들려요)<br><br>하지만 둘 중 하나만 쓸 수 있는 경우도 있어요.<br><b>눈으로 보거나 귀로 들은 장면은 の만 써요</b>: <span class='gd-jp'>田中さんが走っているのを見ました。</span>(다나카 씨가 달리고 있는 것을 봤어요)<br><b>「A는 ~(하는 것)이에요」처럼 문장 끝에 올 때는 こと를 써요</b>: <span class='gd-jp'>私の趣味は写真を撮ることです。</span>(제 취미는 사진 찍기예요) 「撮るのです」라고는 하지 않아요.</div><div class='gd-warn'>판단 요령: 직접 보거나 들은 것은 の, 「~하는 것이에요」처럼 문장 끝에 오면 こと를 써요. 좋아한다거나 재미있다고 말할 때는 둘 다 괜찮지만, 평소 말할 때는 の가 가장 자연스러워요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>「こと」에 익숙해졌다면 다음은 <span class='gd-jp'>〜ことができる</span>＝~할 수 있다예요. <span class='gd-jp'>私は泳ぐことができます。</span>(저는 수영할 수 있어요)</div>","n5-50":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>한국어는 「책상 위에 책이 있어요」, 「방에 고양이가 있어요」처럼 뭐든 「있어요」 하나로 말하죠. 일본어는 한 단계를 더 나눠요. <b>물건과 식물</b>에는 <span class='gd-jp'>あります</span>, <b>사람과 동물</b>에는 <span class='gd-jp'>います</span>를 써요. 그게 살아 있는지, 스스로 움직이는지를 보면 어느 쪽인지 알 수 있어요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>장소＋<span class='gd-jp'>に</span>＋물건이나 사람＋<span class='gd-jp'>が</span>＋<span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span><br><span class='gd-jp'>に</span>는 한국어의 「에」처럼 장소를 나타내고, <span class='gd-jp'>が</span>는 「있는 것이 무엇인지」를 나타내요.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き出しにハサミがあります。</span>(서랍에 가위가 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に生徒がいます。</span>(교실에 학생이 있어요)</div><div class='gd-h'>あります일까 います일까</div><div class='gd-sec'><span class='gd-tag'>あります</span>물건, 식물, 건물에 써요. 나무는 살아 있지만 돌아다니지 않으니까 <span class='gd-jp'>あります</span>를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上に本があります。</span>(책상 위에 책이 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>庭に大きい木があります。</span>(마당에 큰 나무가 있어요)</div><div class='gd-sec'><span class='gd-tag'>います</span>사람과 동물에 써요. 물고기와 벌레도 포함돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋に猫がいます。</span>(방에 고양이가 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>川に魚がいます。</span>(강에 물고기가 있어요)</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>~는 어디에 있어요?</span>어떤 것이 어디에 「있는지」 말하고 싶으면 그것을 앞에 두고 <span class='gd-jp'>は</span>를 붙여요. 장소에는 똑같이 <span class='gd-jp'>に</span>를 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ハサミは引き出しにあります。</span>(가위는 서랍에 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>(화장실은 어디에 있어요?)</div><div class='gd-sec'><span class='gd-tag'>없어요</span>ます를 ません으로 바꿔요: <span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ありません</span></span><span class='gd-pair'><span class='gd-jp'>います</span> → <span class='gd-jp'>いません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>教室に誰もいません。</span>(교실에 아무도 없어요)</div><div class='gd-sec'><span class='gd-tag'>저는 ~가 있어요</span>가족이나 시간처럼 「있다」고 말할 때도 일본어는 이 두 단어를 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>姉が一人います。</span>(저는 누나가 한 명 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、時間がありますか。</span>(내일 시간 있어요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・사람에게는 반드시 <span class='gd-jp'>います</span>를 써요. 「선생님이 계세요」는 <span class='gd-jp'>先生がいます</span>이고, 「先生があります」는 틀려요. 가족도 마찬가지로 <span class='gd-jp'>妹がいます</span>예요.<br>・식물에는 <span class='gd-jp'>あります</span>를 써요. 물고기나 벌레는 아무리 작아도 살아 있으니까 <span class='gd-jp'>います</span>를 써요.<br>・물건, 사람, 동물이 「어딘가에 있다」고 할 때 장소에는 <span class='gd-jp'>に</span>를 써요. <span class='gd-jp'>部屋に猫がいます</span>가 맞고, 部屋で猫がいます는 틀려요.<br>・<b>예외</b>: 「있다」의 대상이 행사나 일(<span class='gd-jp'>テスト</span>, <span class='gd-jp'>パーティー</span>, <span class='gd-jp'>会議</span>…)이면 「그곳에서 열린다」는 뜻이라서 장소에 <span class='gd-jp'>で</span>를 써요. <span class='gd-jp'>あした学校でテストがあります。</span>(내일 학교에서 시험이 있어요)<br>・「아무것도 없다」「아무도 없다」의 <span class='gd-jp'>何も</span>, <span class='gd-jp'>誰も</span> 뒤에는 반드시 부정형인 <span class='gd-jp'>ありません</span>／<span class='gd-jp'>いません</span>이 와요.</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'>같은 공원이라도 뒤에 무엇이 오는지 보세요.<br><b>존재</b>는 <span class='gd-jp'>に</span>: <span class='gd-jp'>公園に犬がいます。</span>(공원에 개가 있어요)<br><b>동작을 할 때</b>는 <span class='gd-jp'>で</span>: <span class='gd-jp'>公園で犬と遊びます。</span>(공원에서 개와 놀아요)<br><b>행사가 열릴 때</b>는 <span class='gd-jp'>で</span>: <span class='gd-jp'>公園でお祭りがあります。</span>(공원에서 축제가 있어요)</div><div class='gd-warn'>판단 요령: 뒤에 <span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span>가 오고 물건, 사람, 동물이 존재한다면 <span class='gd-jp'>に</span>를 써요. 뒤에 동작이 오거나 「있다」의 대상이 행사나 일이라면 <span class='gd-jp'>で</span>를 써요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>수량을 붙여 볼 수 있어요. <span class='gd-jp'>猫が二匹います。</span>(고양이가 두 마리 있어요)<br>그리고 「~하고 있다」를 뜻하는 <span class='gd-jp'>～ています</span>에 들어 있는 <span class='gd-jp'>います</span>가 바로 오늘 배운 그 단어예요.</div>","n5-55":"<div class='gd-h'>한 문장으로 먼저 이해하기</div><div class='gd-sec'>「〜てください」는 한국어의 <b>「~해 주세요」「~하세요」</b>에 해당하고, 「〜ないでください」는 <b>「~하지 마세요」</b>에 해당해요. 친구에게 \"잠깐만 기다려 주세요\"라고 할 때는 <span class='gd-jp'>ちょっと待ってください</span>, 안내문에 \"사진 촬영 금지\"라고 쓸 때는 <span class='gd-jp'>写真を撮らないでください</span>예요. 바로 이 두 가지 문형을 쓴 거예요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>부탁할 때</span>상대에게 어떤 일을 해 달라고 부탁해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう一度言ってください。</span>(다시 한 번 말해 주세요)</div><div class='gd-sec'><span class='gd-tag'>지시, 당부</span>선생님의 수업, 의사의 당부, 순서를 설명할 때 자주 들려요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>(여기에 이름을 써 주세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を毎日飲んでください。</span>(이 약을 매일 드세요)</div><div class='gd-sec'><span class='gd-tag'>하지 말라고 할 때</span>주의를 주거나, 금지하거나, 위로할 때 모두 쓸 수 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>心配しないでください。</span>(걱정하지 마세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室で食べないでください。</span>(교실에서 먹지 마세요)</div><div class='gd-h'>만드는 방법: ~해 주세요</div><div class='gd-sec'>먼저 동사를 <b>て형</b>(「て形」 레슨에서 배운 형태)으로 바꾸고, 뒤에 바로 <span class='gd-jp'>ください</span>를 붙여요.<br><b>1그룹(5단 동사)</b>: 마지막 글자를 보고 바꾸는 방법을 정해요.<br>・う、つ、る로 끝나면 → って：<span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってください</span></span><br>・む、ぶ、ぬ로 끝나면 → んで：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んでください</span></span><br>・く로 끝나면 → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いてください</span></span><br>・ぐ로 끝나면 → いで：<span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いでください</span></span><br>・す로 끝나면 → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話してください</span></span><br>・예외：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ってください</span></span>(行いて가 아니에요)</div><div class='gd-sec'><b>2그룹(1단 동사)</b>: 「る」를 떼고 「て」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてください</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見てください</span></span></div><div class='gd-sec'><b>3그룹(する・来る)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来てください</span>(きてください)</span></div><div class='gd-h'>만드는 방법: ~하지 마세요</div><div class='gd-sec'>먼저 동사를 <b>ない형</b>으로 바꾸고, 뒤에 <span class='gd-jp'>でください</span>를 붙여요.<br><b>1그룹(5단 동사)</b>: 마지막 음을 같은 행의 「あ」단 음으로 바꾸고 ない를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → る를 ら로 바꾸기 → <span class='gd-jp'>撮らない</span> → <span class='gd-jp'>撮らないでください</span></span><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かないでください</span></span><br>う로 끝나는 동사는 「わ」로 바꿔요：<span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わないでください</span></span></div><div class='gd-sec'><b>2그룹(1단 동사)</b>: 「る」를 떼고 ない를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないでください</span></span></div><div class='gd-sec'><b>3그룹(する・来る)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないでください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないでください</span>(こないでください)</span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・「~하지 마세요」는 ない 뒤에 <b>で</b>가 붙어요：<span class='gd-jp'>見ないでください</span>예요. 「見ないてください」가 아니고, 「見ませんでください」라는 말도 없어요.<br>・う로 끝나는 동사의 ない형은 「わ」예요：<span class='gd-jp'>吸わない</span>、<span class='gd-jp'>買わない</span>. 「吸あない」가 아니에요.<br>・来る는 읽는 법이 두 가지예요：<span class='gd-jp'>来てください</span>는 <b>きて</b>, <span class='gd-jp'>来ないでください</span>는 <b>こないで</b>라고 읽어요.<br>・한국어로는 \"~해 주세요\"라고 옮기지만, 사실은 <b>상대에게 행동을 시키는</b> 말이에요. 선생님이나 상사에게 부탁할 때는 <span class='gd-jp'>〜てくださいませんか</span>(~해 주시겠어요?)라고 하는 편이 더 공손해요.<br>・친구 사이에서는 ください를 자주 생략해요：<span class='gd-jp'>ちょっと待って。</span>(잠깐만)<span class='gd-jp'>見ないで。</span>(보지 마)<br>・점원이 손님에게 자주 하는 <span class='gd-jp'>少々お待ちください</span>(잠시만 기다려 주세요)는 훨씬 더 공손한 다른 형태라서 이번 레슨의 て형이 아니에요. 들었을 때 알아볼 수만 있으면 충분해요.</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'><span class='gd-jp'>ください</span> 앞에 <b>물건</b>이 오면 \"~을 주세요\"라는 뜻이고, <b>동사 て형</b>이 오면 \"~해 주세요\"라는 뜻이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>水をください。</span>(물을 주세요)</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲んでください。</span>(물을 마셔 주세요)</div><div class='gd-warn'>구별 요령: 「명사＋をください」는 상대에게 물건을 달라고 하는 말이고, 「て形＋ください」는 상대에게 동작을 부탁하는 말이에요.</div>","n5-57":"<div class='gd-h'>한 문장으로 먼저 이해하기</div><div class='gd-sec'>\"갖고 싶다\"와 \"하고 싶다\"는 한국어에서 둘 다 \"싶다\"로 끝나서 비슷하게 느껴지지만, 일본어는 이 둘을 말 자체로 나눠요. 물건을 원할 때는 <b>「欲しい」</b>, 동작을 하고 싶을 때는 <b>「〜たい」</b>를 써요.</div><div class='gd-h'>만드는 방법</div><div class='gd-sec'><span class='gd-tag'>물건을 원할 때</span>명사＋が欲しいです</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいスマホが欲しいです。</span>(새 스마트폰을 갖고 싶어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日に時計が欲しいです。</span>(생일에 시계를 받고 싶어요)</div><div class='gd-sec'><span class='gd-tag'>동작을 하고 싶을 때</span>먼저 동사를 ます형으로 바꾸고, 「ます」를 떼고, 「たいです」를 붙여요.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → ます 떼기 → <span class='gd-jp'>行きたい</span></span><br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べたい</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見たい</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>したい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来たい</span>(きたい)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行きたいです。</span>(일본에 가고 싶어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>温泉に入りたいです。</span>(온천에 들어가고 싶어요)</div><div class='gd-h'>조사에 주의하세요</div><div class='gd-sec'><span class='gd-jp'>欲しい</span> 앞에는 <b>が</b>를 써요.<br><span class='gd-jp'>〜たい</span>는 원래 「を」를 쓰던 자리에 「を」를 그대로 써도 되고 「が」로 바꿔도 돼요. 둘 다 맞아요.<br><span class='gd-jp'>水を飲みたいです。</span>／<span class='gd-jp'>水が飲みたいです。</span>(물을 마시고 싶어요)<br>다른 조사는 바꿀 수 없고, 원래 쓰던 조사를 그대로 써요：<span class='gd-jp'>友達に会いたいです。</span>(친구를 만나고 싶어요) 여기서 「に」는 が로 바꿀 수 없어요.</div><div class='gd-h'>부정과 과거: い형용사와 똑같이 바뀌어요</div><div class='gd-sec'><span class='gd-jp'>欲しい</span>와 <span class='gd-jp'>〜たい</span>는 둘 다 「い」로 끝나서 い형용사와 똑같이 활용해요.<br><span class='gd-pair'><span class='gd-jp'>欲しいです</span> → <span class='gd-jp'>欲しくないです</span></span>(갖고 싶지 않아요)<span class='gd-pair'><span class='gd-jp'>欲しかったです</span></span>(갖고 싶었어요)<br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたくないです</span></span>(가고 싶지 않아요)<span class='gd-pair'><span class='gd-jp'>行きたかったです</span></span>(가고 싶었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は何もしたくないです。</span>(오늘은 아무것도 하고 싶지 않아요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・たい는 사전형이 아니라 ます형 뒤에 붙어요. 「行くたい」는 틀린 말이고, <span class='gd-jp'>行きたい</span>라고 써야 해요.<br>・たい는 이미 형용사라서 뒤에 ます를 또 붙일 수 없어요. <span class='gd-jp'>行きたいです</span>라고 해야 하고 「行きたいます」는 안 돼요. 부정도 <span class='gd-jp'>行きたくないです</span>라고 해야 하고 「行きたいません」은 안 돼요.<br>・<span class='gd-jp'>来たい</span>는 <b>きたい</b>라고 읽어요.<br>・이 두 표현은 모두 <b>나 자신</b>의 마음을 말할 때 써요. 「田中さんは車が欲しいです」처럼 바로 말하면 일본 사람은 어색하게 느껴요. 다른 사람의 마음을 내가 직접 느낄 수는 없기 때문이에요. 다른 사람 이야기를 할 때는 <span class='gd-jp'>田中さんは車が欲しいと言っていました。</span>(다나카 씨는 차를 갖고 싶다고 했어요)처럼 말할 수 있어요. 상대에게 질문하는 것은 괜찮아요：<span class='gd-jp'>何が欲しいですか。</span>(무엇을 갖고 싶어요?)<br>・선생님, 상사, 손님에게 바로 「〜たいですか」라고 물으면 상대가 뭘 하려는지 캐묻는 느낌이라 별로 예의 바르지 않아요. 상대에게 음료를 권하고 싶다면 <span class='gd-jp'>コーヒーはいかがですか。</span>나 <span class='gd-jp'>コーヒーを飲みませんか。</span>라고 하는 편이 더 적절해요.</div><div class='gd-h'>닮은 표현과 구분하기</div><div class='gd-sec'>같은 커피 한 잔이라도 이렇게 달라요.<br><span class='gd-jp'>コーヒーが欲しいです。</span>(커피를 갖고 싶어요: 원하는 것은 「커피」라는 물건)<br><span class='gd-jp'>コーヒーが飲みたいです。</span>(커피를 마시고 싶어요: 하고 싶은 것은 「마시다」라는 동작)<br>한국어에서는 \"싶다\"를 두 경우에 다 쓰다 보니, \"일본에 가고 싶어요\"를 그대로 欲しい로 옮기려는 실수가 나오기 쉬워요. 하고 싶은 것은 「가다」라는 동작이니까 <span class='gd-jp'>日本へ行きたいです。</span>라고 해야 하고, 欲しい는 쓸 수 없어요.</div><div class='gd-warn'>구별 요령: 한국어 \"싶다\" 앞을 보세요. \"갖고 싶다\"처럼 <b>명사</b>(스마트폰, 커피)를 원하면 欲しい를 쓰고, \"가고, 먹고, 보고\"처럼 <b>동사</b>를 하고 싶으면 たい를 써요.</div><div class='gd-h'>다 배운 뒤에 이어서 배울 것</div><div class='gd-sec'>「に(목적)」와 함께 쓸 수도 있어요：<span class='gd-jp'>映画を見に行きたいです。</span>(영화를 보러 가고 싶어요) 나중에는 다른 사람이 원하는 것을 말하는 표현도 배울 거예요：<span class='gd-jp'>欲しがっている</span>、<span class='gd-jp'>〜たがっている</span>.</div>","n5-52":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>「〜ています」는 한국어의 <b>「~고 있다」「~아/어 있다」「이미 ~했다(지금도 그 상태)」「요즘 계속 ~하고 있다」</b>에 가까워요. 핵심은 한 시점이 아니라 <b>이어지는 상태</b>를 말한다는 점이에요. 동작이 진행 중이거나, 결과가 남아 있거나, 요즘 계속 하고 있다는 뜻이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>먼저 동사를 て형으로 바꾸고 뒤에 <b>います</b>를 붙이면 돼요. て형 변화는 「て형」 수업에서 복습하세요.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べています</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでいます</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しています</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span> → <span class='gd-jp'>来ています</span>（きています）</span></div><div class='gd-h'>세 가지 뜻</div><div class='gd-sec'><span class='gd-tag'>하는 중</span>지금 이 순간 동작이 진행 중이라는 뜻이에요. 「今」와 자주 같이 나와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、洗濯しています。</span>（지금 빨래하고 있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はテレビを見ています。</span>（남동생은 TV를 보고 있어요）</div><div class='gd-sec'><span class='gd-tag'>결과가 남아 있음</span>어떤 동작은 <b>순식간에 끝나요</b>. 예를 들면 결혼하다, (문·창문이) 열리다(<span class='gd-jp'>開く</span>), 이사해서 살다 같은 동작이에요. 이런 동사에 ています를 붙이면 「~하는 중」이 아니라 「끝났고, 지금도 그 상태」라는 뜻이 돼요. 사물의 현재 상태를 말할 때는 <span class='gd-jp'>開く</span> 같은 자동사를 써요. <span class='gd-jp'>窓が開いています</span>라고 하고, <span class='gd-jp'>窓を開けています</span>라고 하면 안 돼요(「누군가 창문을 열고 있는 중」처럼 들려요).</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いています。</span>（창문이 열려 있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に住んでいます。</span>（교토에 살고 있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚しています。</span>（우리 언니는 결혼한 상태예요）</div><div class='gd-sec'><span class='gd-tag'>요즘 계속 하는 일</span>최근, 요즘 한동안 계속하고 있는 일이에요. 일, 근황, 최근 생긴 습관 같은 것들이 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝走っています。</span>（저는 매일 아침 달리고 있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は銀行で働いています。</span>（저희 아버지는 은행에서 일하세요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>結婚しています</span>는 「기혼」이라는 뜻이지, 「결혼식을 하는 중」이 아니에요. 마찬가지로 <span class='gd-jp'>住んでいます</span>는 「살고 있다」예요. 지금 사는 곳을 말할 때는 반드시 이걸 써요. <span class='gd-jp'>京都に住みます</span>는 오히려 「(앞으로) 교토에 살 거예요」가 돼요.<br>・「알고 있다」는 <span class='gd-jp'>知っています</span>인데, 「모른다」는 <span class='gd-jp'>知りません</span>이에요. 知っていません이라고 하지 않아요.<br>・<span class='gd-jp'>もう食べましたか</span>라고 물으면 「아직요」는 <span class='gd-jp'>まだ食べていません</span>이에요. まだ食べませんでした라고 하면 안 돼요.<br>・<span class='gd-jp'>来ています</span>의 来는 <b>き</b>로 읽어요.<br>・친구 사이에서는 い를 자주 빼서 <span class='gd-jp'>食べています</span>를 <span class='gd-jp'>食べてる</span>라고 해요. 들어도 당황하지 마세요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><b>ます</b>와 <b>ています</b>가 가장 자주 헷갈려요. 같은 동작으로 차이를 볼게요.<br><span class='gd-jp'>本を読みます。</span>（책을 읽어요: 평소 습관이거나, 잠시 후에 읽을 거예요）<br><span class='gd-jp'>本を読んでいます。</span>（책을 읽고 있어요）<br><br><span class='gd-jp'>来月結婚します。</span>（다음 달에 결혼해요）<br><span class='gd-jp'>もう結婚しています。</span>（이미 결혼했어요）<br><br>둘 다 습관을 말할 수 있지만 느낌이 달라요.<br><span class='gd-jp'>毎日コーヒーを飲みます。</span>（매일 커피를 마셔요: 일반적인 습관, 사실）<br><span class='gd-jp'>最近、毎朝走っています。</span>（요즘 매일 아침 달리고 있어요: 요즘 계속 하는 중）</div><div class='gd-warn'>판단 요령: 지금 이 순간 하는 중이거나, 이미 ~했다/~아 있다, 또는 「요즘·지금 계속 하고 있다」를 말할 때는 ています를 써요. 일반적인 습관이나 앞으로 할 일은 ます를 써요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>「자동사・타동사」를 배우면 <span class='gd-jp'>ドアが閉まっています</span>(문이 닫혀 있어요)처럼 「결과가 남아 있다」는 표현을 자주 보게 될 거예요. 그때 비교해 보면 더 확실하게 이해돼요.</div>","n5-53":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>한국어는 여러 일을 말할 때 「아침에 일어나서 이를 닦고 나가요」처럼 「~아/어서」「~고」로 이어서 말하면 돼요. 일본어는 앞의 동사를 <b>て형</b>으로 바꿔서 「…하고/해서…」처럼 이어요. 현재인지 과거인지, 정중한지 아닌지는 <b>마지막 동사</b>가 정해요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><b>동사</b>: て형을 그대로 써요(변화 방법은 「て형」 수업을 보세요).<br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span></div><div class='gd-sec'><b>い형용사</b>: 끝의 「い」를 「くて」로 바꿔요.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → い를 くて로 → <span class='gd-jp'>安くて</span></span><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくて</span></span>(이 예외는 외워야 해요)</div><div class='gd-sec'><b>な형용사, 명사</b>: 뒤에 「で」를 바로 붙여요.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かで</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生で</span></span></div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>순서대로 말하기</span>한 가지를 끝내고 다음 일을 할 때, 일어난 순서대로 말해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、歯を磨いて、出かけます。</span>（아침에 일어나서 이를 닦고 나가요）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は家に帰って、すぐ寝ました。</span>（어제는 집에 돌아와서 바로 잤어요）</div><div class='gd-sec'><span class='gd-tag'>여러 특징 말하기</span>사람이나 물건을 설명할 때 특징 두 가지를 한꺼번에 말해요. 한국어의 「~고」와 비슷해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くて、おいしいです。</span>（이 가게는 싸고 맛있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は台湾人で、大学生です。</span>（저는 대만 사람이고 대학생이에요）</div><div class='gd-sec'><span class='gd-tag'>방법</span>앞의 동작이 뒤에 오는 일의 「방법」이나 「모습」이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>歩いて駅へ行きます。</span>（걸어서 역에 가요）</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持って出かけます。</span>（우산을 들고 나가요）</div><div class='gd-sec'><span class='gd-tag'>원인</span>앞이 원인이고, 뒤에는 대개 감정이나 상태, 또는 「~할 수 없다」가 와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ニュースを聞いて、びっくりしました。</span>（뉴스를 듣고 깜짝 놀랐어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>頭が痛くて、何もできませんでした。</span>（머리가 아파서 아무것도 못 했어요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・시제와 정중함은 <b>마지막 동사만</b> 봐요. <span class='gd-jp'>昨日、デパートへ行って、靴を買いました。</span>（어제 백화점에 가서 신발을 샀어요） 앞의 <span class='gd-jp'>行って</span>는 과거로 바꿀 필요가 없어요. 「과거」는 마지막의 <span class='gd-jp'>買いました</span>가 맡아요.<br>・い형용사는 <span class='gd-jp'>安くて</span>이지 「安いて」가 아니에요. <span class='gd-jp'>いい</span>는 <span class='gd-jp'>よくて</span>로 바꿔요. な형용사는 <span class='gd-jp'>静かで</span>이지 「静かくて」가 아니에요.<br>・특징 두 가지를 이어 말할 때는 방향이 같은 게 좋아요(둘 다 장점이거나 둘 다 단점). 「싸지만 맛이 없다」처럼 하나는 좋고 하나는 나쁜 경우에는 <span class='gd-jp'>が</span>를 써요. <span class='gd-jp'>この店は安いですが、おいしくないです。</span>（이 가게는 싸지만 맛이 없어요）<br>・원인을 나타내는 て 뒤에는 「~해요(권유)」「~해 주세요」「~하고 싶어요」를 <b>쓸 수 없어요</b>. 「비가 오니까 택시로 가요」라고 하고 싶으면 <span class='gd-jp'>から</span>를 써요. <span class='gd-jp'>雨が降っているから、タクシーで行きましょう。</span></div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>같은 주말 이야기라도 이렇게 달라요.<br><span class='gd-jp'>映画を見て、ご飯を食べました。</span>（영화를 보고 밥을 먹었어요: 순서대로 이야기해요）<br><span class='gd-jp'>映画を見てから、ご飯を食べました。</span>（영화를 본 <b>뒤에야</b> 밥을 먹었어요: 앞뒤 순서를 특히 강조해요）<br><span class='gd-jp'>映画を見たり、ご飯を食べたりしました。</span>（영화를 보기도 하고 밥을 먹기도 했어요: 예를 든 것뿐이라 순서는 중요하지 않고, 다른 것도 했을 수 있어요）</div><div class='gd-warn'>판단 요령: 순서대로 하나씩 말할 때는 「て」, 「A를 끝낸 뒤에 B」를 강조할 때는 「てから」, 몇 가지를 예로 들 때는 「たり～たり」를 써요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>て형 뒤에는 자주 쓰는 문형이 많이 이어져요. 예를 들어 「~해 주세요」는 <span class='gd-jp'>ちょっと待ってください。</span>(잠시만 기다려 주세요), 「~하고 있어요」는 <span class='gd-jp'>今、ご飯を食べています。</span>(지금 밥을 먹고 있어요)처럼 써요.</div>","n5-59":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「〜とき」는 한국어의 <b>「~할 때」</b>와 같아요. 앞에 나오는 말 전체가 「とき」를 꾸며 주는 구조도 한국어와 비슷해요. 예를 들면 <span class='gd-jp'>暇なとき</span>(한가할 때), <span class='gd-jp'>子どものとき</span>(어릴 때)처럼요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>「とき」는 명사예요. 그래서 앞에 붙는 형태는 명사를 꾸밀 때의 접속과 똑같아요.<br><b>동사</b>: 그대로 접속해요<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとき</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないとき</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったとき</span></span><br><b>い형용사</b>: 그대로 접속해요<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいとき</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いとき</span></span><br><b>な형용사</b>: 「な」를 붙여요<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇なとき</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なとき</span></span><br><b>명사</b>: 「の」를 붙여요<br><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものとき</span></span><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのとき</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>暇なとき、何をしますか。</span>(한가할 때 뭐 해요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、よくこの公園で遊びました。</span>(어릴 때 이 공원에서 자주 놀았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないとき、先生に聞きます。</span>(모를 때는 선생님께 물어봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないとき、コンビニでご飯を買います。</span>(시간이 없을 때는 편의점에서 밥을 사요)</div><div class='gd-h'>가장 중요한 포인트: 行くとき와 行ったとき</div><div class='gd-sec'>「とき」 앞의 동사를 원형으로 쓸지 た형으로 쓸지는 <b>문장 전체가 현재냐 과거냐로 정하는 게 아니에요.</b> 그 시점에 동작이 <b>끝났는지 아닌지</b>로 정해요.<br><span class='gd-tag'>사전형＋とき</span>동작이 아직 끝나지 않았어요. 막 하려는 중이거나 하는 도중이에요.<br><span class='gd-tag'>た형＋とき</span>동작이 이미 끝났어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるとき、「いってきます」と言います。</span>(나갈 때 「다녀오겠습니다」라고 말해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったとき、「ただいま」と言います。</span>(집에 돌아왔을 때 「다녀왔습니다」라고 말해요)</div><div class='gd-sec'>한 쌍을 더 볼게요. 두 문장 모두 끝이 과거형인데 뜻은 꽤 달라요.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行くとき、辞書を買いました。</span>(일본에 갈 때 사전을 샀어요: 출발 전이나 가는 길에 샀어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行ったとき、辞書を買いました。</span>(일본에 갔을 때 사전을 샀어요: 일본에 도착해서 샀어요)</div><div class='gd-sec'>첫 번째 문장은 분명 지난 일인데도 앞에는 <span class='gd-jp'>行く</span>를 써요. 사전을 산 그 순간에는 아직 일본에 도착하지 않았기 때문이에요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・명사에는 の를 붙여요: <span class='gd-jp'>子どものとき</span>가 맞고, 子どもとき는 틀려요.<br>・な형용사에는 な를 붙이고, だ는 쓸 수 없어요: <span class='gd-jp'>暇なとき</span>가 맞고, 暇とき도 暇だとき도 틀려요. 과거일 때만 <span class='gd-jp'>暇だったとき</span>라고 할 수 있어요.<br>・동사와 い형용사 뒤에는 の를 <b>붙이지 않아요</b>. 명사에 の를 붙이는 습관 때문에 「行くのとき」라고 말하는 학습자가 많은데, 이건 틀린 표현이에요.<br>・「とき」 앞에는 ます나 です를 쓰지 않아요. <span class='gd-jp'>行くとき、〜ます</span>라고 하면 충분히 정중해요. 「行きますとき」라고 하면 안 돼요. 정중함은 문장 맨 끝에서 정해요.<br>・습관이나 조건을 말할 때는 は를 붙여서 「ときは」로 자주 말해요. <span class='gd-jp'>寒いときは、温かいお茶を飲みます。</span>(추울 때는 따뜻한 차를 마셔요)처럼요. 아주 자연스럽게 들려요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'>이미 배운 <span class='gd-jp'>〜まえに</span>, <span class='gd-jp'>〜たあとで</span>도 시간과 관련이 있어서 「とき」와 헷갈리기 쉬워요.<br><b>とき</b>＝바로 그때, 그 과정 중이에요: <span class='gd-jp'>家に帰るとき、パンを買いました。</span>(집에 가는 길에 빵을 샀어요)<br><b>まえに</b>＝「그 전에」라는 뜻만 있어서 얼마나 전이든 괜찮아요: <span class='gd-jp'>家に帰るまえに、パンを買いました。</span>(집에 가기 전에 빵을 샀어요)<br><b>たとき</b>＝동작이 끝난 그 시점이에요: <span class='gd-jp'>家に帰ったとき、母はいませんでした。</span>(집에 돌아왔을 때 엄마는 안 계셨어요)<br><b>たあとで</b>＝끝난 뒤에 다음 일을 해요: <span class='gd-jp'>家に帰ったあとで、宿題をしました。</span>(집에 돌아온 뒤에 숙제를 했어요)</div><div class='gd-warn'>구별 요령: 「바로 그때」를 말하고 싶으면 とき, 「앞뒤 순서」를 말하고 싶으면 まえに나 あとで를 써요.</div><div class='gd-h'>다음에 배울 것</div><div class='gd-sec'>「とき」 앞의 동작이 「이미 끝났을 때」라는 뜻이면 た형을 쓰니까, <span class='gd-jp'>た형</span>의 활용에 먼저 익숙해져야 해요. N4에서 <span class='gd-jp'>〜たら</span>(~하면, ~한 뒤에)를 배우면 「とき」와 자주 비교하게 될 거예요.</div>","n5-60":"<div class='gd-h'>한 줄로 이해하기</div><div class='gd-sec'>「〜でしょう」는 한국어의 「~겠죠」, 「~일 거예요」와 비슷해요. 억양을 내리면 스스로 추측하는 말이 돼요. 「내일은 아마 비가 오겠죠」처럼요. 억양을 올리면 상대에게 확인하는 말이 돼요. 「맛있죠?」처럼요. 같은 표현인데 <b>억양에 따라 두 가지 뜻</b>으로 나뉘어요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>추측(억양↓)</span>100% 확신하지는 않고 혼자 짐작할 때 써요. <span class='gd-jp'>たぶん</span>(아마)과 자주 같이 쓰고, 일기예보에서도 많이 나와요.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はたぶん雨でしょう。</span>(내일은 아마 비가 오겠죠)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったでしょう。</span>(다나카 씨는 벌써 돌아갔을 거예요)</div><div class='gd-sec'><span class='gd-tag'>확인(억양↑)</span>상대도 같은 생각일 거라고 여기고 물어보면서 고개를 끄덕여 주길 기다릴 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいでしょう？</span>(이 케이크 맛있죠?)</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょう？</span>(봐요, 제가 말했잖아요?)</div><div class='gd-h'>접속 방법</div><div class='gd-sec'><b>동사, い형용사</b>: 그대로 뒤에 붙여요. 부정형, 과거형도 그대로 붙여요.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いでしょう</span></span><span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないでしょう</span></span></div><div class='gd-sec'><b>な형용사, 명사</b>: 「だ」를 먼저 떼고 붙여요.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ를 떼요 → <span class='gd-jp'>静かでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨でしょう</span></span><br>과거의 「だった」는 그대로 둬요: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったでしょう</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・명사, な형용사 뒤에는 「だ」를 남기면 안 돼요: <span class='gd-jp'>学生でしょう</span>가 맞고, 「学生だでしょう」는 틀려요.<br>・앞에 です를 또 넣지 마세요: <span class='gd-jp'>寒いでしょう</span>면 충분하고, 「寒いですでしょう」라고 하면 안 돼요. でしょう 자체가 です의 「추측형」이라서 이미 정중해요.<br>・<b>자신이 할 계획</b>을 말할 때는 쓸 수 없어요. 「私は明日行くでしょう」는 매우 어색해요. 자기 계획은 그냥 <span class='gd-jp'>明日行きます</span>라고 해요.<br>・확인할 때 쓰는 「でしょう？」에는 「당연히 알고 있죠?」라는 뉘앙스가 있어서, 선생님이나 상사에게 쓰면 조금 무례하게 들려요. 윗사람에게 정중하게 물을 때는 <span class='gd-jp'>〜でしょうか</span>(~일까요?)를 써요. 예를 들면 <span class='gd-jp'>駅はどこでしょうか。</span>(역이 어디일까요?)처럼요.<br>・친구끼리 확인할 때는 <span class='gd-jp'>でしょ？</span>로 줄여서 자주 말해요. 들어도 놀라지 마세요. 뜻은 같아요.</div><div class='gd-h'>비슷한 표현과 구별하기</div><div class='gd-sec'><b>ましょう</b>와 <b>でしょう</b>는 끝이 둘 다 「しょう」지만 뜻이 완전히 달라요.<br>・<span class='gd-jp'>一緒に行きましょう。</span>(같이 가요: 권유)<br>・<span class='gd-jp'>田中さんも行くでしょう。</span>(다나카 씨도 아마 갈 거예요: 추측)<br>접속도 달라요. ましょう는 ます형 뒤에 붙고(<span class='gd-jp'>行き</span>＋ましょう), でしょう는 사전형 같은 보통형 뒤에 붙어요(<span class='gd-jp'>行く</span>＋でしょう).</div><div class='gd-sec'><b>でしょう？</b>와 <b>ね</b>는 둘 다 「~죠」로 옮길 수 있는데, 상대도 같이 느끼고 있는지가 달라요.<br>・두 사람이 함께 밖을 걷고 있을 때: <span class='gd-jp'>寒いですね。</span>(춥네요: 지금 함께 느끼고 있어서 자연스럽게 맞장구를 쳐요)<br>・친구가 방금 밖에서 들어왔고, 당신은 집 안에서 물을 때: <span class='gd-jp'>外、寒いでしょう？</span>(밖은 춥죠?: 당신은 밖에 있지 않았고, 상대가 춥다고 느꼈을 거라 짐작해서 인정을 구해요)</div><div class='gd-warn'>구별 요령: 「같이 ~해요」는 ましょう, 「아마 ~일 거예요」「~죠?」는 でしょう, 두 사람이 지금 같이 느끼면서 맞장구만 칠 때는 ね를 써요.</div><div class='gd-h'>다음에 배울 것</div><div class='gd-sec'>확신이 더 낮은 「~일지도 몰라요」를 말하고 싶으면 <span class='gd-jp'>〜かもしれません</span>을 쓸 수 있어요: <span class='gd-jp'>明日は雨かもしれません。</span>(내일은 비가 올지도 몰라요)</div>","n5-61":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'>「〜からです」는 한국어의 <b>「～기 때문이에요」</b>예요. 상대가 <span class='gd-jp'>どうして</span>(왜)라고 물으면, 이유만 말하고 뒤에 「からです」를 붙여서 대답하면 돼요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>왜냐는 질문에 대답할 때</span>상대가 먼저 '왜'냐고 물으면 이유만 대답해요. 앞에서 있었던 일을 다시 말할 필요는 없어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして休んだんですか。</span>(왜 쉬었어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったからです。</span>(열이 났기 때문이에요)</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして日本語を勉強しているんですか。</span>(왜 일본어를 공부하고 있어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本のアニメが好きだからです。</span>(일본 애니메이션을 좋아하기 때문이에요)</div><div class='gd-sec'><span class='gd-tag'>스스로 이유를 덧붙일 때</span>먼저 한 가지를 말하고, 다음 문장에서 이유를 덧붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はパーティーに行きません。忙しいからです。</span>(오늘은 파티에 안 가요. 바쁘기 때문이에요)</div><div class='gd-h'>어떻게 붙일까요</div><div class='gd-sec'>「から」 앞에는 <b>ます도 です도 없는 형태</b>(친구와 말할 때 쓰는 보통형)를 쓰고, 정중함은 마지막의 「です」가 맡아요.<br><b>동사</b>: 그대로 붙여요.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くからです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったからです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないからです</span></span><br><b>い형용사</b>: 그대로 붙여요.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いからです</span></span><br><b>な형용사, 명사</b>: 사이에 「だ」를 먼저 넣어요.<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きだからです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だからです</span></span></div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・な형용사와 명사에 「だ」를 빼먹는 경우: <span class='gd-jp'>好きからです</span>, <span class='gd-jp'>雨からです</span>는 모두 틀려요. <span class='gd-jp'>好きだからです</span>, <span class='gd-jp'>雨だからです</span>라고 해야 해요.<br>・반대로 い형용사에는 「だ」를 붙이면 <b>안 돼요</b>. <span class='gd-jp'>高いからです</span>라고 하고, 高いだからです라고 하면 안 돼요.<br>・「から」 앞에 ます를 넣지 마세요. <span class='gd-jp'>熱がありましたからです</span>는 틀리고, <span class='gd-jp'>熱があったからです</span>라고 해야 해요.<br>・한국어의 「～니까」「～기 때문에」처럼 일본어의 「から」도 이유의 <b>뒤</b>에 붙어요. '왜냐하면'처럼 앞에 두고 から熱があった처럼 말하면 안 돼요.<br>・친구와 말할 때는 です만 빼면 돼요. <span class='gd-jp'>熱があったから。</span>(열이 났으니까)</div><div class='gd-h'>비슷하게 생긴 표현과 구분해요</div><div class='gd-sec'>이미 조사 「から」(원인・이유)를 배웠죠? 「からです」와 뜻은 같고, 차이는 <b>문장을 배열하는 방식</b>이에요. 같은 내용을 비교해 볼게요.<br><span class='gd-tag'>〜から、〜</span>원인이 앞, 결과가 뒤에 와서 한 문장으로 끝나요.</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったから、休みました。</span>(열이 나서 쉬었어요)</div><div class='gd-sec'><span class='gd-tag'>〜からです</span>결과를 먼저 말하고 원인은 다른 문장으로 덧붙여요. 또는 '왜'냐는 질문을 받았을 때 원인만 대답해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みました。熱があったからです。</span>(쉬었어요. 열이 났기 때문이에요)</div><div class='gd-warn'>판단 팁: 원인 뒤에 '그래서 어떻게 했다'가 이어지면 「〜から、」를 쓰고, 원인이 문장의 끝이면 「〜からです」를 써요.</div><div class='gd-h'>다 익히고 나서 배우면 좋은 표현</div><div class='gd-sec'>결과를 앞에 두고 「のは」를 붙이면 이유를 더 분명하게 말할 수 있어요: <span class='gd-jp'>昨日休んだのは、熱があったからです。</span>(어제 쉰 건 열이 났기 때문이에요)</div>","n5-63":"<div class='gd-h'>한 문장으로 먼저 이해해요</div><div class='gd-sec'>의문사는 질문할 때 쓰는 말로, 한국어의 「무엇, 누구, 어디, 언제, 어느 것, 얼마, 어때요」에 해당해요. 쓰는 법도 한국어와 아주 비슷해요. <b>묻고 싶은 자리에 의문사를 넣고 문장 끝에 か를 붙이면</b> 돼요. 또 의문사 뒤에 「も」나 「か」를 붙이면 뜻이 완전히 달라지는데, 이게 이번 과의 핵심이에요.</div><div class='gd-h'>가장 자주 쓰는 일곱 개부터 알아봐요</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何ですか。</span>(이건 뭐예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は誰ですか。</span>(저 사람은 누구예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>(화장실은 어디예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日はいつですか。</span>(생일이 언제예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どれがいいですか。</span>(어느 것이 좋아요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>これはいくらですか。</span>(이건 얼마예요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本はどうでしたか。</span>(일본은 어땠어요?)</div><div class='gd-sec'>손님이나 윗사람에게 더 정중하게 말할 때는 <span class='gd-jp'>誰</span>를 <span class='gd-jp'>どなた</span>로, <span class='gd-jp'>どう</span>를 <span class='gd-jp'>いかが</span>로 바꿀 수 있어요. 점원이 자주 <span class='gd-jp'>コーヒーはいかがですか。</span>(커피 한잔 어떠세요?)라고 말해요.</div><div class='gd-h'>「何」는 なに일까요, なん일까요</div><div class='gd-sec'><span class='gd-jp'>です</span>, <span class='gd-jp'>の</span>가 뒤에 오거나 「～시, ～명」 같은 단위가 뒤에 오면 <b>なん</b>으로 읽어요: <span class='gd-jp'>何ですか</span>, <span class='gd-jp'>何の本</span>, <span class='gd-jp'>何時</span>, <span class='gd-jp'>何人</span>, <span class='gd-jp'>何曜日</span>.<br><span class='gd-jp'>を</span>, <span class='gd-jp'>が</span>, <span class='gd-jp'>も</span>, <span class='gd-jp'>か</span>가 뒤에 오면 <b>なに</b>으로 읽어요: <span class='gd-jp'>何を食べますか</span>, <span class='gd-jp'>何も</span>, <span class='gd-jp'>何か</span>.</div><div class='gd-h'>「も」를 붙이면: 전부 아니에요</div><div class='gd-sec'><span class='gd-tag'>의문사＋も＋부정</span>「아무것도 ~않다, 아무도 ~않다, 어디에도 ~않다」라는 뜻이 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>何も飲みませんでした。</span>(아무것도 마시지 않았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も来ませんでした。</span>(아무도 오지 않았어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日はどこへも行きませんでした。</span>(일요일에는 아무 데도 가지 않았어요)</div><div class='gd-sec'>조사에 주의하세요. 원래 있던 <span class='gd-jp'>を</span>, <span class='gd-jp'>が</span>는 も로 바뀌지만(<span class='gd-pair'><span class='gd-jp'>何を</span> → <span class='gd-jp'>何も</span></span>), <span class='gd-jp'>へ</span>, <span class='gd-jp'>に</span>는 그대로 남기고 も 앞에 둬요: <span class='gd-jp'>どこへも</span>, <span class='gd-jp'>どこにも</span>, <span class='gd-jp'>誰にも</span>.</div><div class='gd-h'>「か」를 붙이면: 어떤 ~, 불확실해요</div><div class='gd-sec'><span class='gd-tag'>의문사＋か</span>「어떤 것, 누군가, 어딘가, 언젠가」라는 뜻이 돼요. 있기는 한데 정확히 무엇인지는 말할 수 없을 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>何か食べたいです。</span>(뭔가 먹고 싶어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰かいますか。</span>(누구 있어요?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこか静かな場所へ行きたいです。</span>(어딘가 조용한 곳에 가고 싶어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつか日本に住みたいです。</span>(언젠가 일본에 살고 싶어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・의문사가 주어일 때는 뒤에 <b>が</b>를 쓰고 は는 쓰지 않아요: <span class='gd-jp'>誰が来ましたか。</span>라고 하고, 誰は来ましたか라고 하면 안 돼요.<br>・<span class='gd-jp'>いつも</span>는 「언제도 ~않다」가 아니라 「항상」이라는 뜻이에요. 뒤에 긍정도 부정도 올 수 있어요: <span class='gd-jp'>いつも朝ご飯を食べます。</span>(항상 아침을 먹어요) / <span class='gd-jp'>いつも朝ご飯を食べません。</span>(항상 아침을 안 먹어요)<br>・<span class='gd-jp'>何も</span>는 なにも로 읽고, なんも가 아니에요.<br>・<span class='gd-jp'>どれ</span>는 셋 이상 중에서 하나를 고를 때 쓰고, 둘 중에서 고를 때는 <span class='gd-jp'>どちら</span>를 써요.</div><div class='gd-h'>비슷하게 생긴 표현과 구분해요</div><div class='gd-sec'>친구에게 뭘 마셨는지 물을 때도, 한 글자만 달라지면 뜻이 달라져요.<br><b>何を</b>＝'무엇'인지 묻는 거라서 상대가 물건으로 대답해요: <span class='gd-jp'>何を飲みましたか。</span>(뭘 마셨어요?) → <span class='gd-jp'>お茶です。</span><br><b>何か</b>＝'있는지 없는지' 묻는 거라서 상대가 먼저 はい・いいえ로 대답해요: <span class='gd-jp'>何か飲みましたか。</span>(뭔가 마셨어요?) → <span class='gd-jp'>はい、お茶を飲みました。</span><br><b>何も</b>＋부정＝'아무것도 없다': <span class='gd-jp'>いいえ、何も飲みませんでした。</span>(아니요, 아무것도 안 마셨어요)</div><div class='gd-warn'>판단 팁: '무엇인지' 알고 싶으면 何を, '있는지 없는지' 알고 싶으면 何か, '전부 없다'고 말하고 싶으면 何も＋부정을 써요.</div><div class='gd-h'>다 익히고 나서 배우면 좋은 표현</div><div class='gd-sec'>'이것, 그것, 어느 것'을 한 세트로 외우면 더 편해요. 이어서 지시어(こそあど)를 배워 보세요: <span class='gd-jp'>どの本ですか。</span>(어느 책이에요?)</div>","n5-64":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>일본어의 こそあど는 한국어의 '이·그·저·어느'와 거의 같은 구조예요. <b>こ</b>＝이(나와 가까운 것), <b>そ</b>＝그(상대방과 가까운 것), <b>あ</b>＝저(우리 둘 다 먼 것), <b>ど</b>＝어느예요. 먼저 「こそあど」 네 개의 첫소리를 기억해 두고 뒤에 다른 꼬리를 붙이면, 물건도 장소도 방향도 가리킬 수 있어요.</div><div class='gd-h'>장면으로 떠올려 보기</div><div class='gd-sec'>친구와 길가에 서 있어요. 내 손에는 휴대폰이, 친구 손에는 커피 한 잔이 있고, 건너편 먼 곳에는 큰 건물이 한 채 있어요.<br>휴대폰은 내 쪽에 있으니 <b>こ</b>를 써요. 커피는 친구 쪽에 있으니 <b>そ</b>를 써요. 건물은 둘 다에게 멀어서 <b>あ</b>를 써요. 어느 것인지 모를 때는 <b>ど</b>를 써요.</div><div class='gd-h'>네 그룹 한눈에 보기</div><div class='gd-sec'><span class='gd-tag'>물건 가리키기</span><span class='gd-jp'>これ・それ・あれ・どれ</span><br>이 말들은 혼자서 주인공이 될 수 있어서 뒤에 바로 「は」「が」를 붙여요.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>（이건 제 우산이에요）</div><div class='gd-ex-line'>・<span class='gd-jp'>それ、何ですか。</span>（그거 뭐예요? 상대방 손에 있는 것）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれは東京タワーです。</span>（저건 도쿄타워예요）</div><div class='gd-sec'><span class='gd-tag'>뒤에 명사가 와요</span><span class='gd-jp'>この・その・あの・どの</span><br>이 말들은 혼자 쓸 수 없고, 뒤에 반드시 명사가 와야 해요. 한국어의 '이 책, 그 가방, 저 사람'과 같아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、おもしろいですよ。</span>（이 책 재미있어요）</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、かわいいですね。</span>（그 가방 귀엽네요）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人はだれですか。</span>（저 사람은 누구예요?）</div><div class='gd-sec'><span class='gd-tag'>장소 가리키기</span><span class='gd-jp'>ここ・そこ・あそこ・どこ</span></div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>（화장실은 어디예요?）</div><div class='gd-ex-line'>・<span class='gd-jp'>あそこにコンビニがあります。</span>（저기에 편의점이 있어요）</div><div class='gd-sec'><span class='gd-tag'>공손한 표현</span><span class='gd-jp'>こちら・そちら・あちら・どちら</span><br>방향이나 장소를 가리킬 수 있고, 사람을 정중하게 소개할 때도 써요. 점원이나 안내 직원이 자주 쓰는 말이에요. 친구와 이야기할 때는 <span class='gd-jp'>こっち・そっち・あっち・どっち</span>가 돼요.</div><div class='gd-ex-line'>・<span class='gd-jp'>受付はあちらです。</span>（접수처는 저쪽이에요）</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらは田中さんです。</span>（이분은 다나카 씨예요）</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>この・その・あの・どの</span>는 단독으로 쓸 수 없어요. '이건 제 거예요'는 <span class='gd-jp'>これは私のです</span>라고 해야 하고, このは私のです는 틀린 말이에요.<br>・장소의 '저기'는 <b>あそこ</b>이고 あこ가 아니에요. 같은 그룹의 다른 말들과 생김새가 달라서 따로 외워야 해요.<br>・한국어는 '그'와 '저'를 나누니까 감각은 비슷해요. 물건이 상대방 곁이나 손에 있으면 <b>それ</b>, 두 사람 모두에게 멀 때만 <b>あれ</b>를 써요.<br>・서 있는 위치가 다르면 쓰는 말도 바뀌어요. 상대가 자기 손의 물건을 가리키며 <span class='gd-jp'>これは何ですか</span>라고 물으면, 대답할 때는 <span class='gd-jp'>それは～です</span>라고 해요. 그 물건이 상대 쪽에 있기 때문이에요.<br>・상대방이 방금 말한 내용도 「そ」로 시작하는 말로 가리켜요. 한국어의 '그거 좋네요'와 같아요: <span class='gd-jp'>それ、いいですね。</span>（그거 좋네요）<br>・사람을 소개할 때는 <span class='gd-jp'>こちら</span>를 써요. <span class='gd-jp'>これ</span>로 사람을 가리키면 사람을 물건 취급하는 것 같아서 매우 무례해요.</div><div class='gd-h'>비슷하게 생긴 말과 구별하기</div><div class='gd-sec'><b>これ</b>와 <b>この</b>: 둘 다 '이'라는 뜻이지만, 뒤에 무엇이 오는지가 달라요.<br><span class='gd-jp'>これは私の本です。</span>（이건 제 책이에요）<br><span class='gd-jp'>この本は私のです。</span>（이 책은 제 거예요）<br>첫 문장의 <span class='gd-jp'>これ</span> 뒤에는 「は」가 오고, 둘째 문장의 <span class='gd-jp'>この</span> 뒤에는 「本」가 와요.</div><div class='gd-sec'><b>どれ</b>와 <b>どちら</b>: 둘 다 '어느 것'이라는 뜻이지만, 고를 수 있는 선택지 수가 달라요.<br><span class='gd-jp'>この三つの中で、どれがいいですか。</span>（이 세 개 중에서 어느 게 좋아요?）<br><span class='gd-jp'>コーヒーと紅茶、どちらがいいですか。</span>（커피와 홍차 중 어느 쪽이 좋아요?）<br>세 개 이상 중에서 고를 때는 どれ, 두 개 중 하나를 고를 때는 どちら를 써요.</div><div class='gd-warn'>판단 요령: 바로 뒤에 명사가 오면 この, 뒤에 「は」「が」가 오면 これ예요. 세 개 이상에서 고를 때는 どれ, 둘 중 하나일 때는 どちら예요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>「ど」로 시작하는 그룹은 사실 질문할 때 쓰는 말이에요. 이어서 '의문사'를 배우면서 <span class='gd-jp'>だれ</span>, <span class='gd-jp'>なに</span>, <span class='gd-jp'>いつ</span>도 함께 익혀 보세요.</div>","n5-65":"<div class='gd-h'>한마디로 이해하기</div><div class='gd-sec'>한국어도 '종이 한 <b>장</b>, 연필 한 <b>자루</b>, 고양이 한 <b>마리</b>'처럼 물건을 셀 때 중간에 '장, 자루, 마리' 같은 말을 넣어요. 일본어도 똑같고, 이런 말을 <b>조수사</b>(수를 세는 말)라고 해요. 나누는 방식도 한국어와 비슷해요. 얇고 평평한 것은 <span class='gd-jp'>枚</span>, 가늘고 긴 것은 <span class='gd-jp'>本</span>를 써요. '대략'이라고 말하고 싶으면 수량 뒤에 <span class='gd-jp'>くらい</span>를 붙여요.</div><div class='gd-h'>먼저 이 조수사들부터 기억하기</div><div class='gd-sec'><span class='gd-tag'>つ</span>일반적인 물건에 두루 쓸 수 있어서, 어떤 조수사를 써야 할지 모를 때 가장 만능이에요. 주문할 때도 자주 써요. 1부터 10까지는 따로 외워야 해요: <span class='gd-jp'>ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお</span>. 한국어의 '하나, 둘, 셋…'과 비슷하게 10까지만 써요. 10을 넘으면 つ는 쓰지 않아요.</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごを3つ買いました。</span>（사과를 3개 샀어요）</div><div class='gd-sec'><span class='gd-tag'>人</span>사람을 셀 때 써요. 1명, 2명은 읽는 법이 특별해요: <span class='gd-jp'>ひとり、ふたり</span>. 3명부터는 <span class='gd-jp'>さんにん</span>, 4명은 <span class='gd-jp'>よにん</span>이에요.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族は4人です。</span>（우리 가족은 4명이에요）</div><div class='gd-sec'><span class='gd-tag'>本</span>가늘고 긴 것: 펜, 병, 우산, 바나나.</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆を1本貸してください。</span>（연필 한 자루 빌려주세요）</div><div class='gd-sec'><span class='gd-tag'>枚</span>얇고 평평한 것: 종이, 우표, 셔츠, 접시.</div><div class='gd-ex-line'>・<span class='gd-jp'>切手を5枚ください。</span>（우표 5장 주세요）</div><div class='gd-sec'><span class='gd-tag'>匹</span>고양이, 개, 물고기 같은 작은 동물.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちに猫が2匹います。</span>（우리 집에 고양이가 2마리 있어요）</div><div class='gd-sec'>그 밖에 자주 보는 것으로는, 책은 <span class='gd-jp'>冊</span>, 자동차나 TV 같은 기계는 <span class='gd-jp'>台</span>, 잔에 담긴 음료는 <span class='gd-jp'>杯</span>를 써요.</div><div class='gd-h'>문장에 넣는 법</div><div class='gd-sec'>가장 자연스러운 순서는 <b>물건＋を(또는 が)＋수량＋동사</b>예요. 수량은 동사 바로 앞에 놓고, 뒤에 조사를 더 붙이지 않아요.<br>한국어로 '사과를 세 개 샀어요'라고 하듯이, 일본어도 <span class='gd-jp'>りんごを3つ買います</span>처럼 물건을 먼저 말하고 수량을 나중에 말해요. 한국어와 어순이 같아요.<br>'몇 개'인지 물을 때는 숫자 자리에 <span class='gd-jp'>何</span>를 넣어요: <span class='gd-jp'>何人</span>（なんにん）, <span class='gd-jp'>何本</span>（なんぼん）, <span class='gd-jp'>何枚</span>（なんまい）. つ로 세는 물건은 <span class='gd-jp'>いくつ</span>로 물어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄弟は何人いますか。</span>（형제자매가 몇 명이에요?）</div><div class='gd-h'>시간 말하는 법</div><div class='gd-sec'><span class='gd-jp'>時</span>는 '몇 시', <span class='gd-jp'>時間</span>은 '몇 시간'이에요. 한국어의 '시'와 '시간'의 구분과 같아요. <span class='gd-jp'>2時</span>는 2시, <span class='gd-jp'>2時間</span>은 2시간이에요.<br>분을 나타내는 <span class='gd-jp'>分</span>는 읽는 법이 바뀌니까 외워 두세요: <span class='gd-jp'>いっぷん、にふん、さんぷん、よんぷん、ごふん、ろっぷん、ななふん、はっぷん、きゅうふん、じゅっぷん</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日7時間寝ます。</span>（매일 7시간 자요）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩いて10分くらいです。</span>（역까지 걸어서 10분쯤이에요）</div><div class='gd-ex-line'>・<span class='gd-jp'>1時間くらいかかります。</span>（1시간쯤 걸려요）</div><div class='gd-sec'><span class='gd-jp'>くらい</span>와 <span class='gd-jp'>ぐらい</span>는 뜻이 같아서 어느 쪽을 써도 돼요.</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<b>'대략'은 '약 1시간'처럼 앞에 두지 않아요</b>: 한국어의 '1시간쯤', '1시간 정도'처럼 일본어도 <span class='gd-jp'>1時間くらい</span>라고 해서 くらい를 <b>뒤</b>에 붙여요.<br>・수량 뒤에 を를 또 붙이지 마세요: <span class='gd-jp'>りんごを3つ買いました</span>가 맞고, 「りんごを3つを買いました」는 틀려요.<br>・<span class='gd-jp'>本</span>와 <span class='gd-jp'>匹</span>는 읽는 법이 바뀌어요: <span class='gd-jp'>1本</span>いっぽん、<span class='gd-jp'>3本</span>さんぼん、<span class='gd-jp'>6本</span>ろっぽん；<span class='gd-jp'>1匹</span>いっぴき、<span class='gd-jp'>3匹</span>さんびき.<br>・1명, 2명은 ひとり、ふたり이고, 「いちにん」「ににん」이 아니에요.<br>・4시는 <span class='gd-jp'>4時</span>（よじ）, 9시는 <span class='gd-jp'>9時</span>（くじ）예요. よんじ、きゅうじ라고 읽지 않도록 주의하세요.<br>・사람을 셀 때는 반드시 <span class='gd-jp'>人</span>를 써요. つ는 쓸 수 없어요.</div><div class='gd-h'>비슷하게 생긴 말과 구별하기</div><div class='gd-sec'>한국어는 '3시간쯤', '3시쯤'처럼 둘 다 '쯤'을 쓰지만, 일본어는 무엇 뒤에 붙는지에 따라 나눠 써요.<br><b>くらい</b>는 <b>얼마나 오래, 얼마나 많이</b> 뒤에 붙어요: <span class='gd-jp'>3時間くらい待ちました。</span>（3시간쯤 기다렸어요）<br><b>ごろ</b>는 <b>몇 시, 며칠</b> 같은 시점 뒤에 붙어요: <span class='gd-jp'>3時ごろ着きます。</span>（3시쯤 도착해요）<br>회화에서는 「3時くらい」도 들을 수 있지만, 반대로 「3時間ごろ」라고 하면 틀려요.</div><div class='gd-warn'>판단 요령: '얼마나 오래, 얼마나 많이'의 대략은 くらい, '몇 시'의 대략은 ごろ를 써요.</div><div class='gd-h'>다 배우고 나서 이어서 배울 것</div><div class='gd-sec'>수량 뒤에 <span class='gd-jp'>だけ</span>를 붙이면 '이만큼만'이라는 뜻이 돼요: <span class='gd-jp'>1つだけください。</span>（하나만 주세요）</div>","n5-66":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>부사는 동사나 형용사 앞에 놓여서 <b>「얼마나 ～」「얼마나 많이」「얼마나 자주 ～」</b>를 덧붙여 주는 작은 말이에요. 한국어의 「아주 맛있어요」의 「아주」, 「자주 가요」의 「자주」, 「별로 안 마셔요」의 「별로」가 일본어에서는 모두 부사예요. 이 카드는 <b>정도</b>, <b>수량</b>, <b>빈도</b> 세 가지로 나눠서 알아봐요.</div><div class='gd-h'>언제 쓸까요</div><div class='gd-sec'><span class='gd-tag'>정도: 아주</span><span class='gd-jp'>とても</span>＝아주, 매우. 형용사 앞에 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(아주 즐거웠어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはとてもおいしいです。</span>(이 라멘은 아주 맛있어요)</div><div class='gd-sec'><span class='gd-tag'>수량: 많이</span><span class='gd-jp'>たくさん</span>＝많이. 「양」을 말할 때 써요. 동사 앞에 쓰거나 「たくさんの＋명사」로 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はたくさん食べました。</span>(어제는 많이 먹었어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅にたくさんの人がいます。</span>(역에 사람이 많이 있어요)</div><div class='gd-sec'><span class='gd-tag'>빈도: 얼마나 자주 하는지</span>가장 자주 하는 것부터 전혀 안 하는 것까지 한 줄로 늘어놓으면 이래요.<br><b>いつも＞よく＞ときどき＞たまに＞あまり～ない＞全然～ない</b></div><div class='gd-ex-line'>・<span class='gd-jp'>いつも7時に起きます。</span>(저는 항상 7시에 일어나요)</div><div class='gd-ex-line'>・<span class='gd-jp'>よくこの店に来ます。</span>(저는 이 가게에 자주 와요)</div><div class='gd-ex-line'>・<span class='gd-jp'>ときどき料理をします。</span>(저는 가끔 요리를 해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに映画を見ます。</span>(저는 어쩌다 한 번 영화를 봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビはあまり見ません。</span>(저는 텔레비전을 별로 안 봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は全然飲みません。</span>(저는 술을 전혀 안 마셔요)</div><div class='gd-sec'><span class='gd-tag'>よく의 또 다른 뜻</span><span class='gd-jp'>よく</span>는 「자주」 말고도 「잘, 충분히」라는 뜻이 있어요. 뒤에 오는 동사를 보면 어느 쪽인지 알 수 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(어제는 잘 잤어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、よく分かりません。</span>(죄송해요, 잘 모르겠어요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・<span class='gd-jp'>あまり</span>, <span class='gd-jp'>全然</span> 뒤에는 꼭 <b>부정</b>이 와야 해요. 「<span class='gd-jp'>あまり好きです</span>」는 틀린 말이고, <span class='gd-jp'>あまり好きじゃないです</span>(별로 안 좋아해요)라고 해야 해요.<br>・한국어의 「별로 맛없어요」를 「とても」에 부정을 붙여서 옮기면 안 돼요. <span class='gd-jp'>あまりおいしくないです</span>라고 해야 해요.<br>・한국어의 「아주」와 「많이」처럼 일본어도 둘을 구분해요. 「아주 맛있어요」는 とても, 「사람이 많이 있어요」는 たくさん을 써요. 「とても人がいます」는 틀린 말이고, <span class='gd-jp'>人がたくさんいます</span>라고 해야 해요.<br>・일본 젊은 사람들이 「<span class='gd-jp'>全然大丈夫</span>」(전혀 문제없어)라고 말하는 걸 들을 수도 있어요. 이건 구어체 표현이에요. 교재와 시험에서는 우선 「全然＋부정」으로 외워 두세요.<br>・부사는 보통 꾸며 주는 동사나 형용사 앞에 놓아요. <span class='gd-jp'>よく行きます</span>처럼 쓰고, よく를 문장 끝에 두지 마세요.</div><div class='gd-h'>비슷한 말과 구분하기</div><div class='gd-sec'><b>あまり～ない</b>＝별로 ～하지 않다. 조금은 해요: <span class='gd-jp'>お酒はあまり飲みません。</span>(술은 별로 안 마셔요. 가끔 조금은 마셔요)<br><b>全然～ない</b>＝전혀 ～하지 않다. 조금도 안 해요: <span class='gd-jp'>お酒は全然飲みません。</span>(술을 전혀 안 마셔요)<br><span class='gd-jp'>よく行きますか。</span>(자주 가요?)라고 물으면, 가끔 갈 때는 <span class='gd-jp'>いいえ、あまり行きません。</span>, 한 번도 안 갈 때만 <span class='gd-jp'>いいえ、全然行きません。</span>이라고 답해요.</div><div class='gd-warn'>판단 요령: 한국어로 「별로」라고 하고 싶으면 あまり, 「전혀」라고 하고 싶으면 全然을 써요. 둘 다 뒤에 부정이 와야 해요.</div><div class='gd-h'>익힌 다음에 배울 것</div><div class='gd-sec'>형용사도 부사로 바꿀 수 있어요. 예를 들면 <span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早く</span></span>: <span class='gd-jp'>早く起きます。</span>(일찍 일어나요). 이어서 「형용사의 부사 용법」도 살펴보세요.</div>","n5-67":"<div class='gd-h'>한 줄로 먼저 이해하기</div><div class='gd-sec'>이 카드는 일본어를 <b>실제 사람이 말하는 것처럼</b> 들리게 해 주는 세 가지 작은 말을 다뤄요.<br><b>접속사</b>＝한국어의 「그리고, 게다가, 하지만, 그래서」처럼 둘째 문장 맨 앞에 놓아서 두 문장을 이어 줘요.<br><b>감동사</b>＝「네, 아니요, 저기…, 음…」처럼 대답하거나 말문을 열 때 내는 소리예요.<br><b>의성어·의태어</b>＝「멍멍, 주룩주룩, 방긋방긋」처럼 소리나 모습을 흉내 내는 말이에요. 한국어에도 많지만 일본어는 더 자주 써요.</div><div class='gd-h'>접속사: 두 문장 이어 주기</div><div class='gd-sec'>쓰는 법은 간단해요. 첫 문장을 끝내고, 둘째 문장 앞에 접속사를 놓아요. 뒤에는 보통 쉼표「、」를 붙여요.</div><div class='gd-sec'><span class='gd-tag'>そして</span>그리고, 게다가. 같은 방향의 내용을 덧붙일 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いです。そして、おいしいです。</span>(이 가게는 싸요. 그리고 맛있어요)</div><div class='gd-sec'><span class='gd-tag'>それから</span>그러고 나서, 그리고 또. 다음에 한 일을 말하거나 「또 ～」를 덧붙일 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンを買いました。それから、牛乳も買いました。</span>(빵을 샀어요. 그리고 우유도 샀어요)</div><div class='gd-sec'><span class='gd-tag'>でも</span>하지만. 앞과 반대되는 내용을 말할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいです。でも、おもしろいです。</span>(일본어는 어려워요. 하지만 재미있어요)</div><div class='gd-sec'><span class='gd-tag'>だから</span>그래서. 앞은 원인, 뒤는 결과예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>(비가 왔어요. 그래서 안 갔어요)</div><div class='gd-h'>감동사: 대답하기와 말문 열기</div><div class='gd-sec'><span class='gd-tag'>はい・いいえ</span>네／아니요.</div><div class='gd-ex-line'>・<span class='gd-jp'>「学生ですか。」「はい、そうです。」</span>(「학생이에요?」「네, 맞아요」)</div><div class='gd-sec'><span class='gd-tag'>あのう</span>사람을 부르거나 뭔가 물어보려고 말문을 열 때 써요. 「실례합니다」 같은 느낌이 조금 있어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>あのう、すみません。駅はどこですか。</span>(저기… 죄송한데요, 역이 어디예요?)</div><div class='gd-sec'><span class='gd-tag'>ええと</span>생각하면서 말할 때 써요. 한국어의 「음…」과 비슷해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ええと、三つください。</span>(음… 세 개 주세요)</div><div class='gd-h'>의성어·의태어: 소리와 모습 흉내 내기</div><div class='gd-sec'><b>의성어</b>는 실제 소리를 흉내 낸 말이고, <b>의태어</b>는 소리로 모습이나 느낌을 나타낸 말이에요. 보통 같은 소리를 두 번 반복해요.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨がザーザー降っています。</span>(비가 주룩주룩 내리고 있어요: 의성어)</div><div class='gd-ex-line'>・<span class='gd-jp'>犬がワンワン鳴いています。</span>(개가 멍멍 짖고 있어요: 의성어)</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がぺこぺこです。</span>(배가 너무 고파요: 의태어)</div><div class='gd-sec'>그 밖에 <span class='gd-jp'>ゆっくり</span>(천천히), <span class='gd-jp'>はっきり</span>(또렷하게)는 동작의 모습을 나타내는 부사예요. 소리를 흉내 내는 말은 아니지만 이것도 아주 자주 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>ゆっくり話してください。</span>(천천히 말해 주세요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・접속사는 <b>둘째 문장 맨 앞</b>에 놓아야 하고, 문장 중간에 끼워 넣으면 안 돼요. <span class='gd-jp'>高いです。でも、買います。</span>는 괜찮지만, 「高いでも買います」라고는 말할 수 없어요.<br>・<span class='gd-jp'>だから</span>로 말을 시작해서 「言ったでしょう」를 잇는 「だから、言ったでしょう」는 「내가 말했잖아」라는 짜증 섞인 말투예요. 윗사람에게는 쓰지 마세요.<br>・보통 「그래서」라는 뜻으로 쓸 때, 윗사람에게나 격식 있는 자리에서는 <span class='gd-jp'>だから</span>를 좀 더 공손한 <span class='gd-jp'>ですから</span>로 바꿔 쓸 수 있어요.<br>・감동사 <span class='gd-jp'>あのう</span>(<span class='gd-jp'>あの</span>, <span class='gd-jp'>あのー</span>로도 써요)와 지시사 <span class='gd-jp'>あの</span>(저＋명사)는 뿌리는 같지만 쓰임새가 달라요. 사람을 부를 때는 「あの、すみません」라고 해도 되고 살짝 늘여서 「あのう…」라고 해도 돼요. 늘이면 망설이는 느낌과 「실례합니다」 같은 느낌이 조금 더 커져요.<br>・<span class='gd-jp'>はい</span>는 「네」만 뜻하는 게 아니에요. 이름이 불렸을 때 <span class='gd-jp'>はい</span>라고 하면 「네, 여기 있어요」라는 뜻이에요.</div><div class='gd-h'>비슷한 말과 구분하기</div><div class='gd-sec'>「비싸지만 살 거예요」라는 같은 상황도 두 가지로 말할 수 있어요.<br><span class='gd-jp'>高いです。でも、買います。</span>(두 문장. <b>でも</b>로 둘째 문장을 시작해요)<br><span class='gd-jp'>高いですが、買います。</span>／<span class='gd-jp'>高いけど、買う。</span>(한 문장. <b>が・けど</b>가 앞 절 끝에 붙어요)<br><br>「비가 와서 안 갔어요」도 마찬가지예요.<br><span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>(두 문장. <b>だから</b>를 써요)<br><span class='gd-jp'>雨が降ったから、行きませんでした。</span>(한 문장. <b>から</b>가 원인 뒤에 붙어요)</div><div class='gd-warn'>판단 요령: <b>でも・だから</b>는 새 문장의 맨 앞에 서고, <b>が・けど・から</b>는 앞 문장의 끝에 붙어요. 앞에 마침표가 있는지 보면 어느 쪽을 써야 할지 알 수 있어요.</div>","n5-68":"<div class='gd-h'>한 문장으로 먼저 이해하기</div><div class='gd-sec'>「AというB」는 한국어의 <b>‘A라는 B’</b>예요. 친구에게 ‘홍대에 ○○라는 가게가 있어’라고 말하는 것처럼, 일본어에서는 「という」로 가게 이름과 「店」를 이어요. 상대가 그 이름을 <b>모를 수도 있을 때</b> 소개하는 표현이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>이름(명사 A)＋という＋그게 무엇인지(명사 B)<br><span class='gd-pair'><span class='gd-jp'>村田</span> ＋ <span class='gd-jp'>人</span> → <span class='gd-jp'>村田という人</span></span>(村田라는 사람)<br><span class='gd-pair'><span class='gd-jp'>さくら</span> ＋ <span class='gd-jp'>店</span> → <span class='gd-jp'>さくらという店</span></span>(さくら라는 가게)<br>뒤의 B에는 보통 「人、店、町、食べ物、ドラマ、本」처럼 ‘어떤 종류의 것인지’ 알려 주는 단어가 와요.</div><div class='gd-h'>언제 쓸까요?</div><div class='gd-sec'><span class='gd-tag'>이름 소개하기</span>상대가 들어 본 적 없을 만한 사람, 가게, 작품, 음식을 말할 때 써요.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前に「さくら」という喫茶店があります。</span>(역 앞에 「さくら」라는 카페가 있어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>山田という人から電話がありました。</span>(山田라는 사람에게서 전화가 왔어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>小籠包という食べ物を知っていますか。</span>(小籠包라는 음식을 알아요?)</div><div class='gd-sec'><span class='gd-tag'>이름 묻기</span>이름을 모르는 것은 <span class='gd-jp'>何という</span>로 물어요. 여기서 「何」는 <b>なん</b>이라고 읽어요.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何という花ですか。</span>(이건 무슨 꽃이에요? 이름이 뭐예요?)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・という 뒤에는 <b>반드시 명사</b>가 와야 해요. 「さくらというです」라고 하면 안 되고, 끝까지 말해야 해요: <span class='gd-jp'>さくらという店です</span>.<br>・모두가 아는 것에는 붙이지 않아요. 일본 사람에게 「富士山という山」라고 하면 ‘富士山라는 산이 있는데, 모르시죠?’ 하는 느낌이라 어색해요.<br>・「いう」는 실제로 <b>ゆう</b>처럼 발음하는 경우가 많지만, 쓸 때는 그래도 「いう」라고 써요. 「とゆう」라고 쓰면 안 돼요.<br>・이 「いう」는 보통 히라가나로 쓰고, 한자 「言う」로는 잘 쓰지 않아요.</div><div class='gd-h'>비슷한 표현과 구분하기</div><div class='gd-sec'><b>という</b>＝~라는: <span class='gd-jp'>村田という人</span>(이름이 村田인 사람)<br><b>の</b>＝~의, ~쪽의: <span class='gd-jp'>村田さんの友達</span>(村田 씨의 친구)<br>한국어에서도 ‘라는’과 ‘의’는 다르니까 구분하기 어렵지 않을 거예요. 다만 「村田の人」라고 하면 ‘村田 집안/村田 쪽 사람’이라는 뜻이 되어서, ‘이름이 村田’라는 뜻은 아니에요.</div><div class='gd-sec'>그리고 자기소개에서 자주 듣는 <span class='gd-jp'>林といいます。</span>(저는 林예요)는 ‘~라고 해요’를 <b>문장 끝</b>에 두는 형태라서 뒤에 명사가 오지 않아요.<br><span class='gd-jp'>林といいます。</span>(저는 林라고 해요)<br><span class='gd-jp'>林という人がいます。</span>(林라는 사람이 있어요)<br>자기 이름을 말할 때는 <b>さん을 붙이면 안 돼요</b>. 「林さんといいます」는 틀린 문장이에요.</div><div class='gd-warn'>판단 요령: 한국어로 ‘<b>~라는</b>’이면 という, 그냥 ‘~의’나 ‘~쪽의’이면 の를 써요.</div><div class='gd-h'>익힌 다음에 이어서 배우기</div><div class='gd-sec'>‘이건 일본어로 뭐라고 해요?’라고 물을 때: <span class='gd-jp'>これは日本語で何といいますか。</span>(이건 일본어로 뭐라고 해요?)</div>","n5-30":"<div class='gd-h'>한 줄 요약</div><div class='gd-sec'>「に」는 <b>사람</b> 뒤에 붙어서, 그 동작을 <b>누구에게</b> 하는지 나타내요. 한국어도 \"친구<b>에게</b> 전화하다\", \"선생님<b>께</b> 묻다\", \"엄마<b>한테</b> 말하다\"처럼 조사가 상황마다 달라지죠. 일본어는 더 단순해서, 그 사람 뒤에 「に」만 붙이면 끝이에요.</div><div class='gd-h'>접속 방법</div><div class='gd-sec'>기본 순서는 <b>사람＋に</b>　<b>물건＋を</b>　<b>동사</b>예요.<br>먼저 누구에게 하는지, 그다음 무엇을, 마지막에 동작을 말해요.<br><span class='gd-jp'>母に</span>(엄마에게)＋<span class='gd-jp'>花を</span>(꽃을)＋<span class='gd-jp'>あげます</span>(드려요) → <span class='gd-jp'>母に花をあげます。</span><br>동작에 '물건'이 없으면 바로 「사람＋に＋동사」로 말해요: <span class='gd-jp'>友達に電話します。</span>(친구에게 전화해요)</div><div class='gd-h'>가장 자주 듣는 형태</div><div class='gd-sec'><span class='gd-tag'>물건을 누군가에게 주기</span>주기, 빌려주기, 보여 주기예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>母に花をあげます。</span>(엄마에게 꽃을 드려요)</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を貸しました。</span>(여동생에게 책을 빌려줬어요)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に写真を見せます。</span>(친구에게 사진을 보여 줘요)</div><div class='gd-sec'><span class='gd-tag'>누군가에게 말하기, 연락하기</span>전화하기, 편지 쓰기, 질문하기예요.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に電話します。</span>(친구에게 전화해요)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に聞きます。</span>(선생님께 여쭤봐요)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに手紙を書きました。</span>(다나카 씨에게 편지를 썼어요)</div><div class='gd-sec'><span class='gd-tag'>누군가를 가르치기</span></div><div class='gd-ex-line'>・<span class='gd-jp'>弟に英語を教えます。</span>(남동생에게 영어를 가르쳐요)</div><div class='gd-h'>헷갈리기 쉬운 부분</div><div class='gd-warn'>・한국어에서는 \"친구를 만나요\"처럼 사람 뒤에 '를'을 쓰는 동사가 있어서, 일본어에서도 무심코 を를 붙이는 경우가 많아요. <span class='gd-jp'>友達を会います</span>는 틀린 문장이고, <span class='gd-jp'>友達に会います</span>라고 해야 해요. <span class='gd-jp'>先生を聞きます</span>도 틀린 문장이고, <span class='gd-jp'>先生に聞きます</span>라고 해야 해요. 다만 <span class='gd-jp'>友達を待ちます</span>(친구를 기다려요)처럼 사람 뒤에 を를 쓰는 동사도 있어요. 그러니 동사마다 예문과 함께 외우고, 한국어 조사로 짐작하지 마세요.<br>・に 뒤의 사람이 <b>꼭 물건을 받는 사람은 아니에요</b>. '빌리다', '배우다' 같은 동작에서는 に의 사람이 오히려 물건이 오는 쪽이에요: <span class='gd-jp'>友達に本を借りました。</span>(친구에게 책을 빌렸어요), <span class='gd-jp'>先生に日本語を習います。</span>(선생님께 일본어를 배워요)<br>・「に」에는 다른 용법도 있어요. 시간(<span class='gd-jp'>7時に</span>)이나 장소(<span class='gd-jp'>東京に</span>)가 그 예예요. 앞에 무엇이 오는지 보세요. 앞이 <b>사람</b>이면 대개 이 카드의 용법이에요.</div><div class='gd-h'>비슷하게 생긴 표현과 구분하기</div><div class='gd-sec'>한국어의 '~와/랑'과 '~에게/한테' 때문에 <b>に</b>와 <b>と</b>가 헷갈리기 쉬워요.<br><span class='gd-jp'>友達に話します。</span>(친구에게 이야기해요: 내가 말하고 상대는 듣는 <b>일방향</b>이에요)<br><span class='gd-jp'>友達と話します。</span>(친구와 이야기해요: 두 사람이 주고받으며 <b>함께</b> 해요)<br>똑같이 '친구와 말하다'라도, に를 쓰면 내가 상대에게 말하는 것이고, と를 쓰면 우리가 함께 대화하는 거예요.</div><div class='gd-warn'>구분 팁: 한국어로 '~와 함께'로 바꿀 수 있으면 と, '~에게/한테'로만 바꿀 수 있으면 に를 써요.</div><div class='gd-h'>다음에 배우면 좋은 것</div><div class='gd-sec'>'누가 누구에게 무엇을 주는지' 말하는 <span class='gd-jp'>あげます</span>, <span class='gd-jp'>もらいます</span>, <span class='gd-jp'>くれます</span> 같은 표현에도 계속 이 「に」가 나와요. 이어서 수수 동사를 배워 보세요.</div>"});
